async function dependencias() {
  app.innerHTML = `
    ${_htmlCabecalhoLista({ titulo: 'Dependências', sub: 'Dependências críticas reutilizáveis nos processos.',
      primario: { rotulo: '+ Nova dependência', onclick: 'abrirDrawerDependencia()' } })}
    ${_htmlBarraLista({ busca: { id: 'buscaDep', placeholder: 'Buscar dependência…' }, aoMudar: 'filtrarDependencias', contadorId: 'dependenciasContador',
      filtros: [{ id: 'filtroDepCategoria', rotulo: 'Categoria', opcoes: [] }] })}
    ${_seVeTela('fornecedores', `<details class="lista-ajuda"><summary>Fornecedores nesta lista</summary>
      <p>Os fornecedores aparecem neste catálogo, mas são editados e avaliados em <a href="#fornecedores">Fornecedores</a>. Clique num fornecedor para gerenciá-lo lá.</p></details>`)}
    <div class="loading">⏳ Carregando...</div>
    <div class="data-table data-table--lista" id="listaDeps" style="display:none;">
      <table style="min-width:900px;">
        <colgroup><col style="width:280px"><col style="width:180px"><col style="width:420px"><col style="width:92px"></colgroup>
        <thead>
          <tr>
            <th onclick="ordenarDependencias('nome')" style="cursor:pointer;">Nome <span id="sort-dep-nome"></span></th>
            <th onclick="ordenarDependencias('categoria')" style="cursor:pointer;">Categoria <span id="sort-dep-categoria"></span></th>
            <th>Papel</th>
            <th class="col-acoes">Ações</th>
          </tr>
        </thead>
        <tbody id="depRows"></tbody>
      </table>
    </div>
    <div id="dependenciasPaginacao"></div>
    ${_htmlDrawerDependencia()}`;

  try {
    // Fornecedores VOLTAM a aparecer aqui (so a edicao/avaliacao mora na tela
    // Fornecedores -- clicar numa linha de fornecedor redireciona pra la, ver
    // renderizarDependencias/irParaFornecedor). Pessoa continua fora: o
    // <select> fixo de categoria (so as 7 tecnicas) nao teria como
    // mostrar/editar uma linha de categoria "Pessoas" corretamente. O filtro
    // e aqui, e nao no banco, para que o catalogo continue inteiro -- e o
    // mesmo de que os processos dependem.
    const [todas, areas] = await Promise.all([API.getDependencias(), API.getAreas()]);
    // Fornecedor inativo fica só na aba Inativos de Fornecedores (27/10/2026).
    dependenciasData = todas.filter(d => !['Pessoas', 'Pessoa'].includes(d.categoria) && _fornecedorAtivo(d));
    // Fonte do select "Area Responsavel" na aba DRP -- mesmo catalogo que
    // Areas/Fornecedor ja usam.
    window.areasData = areas;
  } catch (e) {
    console.error('dependencias: falha ao carregar', e);
    document.querySelector('.loading').outerHTML = _htmlErroCarga('Não foi possível carregar as dependências.', 'dependencias');
    return;
  }
  document.querySelector('.loading').style.display = 'none';
  document.getElementById('listaDeps').style.display = 'block';
  // Popular filtro de categorias
  const cats = [...new Set(dependenciasData.map(d => d.categoria))].sort();
  _preencherFiltroLista('filtroDepCategoria', 'Categoria', cats.map((c) => [c, c]));
  renderizarDependencias();
}

function renderizarDependencias() {
  let data = [...dependenciasData];

  // Filtrar por categoria
  const filtro = document.getElementById('filtroDepCategoria');
  if (filtro && filtro.value) {
    data = data.filter(d => d.categoria === filtro.value);
  }

  // Filtrar por busca
  const busca = (document.getElementById('buscaDep') || {}).value || '';
  if (busca.trim()) {
    const termo = busca.toLowerCase();
    data = data.filter(d =>
      (d.nome || '').toLowerCase().includes(termo) ||
      (d.categoria || '').toLowerCase().includes(termo) ||
      (d.detalhes || '').toLowerCase().includes(termo)
    );
  }

  data = dependenciasOrdenacao.aplicar(data);
  dependenciasOrdenacao.atualizarSetas('sort-dep-', ['categoria', 'nome']);

  _atualizarBarraLista('dependenciasContador', data.length, ['dependência', 'dependências']);
  const pag = dependenciasPaginacao.aplicar(data);
  const pagEl = document.getElementById('dependenciasPaginacao');
  if (pagEl) pagEl.innerHTML = _htmlPaginacao(pag, 'irParaPaginaDependencias');
  const filtrando = !!(busca.trim() || (filtro && filtro.value));
  document.getElementById('depRows').innerHTML = pag.itens.length
    ? pag.itens.map(d => {
        // Fornecedor e uma linha de /dependencias com categoria Fornecedores,
        // mas a edicao/avaliacao mora na tela Fornecedores: clicar redireciona
        // pra la (irParaFornecedor) e o excluir nao age aqui (fornecedores tem
        // avaliacoes atreladas, geridas la).
        const ehForn = Perfis.categoriaDeFornecedor(d.categoria);
        // Fornecedor é gerido em Fornecedores: quem não vê essa tela (TI) só consulta a linha.
        const veForn = Perfis.podeVerTela(window.USER_PERFIS, 'fornecedores');
        const id = escJs(d.id);
        const acao = ehForn ? (veForn ? `irParaFornecedor('${id}')` : '') : `editarDep('${id}')`;
        const acoes = ehForn
          ? (veForn ? [{ icone: SVG_EDITAR, titulo: 'Gerenciar em Fornecedores', onclick: `irParaFornecedor('${id}')` }] : [])
          : [_acaoEditar(`editarDep('${id}')`), _acaoExcluir(`excluirDep('${id}')`)];
        return `<tr style="cursor:pointer;" onclick="${acao}">
        ${_tdLista(d.nome, 'forte')}
        <td title="${esc(d.categoria)}"><span class="badge badge-red">${esc(d.categoria)}</span></td>
        ${ehForn ? '<td class="muted">Gerenciado em Fornecedores</td>' : _tdLista(d.detalhes)}
        ${_htmlAcoesLinha(acoes)}
      </tr>`;
      }).join('')
    : `<tr><td colspan="4" class="vazio">${filtrando ? 'Nenhuma dependência encontrada com esses filtros.' : 'Nenhuma dependência cadastrada.'}</td></tr>`;
}

/** Fornecedor é linha de /dependencias, mas editado/avaliado na tela Fornecedores.
 *  Guarda o id pra abrir o cadastro ao chegar lá (ver fornecedores()) e navega. */
window.irParaFornecedor = (id) => {
  window._abrirFornecedorAoCarregar = id || null;
  window.location.hash = 'fornecedores';
};

const dependenciasPaginacao = criarPaginacao(20);
window.filtrarDependencias = () => { dependenciasPaginacao.reiniciar(); renderizarDependencias(); };
window.irParaPaginaDependencias = (delta) => { dependenciasPaginacao.mover(delta); renderizarDependencias(); };

window.ordenarDependencias = (coluna) => {
  dependenciasOrdenacao.ordenar(coluna);
  filtrarDependencias();
};

// ============================================================
// Aba DRP da Dependência -- 6 listas guiadas (Critérios de Acionamento,
// Pré-requisitos, Health Check, Runbook, Critérios de Retorno, Limitações),
// além dos campos fixos (RTO/RPO/Estratégia/Responsável), da seção
// "Dependências" (seletor do catálogo, ver _htmlDrpDependencias) e de "Testes
// do Procedimento" (registro único, ver _htmlDrpTestes). Item de lista e uma
// frase curta, sem sub-campo -- por isso e um array de string simples, nao o
// objeto {categoria,...} que outras listas do app usam (Plano de Ação, KRIs,
// Pessoas Associadas). Todas as listas numeram os itens e permitem
// reordena-los com as setas ▲/▼ -- mesmo padrao do Runbook; a ordem gravada
// e a que o usuario definir em qualquer uma delas.
// ============================================================
window._depDrpListas = { drpCriteriosAcionamento: [], drpPreRequisitos: [], drpHealthCheck: [], drpRunbook: [], drpCriteriosRetorno: [], drpLimitacoes: [] };
window._depDrpEditando = { drpCriteriosAcionamento: null, drpPreRequisitos: null, drpHealthCheck: null, drpRunbook: null, drpCriteriosRetorno: null, drpLimitacoes: null };

/** Bloco de uma lista guiada da aba DRP: label + lista renderizada + caixa de adicionar. */
function _htmlDrpLista(campo, titulo, placeholder) {
  return `
    <div style="border-top:1px solid #eee;margin-top:18px;padding-top:14px;">
      <label style="display:block;font-size:0.78em;font-weight:700;color:#444;text-transform:uppercase;letter-spacing:0.4px;margin-bottom:8px;">${esc(titulo)}</label>
      <div id="lista-${campo}"></div>
      <div style="display:flex;gap:8px;margin-top:8px;">
        <input type="text" id="novoItem-${campo}" placeholder="${esc(placeholder)}" style="flex:1;padding:9px 12px;border:1.5px solid #e0e0e0;border-radius:7px;font-size:0.9em;box-sizing:border-box;">
        <button class="btn btn-ghost" id="btnAdicionar-${campo}" onclick="adicionarDrpItem('${campo}')" style="white-space:nowrap;">+ Adicionar</button>
      </div>
    </div>`;
}

function renderDrpLista(campo) {
  const container = document.getElementById('lista-' + campo);
  if (!container) return;
  const itens = window._depDrpListas[campo] || [];
  const comOrdem = true;
  container.innerHTML = itens.length ? itens.map((texto, i) => `
    <div style="display:flex;align-items:center;gap:8px;border:1px solid #e0e0e0;border-radius:7px;padding:8px 10px;margin-bottom:6px;">
      ${comOrdem ? `<span style="font-weight:700;color:#d60014;min-width:20px;">${i + 1}.</span>` : ''}
      <span style="flex:1;font-size:0.88em;color:#333;">${esc(texto)}</span>
      ${comOrdem ? `
        <button class="btn-icon" onclick="moverDrpItem('${campo}', ${i}, -1)" title="Mover para cima" ${i === 0 ? 'disabled' : ''}>▲</button>
        <button class="btn-icon" onclick="moverDrpItem('${campo}', ${i}, 1)" title="Mover para baixo" ${i === itens.length - 1 ? 'disabled' : ''}>▼</button>` : ''}
      <button class="btn-icon" onclick="editarDrpItem('${campo}', ${i})" title="Editar">
        <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="#ff6b35" stroke-width="2"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"/></svg>
      </button>
      <button class="btn-icon" onclick="removerDrpItem('${campo}', ${i})" title="Remover" style="color:#c62828;font-weight:700;">&times;</button>
    </div>`).join('') : '<p class="vazio-inline">Nenhum item adicionado ainda.</p>';
}

window.adicionarDrpItem = (campo) => {
  const input = document.getElementById('novoItem-' + campo);
  const texto = input.value.trim();
  if (!texto) return;
  const idx = window._depDrpEditando[campo];
  if (idx != null) {
    window._depDrpListas[campo][idx] = texto;
    window._depDrpEditando[campo] = null;
    document.getElementById('btnAdicionar-' + campo).textContent = '+ Adicionar';
  } else {
    window._depDrpListas[campo].push(texto);
  }
  input.value = '';
  renderDrpLista(campo);
};

window.editarDrpItem = (campo, idx) => {
  window._depDrpEditando[campo] = idx;
  document.getElementById('novoItem-' + campo).value = window._depDrpListas[campo][idx];
  document.getElementById('btnAdicionar-' + campo).textContent = 'Salvar alteração';
};

window.removerDrpItem = (campo, idx) => {
  window._depDrpListas[campo].splice(idx, 1);
  if (window._depDrpEditando[campo] === idx) window._depDrpEditando[campo] = null;
  renderDrpLista(campo);
};

window.moverDrpItem = (campo, idx, direcao) => {
  const lista = window._depDrpListas[campo];
  const alvo = idx + direcao;
  if (alvo < 0 || alvo >= lista.length) return;
  [lista[idx], lista[alvo]] = [lista[alvo], lista[idx]];
  renderDrpLista(campo);
};

window.trocarAbaDependencia = (aba) => {
  ['geral', 'drp', 'plano', 'registros', 'processos'].forEach(a => {
    document.getElementById('painel-dep-' + a).style.display = a === aba ? 'block' : 'none';
    _marcarAba(document.getElementById('tab-dep-' + a), a === aba);
  });
  // Ao entrar na aba Plano, re-renderiza o preview do DRP salvo.
  if (aba === 'plano') renderDrpResumo();
  if (aba === 'drp') _carregarSlasDependencia();
};

/**
 * SLAs contratados (15/10/2026): os contratos vigentes que cobrem esta
 * dependência, os mesmos que entram no DRP gerado. Vem do servidor
 * (obterSlasDependencia) -- quem opera DRP pode não ler `contratos` direto, e
 * o servidor só devolve os campos de SLA. Quem não opera DRP não vê o bloco.
 */
async function _carregarSlasDependencia() {
  const cont = document.getElementById('depSlasContratados');
  if (!cont) return;
  const id = (document.getElementById('depId') || {}).value || '';
  if (!id || !Perfis.podeOperarDRP(window.USER_PERFIS)) { cont.innerHTML = ''; return; }
  cont.innerHTML = '<div style="font-size:0.85em;color:#888;margin-bottom:14px;">⏳ Carregando SLAs contratados...</div>';
  let r;
  try {
    r = await API.getSlasDependencia(id);
  } catch (e) {
    console.error('Dependência: SLAs contratados não carregaram', e);
    cont.innerHTML = '';
    return;
  }
  if ((document.getElementById('depId') || {}).value !== String(id)) return;
  const fmt = ContratoCiclo.formatarDuracao;
  const contratos = (r && r.contratos) || [];
  const corpo = contratos.length
    ? contratos.map((c) => {
        const s = ContratoCiclo.normalizarSla(c.sla);
        const partes = c.temSla ? [
          s.cobertura ? `Atendimento ${s.cobertura === 'Outro' ? (s.coberturaDetalhe || 'outro') : s.cobertura}` : '',
          `RTO garantido ${fmt(s.rtoMin) || '—'}`,
          `RPO garantido ${fmt(s.rpoMin) || '—'}`,
          s.disponibilidadePct !== null ? `Disponibilidade ${String(s.disponibilidadePct).replace('.', ',')}%` : '',
        ].filter(Boolean) : ['SLA não cadastrado no contrato'];
        const chips = (c.incompatibilidades || []).map((i) => {
          const k = { perigo: ['#c62828', '#ffebee'], aviso: ['#f57c00', '#fff3e0'] }[i.nivel] || ['#1565c0', '#e3f2fd'];
          return `<span style="display:inline-block;margin:4px 4px 0 0;padding:2px 9px;border-radius:10px;font-size:0.74em;font-weight:700;color:${k[0]};background:${k[1]};">${esc(i.rotulo)}</span>`;
        }).join('');
        return `<div style="padding:8px 0;border-bottom:1px solid #eee;">
          <div style="font-weight:600;">${esc(c.codigo)} — ${esc(c.objeto)} <span style="color:#888;font-weight:400;">· ${esc(c.fornecedorNome || '')}${c.viaCobertura ? '' : ' · pelo fornecedor'}</span></div>
          <div style="font-size:0.85em;color:#555;">${esc(partes.join(' · '))}</div>${chips}
        </div>`;
      }).join('')
    : '<div style="font-size:0.88em;color:#888;">Nenhum contrato vigente cobre esta dependência. Para vincular, marque-a em "O que este contrato cobre", na aba Dados do contrato.</div>';
  cont.innerHTML = `<div style="margin-bottom:18px;padding:12px 14px;border:1px solid #d8d2cd;border-left:3px solid #d60014;border-radius:8px;background:#fffafa;">
    <div style="font-size:0.78em;font-weight:700;color:#444;text-transform:uppercase;letter-spacing:0.4px;margin-bottom:4px;">SLAs contratados</div>
    <div style="font-size:0.74em;color:#888;margin-bottom:6px;">Vêm dos contratos vigentes e entram no DRP gerado, na seção "SLAs Contratados com Fornecedores". A comparação usa o RTO/RPO já salvo desta dependência.</div>
    ${corpo}
  </div>`;
}

/**
 * Cartão único selecionável (nunca lista) -- clicar destaca/desmarca um valor
 * só, ao contrário dos chips de sugestão da aba DRP (_htmlDrpLista), que só
 * preenchem uma caixa de texto pra adicionar à lista. Cada estratégia vem
 * com uma descrição curta, pro usuário não precisar adivinhar o que cada uma
 * significa.
 */
function renderEstrategiaChips() {
  const container = document.getElementById('chips-depEstrategia');
  if (!container) return;
  const atual = document.getElementById('depEstrategia').value;
  container.innerHTML = DEPENDENCIA_ESTRATEGIAS_BACKUP.map((e) => {
    const sel = e.valor === atual;
    return `<button type="button" onclick="selecionarEstrategiaDep('${escJs(e.valor)}')" style="text-align:left;padding:8px 12px;border-radius:10px;cursor:pointer;min-width:160px;max-width:220px;border:1.5px solid ${sel ? '#d60014' : '#c5cae9'};background:${sel ? '#fce8ea' : '#fff'};">
      <div style="font-weight:700;color:#d60014;font-size:0.86em;">${esc(e.valor)}${sel ? ' ✓' : ''}</div>
      <div style="font-size:0.76em;color:#666;margin-top:3px;">${esc(e.descricao)}</div>
    </button>`;
  }).join('');
}

window.selecionarEstrategiaDep = (valor) => {
  const campo = document.getElementById('depEstrategia');
  campo.value = campo.value === valor ? '' : valor; // clicar de novo desmarca
  renderEstrategiaChips();
};

/** Mesma ideia do select de áreas do fornecedor, pro Área Responsável da Dependência. */
function _popularSelectAreaResponsavelDep(valorAtual) {
  const sel = document.getElementById('depResponsavel');
  if (!sel) return;
  const lista = window.areasData || [];
  const temNaLista = lista.some((a) => a.nome === valorAtual);
  sel.innerHTML = '<option value="">Selecione...</option>' +
    lista.map((a) => `<option value="${esc(a.nome)}">${esc(a.nome)}</option>`).join('') +
    (valorAtual && !temNaLista ? `<option value="${esc(valorAtual)}">${esc(valorAtual)} (não cadastrada como área)</option>` : '');
  sel.value = valorAtual || '';
}

// ============================================================
// Aba DRP -- Seção "Dependências": seletor inline que lê o catálogo da
// entidade Dependências (mesmo padrão de CRUD inline da aba BIA), com opção
// de criar quando o item não existe. Estado próprio (_depDrpDependenciasSel)
// pra não colidir com _dependenciaSelecionadas da BIA. Cada item guardado é
// { id, nome, categoria }.
// ============================================================
window._depDrpDependenciasSel = [];

/** Ícone por categoria -- mesmo mapa usado pela tabela de Dependências Críticas da BIA. */
function _iconeCategoriaDep(cat) {
  const map = {
    'Fornecedores': '🏢', 'Fornecedor': '🏢', 'Pessoas': '👤', 'Pessoa': '👤',
    'Processos Internos': '🔄', 'Processo Interno': '🔄', 'API': '🔌', 'Banco de Dados': '🗄️',
    'Infraestrutura': '⚡', 'Portais Web': '🌐', 'Segurança': '🔒', 'Servidor': '🖥️', 'Sistemas': '💻', 'Outros': '📦',
    'Instalações': '📍', 'Instalação': '📍',
  };
  return map[cat] || '📦';
}

/** Bloco HTML da seção "Dependências" (tags selecionadas + input de busca/criar + chips disponíveis). */
function _htmlDrpDependencias() {
  return `
    <div style="border-top:1px solid #eee;margin-top:18px;padding-top:14px;">
      <label style="display:block;font-size:0.78em;font-weight:700;color:#444;text-transform:uppercase;letter-spacing:0.4px;margin-bottom:8px;">Dependências</label>
      <p style="font-size:0.75em;color:#888;margin:0 0 8px;">Outras dependências das quais este item depende para se recuperar. Clique nas disponíveis ou digite para buscar/criar.</p>
      <div id="drpDep-tags" style="display:flex;flex-wrap:wrap;gap:6px;margin-bottom:8px;"></div>
      <div style="position:relative;">
        <input type="text" id="drpDep-input" placeholder="Digite para buscar ou criar..." autocomplete="off" style="width:100%;padding:9px 12px;border:1.5px solid #e0e0e0;border-radius:7px;font-size:0.9em;box-sizing:border-box;" oninput="drpDepMostrarDropdown()" onfocus="drpDepMostrarDropdown()" onblur="setTimeout(drpDepFecharDropdown,300)">
        <div id="drpDep-dropdown" style="display:none;position:absolute;top:100%;left:0;right:0;background:white;border:1.5px solid #e0e0e0;border-radius:0 0 7px 7px;max-height:220px;overflow-y:auto;z-index:50;box-shadow:0 4px 16px rgba(0,0,0,0.12);"></div>
      </div>
      <div id="drpDep-disponiveis" style="margin-top:8px;"></div>
    </div>`;
}

/** Catálogo de dependências, exceto a própria (em edição) e as já selecionadas. */
function _drpDepCatalogoDisponivel(filtro) {
  const catalogo = window.dependenciasCatalogo || dependenciasData || [];
  const selfId = (document.getElementById('depId') || {}).value || '';
  const termo = (filtro || '').toLowerCase();
  return catalogo.filter((d) =>
    String(d.id) !== String(selfId) &&
    _fornecedorAtivo(d) &&
    !window._depDrpDependenciasSel.some((s) => s.id && String(s.id) === String(d.id)) &&
    (termo === '' || (d.nome || '').toLowerCase().includes(termo))
  );
}

function renderDrpDependenciasTags() {
  const cont = document.getElementById('drpDep-tags');
  if (!cont) return;
  const sel = window._depDrpDependenciasSel || [];
  cont.innerHTML = sel.length ? sel.map((item, i) =>
    `<span style="display:inline-flex;align-items:center;gap:4px;background:#d60014;color:white;border:1.5px solid #d60014;padding:4px 8px 4px 12px;border-radius:14px;font-size:0.85em;font-weight:500;white-space:nowrap;" title="${esc(item.categoria || '')}">${esc(_iconeCategoriaDep(item.categoria))} ${esc(item.nome)}<button onclick="removerDrpDependencia(${i})" style="background:none;border:none;cursor:pointer;font-size:1.1em;color:rgba(255,255,255,0.75);line-height:1;padding:0 3px;" title="Remover">&times;</button></span>`
  ).join(' ') : '<span style="font-size:0.82em;color:#bbb;font-style:italic;">Nenhuma dependência vinculada.</span>';
  renderDrpDependenciasDisponiveis();
}

/** Chips cinza das dependências do catálogo ainda não selecionadas. */
function renderDrpDependenciasDisponiveis() {
  const cont = document.getElementById('drpDep-disponiveis');
  if (!cont) return;
  const disp = _drpDepCatalogoDisponivel('');
  if (!disp.length) { cont.innerHTML = ''; return; }
  const chips = disp.slice(0, 40).map((d) =>
    `<span onclick="selecionarDrpDependencia('${escJs(d.nome)}','${escJs(d.categoria)}','${escJs(d.id)}')" style="display:inline-block;padding:4px 10px;border-radius:12px;font-size:0.78em;font-weight:500;background:#f5f6fa;color:#d60014;cursor:pointer;border:1px solid #e0e0e0;" onmouseenter="this.style.background='#c5cae9'" onmouseleave="this.style.background='#f5f6fa'" title="${esc(d.categoria || '')}">${esc(_iconeCategoriaDep(d.categoria))} ${esc(d.nome)}</span>`
  ).join(' ');
  cont.innerHTML = `<span style="font-size:0.7em;color:#999;">Disponíveis:</span><div style="display:flex;flex-wrap:wrap;gap:5px;margin-top:4px;max-height:80px;overflow-y:auto;">${chips}</div>`;
}

window.drpDepMostrarDropdown = () => {
  const input = document.getElementById('drpDep-input');
  const dd = document.getElementById('drpDep-dropdown');
  if (!input || !dd) return;
  const filtro = input.value.trim();
  const disp = _drpDepCatalogoDisponivel(filtro);
  let html = disp.slice(0, 30).map((d) =>
    `<div onmousedown="event.preventDefault();selecionarDrpDependencia('${escJs(d.nome)}','${escJs(d.categoria)}','${escJs(d.id)}');drpDepFecharDropdown();document.getElementById('drpDep-input').value='';" style="padding:8px 12px;cursor:pointer;font-size:0.86em;border-bottom:1px solid #f0f0f0;" onmouseenter="this.style.background='#f5f6fa'" onmouseleave="this.style.background='white'">${esc(_iconeCategoriaDep(d.categoria))} ${esc(d.nome)} <span style="color:#999;font-size:0.85em;">(${esc(d.categoria || 'Outros')})</span></div>`
  ).join('');
  // Opção de criar -- só quando há texto que não corresponde exatamente a um item já disponível.
  const jaExiste = disp.some((d) => (d.nome || '').toLowerCase() === filtro.toLowerCase());
  if (filtro && !jaExiste) {
    html += `<div onmousedown="event.preventDefault();criarDrpDependencia('${escJs(filtro)}');" style="padding:9px 12px;cursor:pointer;font-size:0.86em;color:#d60014;font-weight:700;background:#f5f6fa;" onmouseenter="this.style.background='#fce8ea'" onmouseleave="this.style.background='#f5f6fa'">+ Criar "${esc(filtro)}"</div>`;
  }
  if (!html) { dd.style.display = 'none'; return; }
  dd.innerHTML = html;
  dd.style.display = 'block';
};

window.drpDepFecharDropdown = () => {
  const dd = document.getElementById('drpDep-dropdown');
  if (dd) dd.style.display = 'none';
};

window.selecionarDrpDependencia = (nome, categoria, id) => {
  const realId = (id === 'null' || id === 'undefined' || id === '') ? null : id;
  if (realId && window._depDrpDependenciasSel.some((s) => String(s.id) === String(realId))) return;
  window._depDrpDependenciasSel.push({ id: realId, nome, categoria: categoria || 'Outros' });
  const input = document.getElementById('drpDep-input');
  if (input) input.value = '';
  drpDepFecharDropdown();
  renderDrpDependenciasTags();
};

window.removerDrpDependencia = (idx) => {
  window._depDrpDependenciasSel.splice(idx, 1);
  renderDrpDependenciasTags();
};

/** Cria uma dependência nova (categoria "Outros") no catálogo e a vincula. */
window.criarDrpDependencia = async (nome) => {
  const input = document.getElementById('drpDep-input');
  if (input) input.value = '';
  drpDepFecharDropdown();
  // Otimista: adiciona já vinculada sem id; o id real chega do backend.
  const item = { id: null, nome, categoria: 'Outros' };
  window._depDrpDependenciasSel.push(item);
  renderDrpDependenciasTags();
  try {
    const r = await API.salvarDependencia({ categoria: 'Outros', nome });
    if (r && r.id) {
      item.id = r.id;
      const novaDep = { id: r.id, categoria: 'Outros', nome };
      if (Array.isArray(window.dependenciasCatalogo)) window.dependenciasCatalogo.push(novaDep);
      if (Array.isArray(dependenciasData)) dependenciasData.push(novaDep);
      API.invalidate('getDependencias');
    }
    renderDrpDependenciasTags();
  } catch (e) {
    showToast('❌ ' + _mensagemErro(e, 'Não foi possível criar a dependência. Tente de novo.'), '#c62828');
  }
};

// ============================================================
// Aba DRP -- Seção "Testes do procedimento": registro único de dados de
// controle (não é lista). Campos fixos lidos/gravados por id.
// ============================================================
const DRP_CENARIOS_TESTE = [
  'Tabletop (Exercício de Mesa)',
  'Teste Funcional (testa partes específicas do sistema)',
  'Teste Paralelo (ambiente de recuperação ativado em paralelo)',
  'Full Failover Test (Teste Completo)',
];

// "Testes do Procedimento" (Parâmetros DRP) = só as Estratégias de Teste
// (lista de {cenario, frequencia}). O histórico de execuções foi para a aba
// própria "Registros de Testes" (_htmlDrpRegistros). drpTestes (registro único
// antigo) fica preservado no doc e serve de fonte pra migração ao abrir.
window._depDrpEstrategias = [];

function _htmlDrpTestes() {
  const lbl = 'display:block;font-size:0.78em;font-weight:700;color:#444;text-transform:uppercase;letter-spacing:0.4px;margin-bottom:5px;';
  const inp = 'width:100%;padding:9px 12px;border:1.5px solid #e0e0e0;border-radius:7px;font-size:0.9em;box-sizing:border-box;';
  return `
    <div style="border-top:1px solid #eee;margin-top:18px;padding-top:14px;">
      <label style="${lbl}">Testes do Procedimento — Estratégias de Teste</label>
      <span style="font-size:0.75em;color:#888;display:block;margin-top:-3px;margin-bottom:8px;">Cadastre quantas estratégias forem necessárias, cada uma com sua frequência.</span>
      <div id="drpEstrategiasTabela"></div>
      <div style="background:#fafbff;border:1px solid #fce8ea;border-radius:8px;padding:12px;margin-top:8px;">
        <div style="display:grid;grid-template-columns:1fr 1fr auto;gap:10px;align-items:end;">
          <div>
            <label style="display:block;font-size:0.74em;font-weight:600;color:#666;margin-bottom:4px;">Tipo de Teste (Cenário)</label>
            <select id="drpEstrategiaCenario" style="${inp}">
              <option value="">Selecione...</option>
              ${DRP_CENARIOS_TESTE.map((c) => `<option value="${esc(c)}">${esc(c)}</option>`).join('')}
            </select>
          </div>
          <div>
            <label style="display:block;font-size:0.74em;font-weight:600;color:#666;margin-bottom:4px;">Frequência</label>
            <input type="text" id="drpEstrategiaFrequencia" placeholder="Ex: Semestral" style="${inp}">
          </div>
          <button type="button" class="btn btn-ghost" onclick="adicionarDrpEstrategiaTeste()" style="padding:9px 14px;white-space:nowrap;">+ Adicionar</button>
        </div>
      </div>
    </div>`;
}

function renderDrpEstrategiasTeste() {
  const cont = document.getElementById('drpEstrategiasTabela');
  if (!cont) return;
  const itens = window._depDrpEstrategias || [];
  if (!itens.length) { cont.innerHTML = '<p class="vazio-inline">Nenhuma estratégia de teste cadastrada.</p>'; return; }
  cont.innerHTML = `<table class="data-table" style="box-shadow:none;"><tbody>` +
    itens.map((e, i) => `<tr>
        <td style="font-weight:600;color:#222;">${esc(e.cenario || '-')}</td>
        <td style="font-size:0.85em;color:#555;">${esc(e.frequencia || '-')}</td>
        <td style="text-align:center;white-space:nowrap;">
          <button class="btn-icon" onclick="removerDrpEstrategiaTeste(${i})" title="Remover" style="color:#c62828;font-weight:700;">&times;</button>
        </td>
      </tr>`).join('') + `</tbody></table>`;
}

window.adicionarDrpEstrategiaTeste = () => {
  const cenario = (document.getElementById('drpEstrategiaCenario') || {}).value || '';
  const frequencia = (document.getElementById('drpEstrategiaFrequencia') || {}).value.trim();
  if (!cenario && !frequencia) return showToast('Informe o cenário e/ou a frequência.', '#e65100');
  window._depDrpEstrategias = window._depDrpEstrategias || [];
  window._depDrpEstrategias.push({ cenario, frequencia });
  document.getElementById('drpEstrategiaCenario').value = '';
  document.getElementById('drpEstrategiaFrequencia').value = '';
  renderDrpEstrategiasTeste();
};

window.removerDrpEstrategiaTeste = (idx) => {
  window._depDrpEstrategias.splice(idx, 1);
  renderDrpEstrategiasTeste();
};

// ============================================================
// Aba "Gestão de Testes" -- seção "Roteiros de Teste": documento gerado via
// IA (Gemini) a partir do DRP já gerado da dependência, um por tipo de teste
// (categoria = cenário de DRP_CENARIOS_TESTE, o mesmo vocabulário de
// Estratégias de Teste). Substitui a versão anterior (links cadastrados à
// mão): não existe mais "+ Adicionar" aqui, só "🤖 Gerar Roteiro de Teste".
// window._depDrpRoteiros guarda METADADO só ({categoria,versao,data,autor},
// sem html -- mesmo molde de drpSalvo/DRP) hidratado em abrirDrawerDependencia
// a partir de d.drpRoteirosTeste; o html de verdade mora em roteiro_conteudo
// (servidor, ver appLogic.js) e só volta pelo obterRoteiroTeste. Gerar de novo
// o mesmo tipo de teste acrescenta versão, nunca sobrescreve -- por isso pode
// haver mais de uma entrada por categoria no array; a tabela mostra só a mais
// recente de cada uma.
// ============================================================
window._depDrpRoteiros = [];

function _htmlDrpRoteiros() {
  return `
    <div>
      <label style="display:block;font-size:0.78em;font-weight:700;color:#444;text-transform:uppercase;letter-spacing:0.4px;margin-bottom:5px;">Roteiros de Teste</label>
      <span style="font-size:0.75em;color:#888;display:block;margin-top:-3px;margin-bottom:8px;">Gerados por IA a partir do DRP já gerado desta dependência, um roteiro por tipo de teste.</span>
      <div id="drpRoteirosTabela"></div>
      <button type="button" class="btn btn-ghost" id="btnGerarRoteiroTeste" onclick="gerarRoteiroTeste()" style="color:#2e7d32;border-color:#2e7d32;margin-top:8px;">🤖 Gerar Roteiro de Teste</button>
    </div>`;
}

/** Última versão de cada categoria presente em window._depDrpRoteiros, ordenada por categoria. */
function _roteirosTesteMaisRecentesPorCategoria() {
  const itens = window._depDrpRoteiros || [];
  const porCategoria = {};
  itens.forEach((r) => {
    const atual = porCategoria[r.categoria];
    if (!atual || Number(r.versao) > Number(atual.versao)) porCategoria[r.categoria] = r;
  });
  return Object.values(porCategoria).sort((a, b) => (a.categoria || '').localeCompare(b.categoria || ''));
}

function renderDrpRoteirosTeste() {
  const cont = document.getElementById('drpRoteirosTabela');
  if (!cont) return;
  const itens = _roteirosTesteMaisRecentesPorCategoria();
  if (!itens.length) { cont.innerHTML = '<p class="vazio-inline">Nenhum roteiro de teste gerado ainda.</p>'; return; }
  cont.innerHTML = `<table class="data-table" style="box-shadow:none;">
    <thead><tr>
      <th style="font-size:0.78em;">Categoria</th>
      <th style="font-size:0.78em;">Gerado em</th>
      <th style="font-size:0.78em;">Por</th>
      <th style="width:90px;"></th>
    </tr></thead><tbody>` +
    itens.map((r) => `<tr>
        <td style="font-weight:600;color:#222;">${esc(r.categoria || '-')}</td>
        <td style="font-size:0.85em;color:#555;">${esc(r.data ? new Date(r.data).toLocaleString('pt-BR') : '-')}${r.versao > 1 ? ` <span style="color:#999;">(v${r.versao})</span>` : ''}</td>
        <td style="font-size:0.85em;color:#555;">${esc(r.autor || '-')}</td>
        <td style="text-align:center;white-space:nowrap;">
          <button class="btn-icon" onclick="abrirRoteiroTesteDireto('${escJs(r.categoria)}')" title="Abrir">🔗</button>
          <button class="btn-icon" onclick="removerDrpRoteiroTeste('${escJs(r.categoria)}')" title="Excluir" style="color:#c62828;font-weight:700;">&times;</button>
        </td>
      </tr>`).join('') + `</tbody></table>`;
}

window.removerDrpRoteiroTeste = async (categoria) => {
  if (!await confirmarAcao(`Excluir o roteiro de teste de "${categoria}"? Todas as versões geradas pra este tipo de teste serão apagadas.`)) return;
  const id = document.getElementById('depId').value || '';
  if (!id) return;
  try {
    await API.post('excluirRoteiroTeste', { id, categoria });
    window._depDrpRoteiros = (window._depDrpRoteiros || []).filter((r) => r.categoria !== categoria);
    API.invalidate('getDependencias');
    renderDrpRoteirosTeste();
    showToast('🗑️ Roteiro excluído.', '#555');
  } catch (e) {
    showToast('❌ ' + _mensagemErro(e), '#c62828');
  }
};

/** Cenários já previstos PARA ESTA dependência (Estratégias de Teste da aba Parâmetros DRP), não a lista inteira de DRP_CENARIOS_TESTE. */
function _cenariosTesteCandidatos() {
  const vistos = new Set();
  return (window._depDrpEstrategias || [])
    .filter((e) => e && typeof e === 'object')
    .map((e) => e.cenario)
    .filter((c) => c && !vistos.has(c) && vistos.add(c));
}

window.gerarRoteiroTeste = () => {
  // Blindado com try/catch: um erro inesperado aqui nao pode passar em
  // silencio (sem isso, uma excecao sincrona nesta funcao nao mostra nenhum
  // toast nem console visivel pro usuario -- so aparece no console do
  // DevTools, que a maioria nao abre). Descoberto em producao: clique no
  // botao nao fazia nada, nem o toast esperado de "falta Estrategia de
  // Teste".
  try {
    const id = (document.getElementById('depId') || {}).value || '';
    if (!id) return showToast('Salve a dependência antes de gerar um roteiro de teste.', '#e65100');
    const d = (dependenciasData || []).find((x) => String(x.id) === String(id));
    if (!d || !d.drpSalvo) return showToast('Gere o DRP (aba Plano de Recuperação) antes de gerar um roteiro de teste.', '#e65100');
    const candidatos = _cenariosTesteCandidatos();
    if (!candidatos.length) return showToast('Cadastre ao menos uma Estratégia de Teste (aba Parâmetros DRP) antes de gerar um roteiro.', '#e65100');
    if (candidatos.length === 1) return _gerarRoteiroTesteParaCategoria(candidatos[0]);
    abrirModalEscolherTipoTeste(candidatos);
  } catch (err) {
    console.error('Erro em gerarRoteiroTeste:', err);
    showToast('❌ ' + _mensagemErro(err), '#c62828');
  }
};

async function _gerarRoteiroTesteParaCategoria(categoria) {
  const id = document.getElementById('depId').value || '';
  const d = (dependenciasData || []).find((x) => String(x.id) === String(id));
  const btn = document.getElementById('btnGerarRoteiroTeste');
  const textoOriginal = btn ? btn.innerHTML : '';
  if (btn) { btn.disabled = true; btn.innerHTML = '⏳ Gerando...'; btn.style.opacity = '0.7'; }
  try {
    const result = await API.post('gerarRoteiroTeste', { id, categoria });
    if (result.error) throw new Error(result.error);
    const html = result.html || '';
    await API.post('salvarRoteiroTeste', { id, categoria, html });
    API.invalidate('getDependencias');
    window._depDrpRoteiros = window._depDrpRoteiros || [];
    const versaoAnterior = Math.max(0, ...window._depDrpRoteiros.filter((r) => r.categoria === categoria).map((r) => Number(r.versao) || 0));
    const novaVersao = { categoria, versao: versaoAnterior + 1, data: new Date().toISOString(), autor: window.USER_EMAIL || 'sistema' };
    window._depDrpRoteiros.push(novaVersao);
    renderDrpRoteirosTeste();
    showToast('✅ Roteiro de Teste gerado!', '#2e7d32');
    await _abrirPopupRoteiroTeste(categoria, [{ ...novaVersao, html }], d);
  } catch (err) {
    console.error('Erro ao gerar Roteiro de Teste:', err);
    showToast('❌ ' + _mensagemErro(err), '#c62828');
  } finally {
    if (btn) { btn.disabled = false; btn.innerHTML = textoOriginal; btn.style.opacity = '1'; }
  }
}

window.abrirRoteiroTesteDireto = async (categoria) => {
  const id = document.getElementById('depId').value || '';
  const d = (dependenciasData || []).find((x) => String(x.id) === String(id));
  let versoes;
  try {
    versoes = (await API.get('obterRoteiroTeste', { id })).versoes || [];
  } catch (e) {
    return showToast('❌ ' + _mensagemErro(e), '#c62828');
  }
  const daCategoria = versoes.filter((v) => v.categoria === categoria);
  if (!daCategoria.length) return showToast('Nenhuma versão encontrada para este tipo de teste.', '#e65100');
  await _abrirPopupRoteiroTeste(categoria, daCategoria, d);
};

/** Popup editável (contenteditable + "💾 Salvar versão"), mesmo mecanismo de _buildDRPPage/_buildPCNPage -- edição vira uma versão nova, nunca sobrescreve. */
async function _abrirPopupRoteiroTeste(categoria, versoesDaCategoria, dep) {
  const win = window.open('', '_blank');
  if (!win) return showToast('Popup bloqueado. Permita popups para este site.', '#e65100');
  const ultima = versoesDaCategoria[versoesDaCategoria.length - 1];
  const idToken = await _tokenParaPCN().catch(() => '');
  win.document.write(_buildRoteiroTestePage(categoria, versoesDaCategoria, ultima, dep, idToken));
  win.document.close();
}

function _buildRoteiroTestePage(categoria, versoesDaCategoria, versaoAtual, dep, idToken) {
  const limpo = sanitizarPCN(versaoAtual.html || '');
  const versoesJson = JSON.stringify(versoesDaCategoria).replace(/\\/g, '\\\\').replace(/'/g, "\\'").replace(/\n/g, '\\n').replace(/\r/g, '\\r').replace(/</g, '\\x3c');
  const seletorVersoes = versoesDaCategoria.length > 1 ? `
    <div style="position:fixed;bottom:16px;right:20px;z-index:60;background:white;border:1.5px solid #e0e0e0;border-radius:8px;padding:8px 14px;box-shadow:0 2px 12px rgba(0,0,0,0.15);font-size:9pt;display:flex;align-items:center;gap:8px;">
      <span style="color:#666;">Versão:</span>
      <select id="roteiro-versao-select" onchange="trocarVersaoRoteiroTeste(this.value)" style="padding:4px 8px;border:1px solid #ddd;border-radius:4px;font-size:9pt;">
        ${versoesDaCategoria.map((v, i) => `<option value="${i}" ${v.versao === versaoAtual.versao ? 'selected' : ''}>v${v.versao} — ${new Date(v.data).toLocaleDateString('pt-BR')} ${new Date(v.data).toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' })}</option>`).join('')}
      </select>
    </div>` : '';
  return `<!DOCTYPE html><html><head><title>Roteiro de Teste — ${esc(categoria)}</title><style>
    :root{--risk-critical:#d60014;--risk-high:#b64a12;--risk-medium:#9a6700;--risk-low:#38bb0e}
    body{font-family:Arial;padding:40px;max-width:900px;margin:0 auto;font-size:11pt;line-height:1.6;color:#222;}
    h1{color:#d60014} h2{color:#d60014;border-bottom:2px solid #fce8ea;padding-bottom:6px;margin-top:24px}
    table{width:100%;border-collapse:collapse;margin:8px 0 16px;font-size:9.5pt}
    th{background:#d60014;color:white;padding:8px 10px;text-align:left} td{padding:7px 10px;border:1px solid #e0e0e0}
    .header{display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:12px;margin-bottom:20px;}
    .header .sub{font-size:9pt;color:#888;margin-top:4px;font-weight:400}
    .btn-print{padding:9px 18px;background:#d60014;color:#fff;border:none;border-radius:8px;font-size:9.5pt;cursor:pointer;font-weight:600}
    .btn-print:hover{opacity:.9} @media print{.btn-print,#roteiro-versao-select,#roteiro-versao-select+span{display:none!important}}
  </style></head><body>
    <div class="header">
      <div>
        <img src="https://bia-forte-2025.web.app/logo_fortes.png" style="height:40px;margin-bottom:4px;display:block;" alt="Fortes Tecnologia" onerror="this.style.display='none'">
        <div style="font-size:0.72em;color:#d60014;font-weight:700;letter-spacing:0.3px;margin-bottom:8px;">BIA · Governança, Riscos e Conformidade</div>
        <h1>Roteiro de Teste — ${esc(categoria)}</h1>
        <div class="sub">${esc(dep && dep.nome || '')} • ${esc(versaoAtual.autor || '')} • ${versaoAtual.data ? new Date(versaoAtual.data).toLocaleString('pt-BR') : ''} • Fortes Tecnologia</div>
      </div>
      <div style="display:flex;gap:8px;">
        <button class="btn-print" onclick="salvarVersaoRoteiroTeste()" style="background:#2e7d32;">💾 Salvar versão</button>
        <button class="btn-print" onclick="window.print()">🖨️ Imprimir / PDF</button>
      </div>
    </div>
    <div id="roteiro-conteudo" contenteditable="true" style="outline:none;min-height:150px;">${limpo.html}</div>
    ${seletorVersoes}
    <script>
      var ROTEIRO_API_URL = '` + APP_API_URL + `';
      var ROTEIRO_TOKEN = '` + (idToken || '') + `';
      var ROTEIRO_DEP_ID = '${escScript(dep && dep.id || '')}';
      var ROTEIRO_CATEGORIA = '${escScript(categoria)}';
      var ROTEIRO_VERSOES = JSON.parse('${versoesJson}');
      ${_SCRIPT_TOKEN_POPUP('ROTEIRO_TOKEN')}
      function trocarVersaoRoteiroTeste(idx){
        var v = ROTEIRO_VERSOES[Number(idx)];
        if (v && v.html) document.getElementById('roteiro-conteudo').innerHTML = v.html;
      }
      async function salvarVersaoRoteiroTeste(){
        var conteudo = document.getElementById('roteiro-conteudo').innerHTML;
        var btn = document.querySelector('button[onclick="salvarVersaoRoteiroTeste()"]');
        if(btn){btn.disabled=true;btn.textContent='⏳ Salvando...';}
        try{
          var payload = JSON.stringify({action:'salvarRoteiroTeste', id:ROTEIRO_DEP_ID, categoria:ROTEIRO_CATEGORIA, html:conteudo});
          var enviar = async function(forcar){
            var tk = await tokenDoSistema(forcar);
            return fetch(ROTEIRO_API_URL, {method:'POST',headers:{'Content-Type':'text/plain;charset=UTF-8','Authorization':'Bearer '+tk},body:payload});
          };
          var res = await enviar(false);
          if(res.status===401) res = await enviar(true);
          if(res.status===401){throw new Error(MSG_SESSAO_PERDIDA);}
          var data = JSON.parse(await res.text());
          if(data.error) throw new Error(data.error);
          alert('✅ Versão ' + (data.versao || '') + ' salva com sucesso! (' + (data.totalVersoes || '') + ' versões no total)');
        }catch(e){console.error(e);alert('❌ Não foi possível salvar a versão. Verifique a conexão e tente de novo.');}
        finally{if(btn){btn.disabled=false;btn.textContent='💾 Salvar versão';}}
      }
    </script>
    <script src="https://bia-forte-2025.web.app/tabela-editavel.js?v=1"></script>
  </body></html>`;
}

function _htmlModalEscolherTipoTeste() {
  return `
    <div class="modal-overlay modal-sobre-drawer" id="modalEscolherTipoTeste"><div class="modal" onclick="event.stopPropagation()" style="max-width:420px;">
      <h3>Qual tipo de teste?</h3>
      <p style="font-size:0.85em;color:#666;margin-bottom:14px;">Esta dependência tem mais de um tipo de teste previsto (aba Parâmetros DRP). Escolha para qual gerar o roteiro.</p>
      <select id="escolherTipoTesteSelect" style="width:100%;padding:9px 12px;border:1.5px solid #e0e0e0;border-radius:7px;font-size:0.93em;box-sizing:border-box;"></select>
      <div class="modal-footer">
        <button class="btn btn-ghost" onclick="fecharModalEscolherTipoTeste()">Cancelar</button>
        <button class="btn btn-primary" onclick="confirmarEscolhaTipoTeste()">Gerar</button>
      </div>
    </div></div>`;
}

window.abrirModalEscolherTipoTeste = (candidatos) => {
  document.getElementById('escolherTipoTesteSelect').innerHTML = candidatos.map((c) => `<option value="${esc(c)}">${esc(c)}</option>`).join('');
  document.getElementById('modalEscolherTipoTeste').classList.add('open');
};

window.fecharModalEscolherTipoTeste = () => {
  document.getElementById('modalEscolherTipoTeste').classList.remove('open');
};

window.confirmarEscolhaTipoTeste = () => {
  const categoria = document.getElementById('escolherTipoTesteSelect').value;
  fecharModalEscolherTipoTeste();
  if (categoria) _gerarRoteiroTesteParaCategoria(categoria);
};

// ============================================================
// Aba "Registros de Testes" -- histórico de execuções ao longo do tempo
// (lista de {data, resultado, evidencia, pendencias}), ordenado por data desc.
// ============================================================
window._depDrpRegistros = [];

function _htmlDrpRegistros() {
  const inp = 'width:100%;padding:9px 12px;border:1.5px solid #e0e0e0;border-radius:7px;font-size:0.9em;box-sizing:border-box;';
  const fieldLbl = 'display:block;font-size:0.74em;font-weight:600;color:#666;margin-bottom:4px;';
  return `
    <div>
      <label style="display:block;font-size:0.78em;font-weight:700;color:#444;text-transform:uppercase;letter-spacing:0.4px;margin-bottom:5px;">Registros de Testes</label>
      <span style="font-size:0.75em;color:#888;display:block;margin-top:-3px;margin-bottom:8px;">Histórico das execuções de teste desta dependência ao longo do tempo.</span>
      <div id="drpRegistrosTabela"></div>
      <div style="background:#fafbff;border:1px solid #fce8ea;border-radius:8px;padding:12px;margin-top:8px;">
        <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:10px;">
          <div>
            <label style="${fieldLbl}">Data do teste</label>
            <input type="date" id="drpRegistroData" style="${inp}">
          </div>
          <div>
            <label style="${fieldLbl}">Resultado</label>
            <input type="text" id="drpRegistroResultado" placeholder="Ex: Sucesso / Sucesso parcial / Falha" style="${inp}">
          </div>
          <div style="grid-column:1 / -1;">
            <label style="${fieldLbl}">Evidência</label>
            <input type="text" id="drpRegistroEvidencia" placeholder="Ex: Link do relatório, print, ata" style="${inp}">
          </div>
          <div style="grid-column:1 / -1;">
            <label style="${fieldLbl}">Pendências encontradas</label>
            <textarea id="drpRegistroPendencias" rows="2" placeholder="Ex: Ajustar rota de failover; atualizar runbook do passo 4" style="${inp}resize:vertical;font-family:inherit;"></textarea>
          </div>
        </div>
        <button type="button" class="btn btn-ghost" onclick="adicionarDrpRegistroTeste()" style="padding:9px 14px;white-space:nowrap;">+ Adicionar registro</button>
      </div>
    </div>`;
}

/** Ordena por data desc (registros sem data vão para o fim). */
function _registrosTesteOrdenados() {
  return (window._depDrpRegistros || []).map((r, i) => ({ r, i }))
    .sort((a, b) => String(b.r.data || '').localeCompare(String(a.r.data || '')));
}

function renderDrpRegistrosTeste() {
  const cont = document.getElementById('drpRegistrosTabela');
  if (!cont) return;
  const ordenados = _registrosTesteOrdenados();
  if (!ordenados.length) { cont.innerHTML = '<p class="vazio-inline">Nenhum registro de teste ainda.</p>'; return; }
  cont.innerHTML = `<table class="data-table" style="box-shadow:none;">
    <thead><tr>
      <th style="font-size:0.78em;">Data</th>
      <th style="font-size:0.78em;">Resultado</th>
      <th style="font-size:0.78em;">Evidência</th>
      <th style="font-size:0.78em;">Pendências</th>
      <th style="width:40px;"></th>
    </tr></thead><tbody>` +
    ordenados.map(({ r, i }) => `<tr>
        <td style="font-size:0.85em;color:#333;white-space:nowrap;">${esc(r.data ? new Date(r.data + 'T00:00:00').toLocaleDateString('pt-BR') : '-')}</td>
        <td style="font-size:0.85em;color:#555;">${esc(r.resultado || '-')}</td>
        <td style="font-size:0.85em;color:#555;">${esc(r.evidencia || '-')}</td>
        <td style="font-size:0.85em;color:#555;">${esc(r.pendencias || '-')}</td>
        <td style="text-align:center;"><button class="btn-icon" onclick="removerDrpRegistroTeste(${i})" title="Remover" style="color:#c62828;font-weight:700;">&times;</button></td>
      </tr>`).join('') + `</tbody></table>`;
}

window.adicionarDrpRegistroTeste = () => {
  const data = (document.getElementById('drpRegistroData') || {}).value || '';
  const resultado = (document.getElementById('drpRegistroResultado') || {}).value.trim();
  const evidencia = (document.getElementById('drpRegistroEvidencia') || {}).value.trim();
  const pendencias = (document.getElementById('drpRegistroPendencias') || {}).value.trim();
  if (!data && !resultado && !evidencia && !pendencias) return showToast('Preencha ao menos um campo do registro.', '#e65100');
  window._depDrpRegistros = window._depDrpRegistros || [];
  window._depDrpRegistros.push({ data, resultado, evidencia, pendencias });
  ['drpRegistroData', 'drpRegistroResultado', 'drpRegistroEvidencia', 'drpRegistroPendencias'].forEach((id) => {
    const el = document.getElementById(id); if (el) el.value = '';
  });
  renderDrpRegistrosTeste();
};

window.removerDrpRegistroTeste = (idx) => {
  window._depDrpRegistros.splice(idx, 1);
  renderDrpRegistrosTeste();
};

// ============================================================
// Aba "Plano de Recuperação" da Dependência.
// Importar Template DRP (.md) -> gera o artefato DRP via IA (mesmo formato do
// PCN) a partir do template + os Parâmetros DRP -> abre com imprimir/editar/
// salvar versão. Template e versões moram no doc da dependência
// (drpTemplate/drpTemplateNome/drpSalvo). Importar/Gerar são admin-only.
// ============================================================
window._depDrpTemplate = '';       // conteúdo Markdown do template importado (vazio = usa o padrão)
window._depDrpTemplateNome = '';   // nome do arquivo, só para exibição

function _htmlDrpPlano() {
  const lbl = 'display:block;font-size:0.78em;font-weight:700;color:#444;text-transform:uppercase;letter-spacing:0.4px;margin-bottom:5px;';
  return `
    <div>
      <label style="${lbl}">Template DRP</label>
      <p style="font-size:0.8em;color:#888;margin:0 0 10px;">Importe um template em Markdown (.md) para orientar a estrutura do DRP gerado. Se nenhum for importado, um template padrão é usado.</p>
      <div style="display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-bottom:6px;">
        <input type="file" id="drpTemplateFile" accept=".md,.markdown,text/markdown" style="display:none;" onchange="importarTemplateDrp(this)">
        <button class="btn btn-ghost" id="btnImportarTemplateDrp" onclick="document.getElementById('drpTemplateFile').click()">📥 Importar Template DRP</button>
        <span id="drpTemplateNome" style="font-size:0.83em;color:#555;"></span>
      </div>

      <div style="border-top:1px solid #eee;margin-top:16px;padding-top:16px;">
        <label style="${lbl}">Artefato DRP</label>
        <p style="font-size:0.8em;color:#888;margin:0 0 10px;">Gere o Plano de Recuperação de Desastres a partir do template e dos Parâmetros DRP desta dependência.</p>
        <div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:12px;">
          <button class="btn btn-ghost" id="btnGerarDrp" onclick="gerarDRPDependencia()" style="color:#2e7d32;border-color:#2e7d32;">🤖 Gerar DRP</button>
          <button class="btn btn-ghost" id="btnAbrirDrp" onclick="abrirDRPSalvo()" style="color:#1565c0;border-color:#1565c0;display:none;">📂 Abrir DRP</button>
        </div>
        <div data-ciclo="drp"></div>
        <div id="drpResumo"></div>
      </div>
    </div>`;
}

/** Lê o .md escolhido e guarda em memória (persistido no salvar da dependência). */
window.importarTemplateDrp = (input) => {
  const file = input.files && input.files[0];
  if (!file) return;
  const nome = file.name || '';
  if (!/\.(md|markdown)$/i.test(nome)) {
    showToast('Selecione um arquivo Markdown (.md).', '#e65100');
    input.value = '';
    return;
  }
  const reader = new FileReader();
  reader.onload = () => {
    window._depDrpTemplate = String(reader.result || '');
    window._depDrpTemplateNome = nome;
    _renderDrpTemplateNome();
    showToast('✅ Template importado. Salve a dependência para guardá-lo.', '#2e7d32');
  };
  reader.onerror = () => showToast('Não foi possível ler o arquivo.', '#c62828');
  reader.readAsText(file);
  input.value = '';
};

function _renderDrpTemplateNome() {
  const el = document.getElementById('drpTemplateNome');
  if (!el) return;
  el.innerHTML = window._depDrpTemplateNome
    ? `📄 ${esc(window._depDrpTemplateNome)} <button class="btn-icon" onclick="removerTemplateDrp()" title="Remover template" style="color:#c62828;">&times;</button>`
    : '<span style="color:#999;font-style:italic;">Nenhum template importado — usando o padrão.</span>';
}

window.removerTemplateDrp = () => {
  window._depDrpTemplate = '';
  window._depDrpTemplateNome = '';
  _renderDrpTemplateNome();
};

/**
 * Preview do DRP salvo dentro da aba Plano de Recuperação -- espelha
 * renderPcnResumoBcp: mostra a última versão sanitizada, com botões de abrir/
 * editar/gerar novo. A edição inline por seção e o índice lateral ficam no
 * popup completo (_buildDRPPage).
 */
/** Estilo da prévia de DRP (drawer de Dependência e aba DRP do Processo), injetado uma vez. */
function _garantirEstiloPreviaDrp() {
  if (document.getElementById('drpPreviewStyle')) return;
  const style = document.createElement('style');
  style.id = 'drpPreviewStyle';
  style.textContent = `
    .drp-preview h1, .drp-preview h2, .drp-preview h3 { color:#d60014; margin:14px 0 8px; }
    .drp-preview h1 { font-size:1.25em; } .drp-preview h2 { font-size:1.1em; } .drp-preview h3 { font-size:1em; }
    .drp-preview p, .drp-preview li { font-size:0.95em; color:#333; }
    .drp-preview table { width:100%; border-collapse:collapse; margin:10px 0; font-size:0.85em; }
    .drp-preview th, .drp-preview td { border:1px solid #e0e0e0; padding:6px 10px; text-align:left; }
    .drp-preview th { background:#f5f6fa; }`;
  document.head.appendChild(style);
}

function renderDrpResumo() {
  const container = document.getElementById('drpResumo');
  if (!container) return;
  renderCicloRevisao('drp', (document.getElementById('depId') || {}).value || '');
  // Importar template e Gerar DRP: Admin ou Segurança (TI opera/edita, mas não gera).
  const podeGerar = Perfis.podeGerarDRP(window.USER_PERFIS);
  const btnImp = document.getElementById('btnImportarTemplateDrp');
  const btnGer = document.getElementById('btnGerarDrp');
  if (btnImp) btnImp.style.display = podeGerar ? 'inline-block' : 'none';
  if (btnGer) btnGer.style.display = podeGerar ? 'inline-block' : 'none';
  _renderDrpTemplateNome();

  const id = document.getElementById('depId').value || '';
  const d = id ? (dependenciasData || []).find((x) => String(x.id) === String(id)) : null;
  const versoes = d && d.drpSalvo ? _parsePCNVersoes(d.drpSalvo) : [];
  const btnAbrir = document.getElementById('btnAbrirDrp');
  if (btnAbrir) btnAbrir.style.display = versoes.length ? 'inline-block' : 'none';

  if (!id) {
    container.innerHTML = '<div class="vazio">Salve a dependência antes de gerar o DRP.</div>';
    return;
  }
  if (!versoes.length) {
    container.innerHTML = '<div class="vazio">Nenhum DRP gerado ainda para esta dependência.</div>';
    return;
  }

  _garantirEstiloPreviaDrp();

  const idx = versoes.length - 1;
  const versao = versoes[idx];
  const dataFmt = versao.data ? new Date(versao.data).toLocaleString('pt-BR') : '-';
  container.innerHTML = `
    <div style="font-size:0.82em;color:#666;margin-bottom:8px;">Versão ${versao.versao || (idx + 1)} · gerado em ${dataFmt}${versao.autor ? ' · ' + esc(versao.autor) : ''}</div>
    <div class="drp-preview" style="max-height:360px;overflow-y:auto;border:1px solid #e0e0e0;border-radius:8px;padding:16px 20px;background:#fff;line-height:1.55;">
      <p class="vazio-inline">⏳ Carregando…</p>
    </div>`;
  // drpSalvo guarda so versao/data/autor; o HTML mora em drp_conteudo e vem
  // por obterDRP (que confere o perfil). Antes a previa lia versao.html daqui
  // e saia sempre em branco.
  const caixa = container.querySelector('.drp-preview');
  API.get('obterDRP', { id }).then((r) => {
    if ((document.getElementById('depId') || {}).value !== id) return;
    const lista = (r && r.versoes) || [];
    const ult = lista[lista.length - 1];
    caixa.innerHTML = ult ? sanitizarPCN(ult.html || '').html : '<p class="vazio-inline">Nenhuma versão de DRP encontrada.</p>';
  }).catch((e) => {
    caixa.innerHTML = `<p class="vazio-inline" style="color:#c62828;">${esc(_mensagemErro(e, 'Não foi possível carregar o DRP.'))}</p>`;
  });
}

/**
 * Markup do drawer de Dependência (abas Dados Gerais / Parâmetros DRP / Plano
 * de Recuperação). Extraído pra ser reusado tanto no Catálogo de Dependências
 * quanto na tela DRP (que também gerencia os Parâmetros DRP). Mesmos ids, então
 * abrirDrawerDependencia/salvarDep funcionam igual nas duas telas.
 */
// ============================================================
// Composicao de Servicos (21/10/2026): RTO/RPO/MTTR em minutos (valor +
// unidade na tela) e a hierarquia de dependencias (componentes). A conta fica
// em servico-composicao.js; aqui so o formulario.
// ============================================================
const _ROTULO_UNIDADE_DURACAO = { min: ['minuto', 'minutos'], h: ['hora', 'horas'], d: ['dia', 'dias'] };

/** Campo de duração: número + unidade (min/h/dias). idBase -> #idBase (valor) e #idBaseUnidade. */
function _htmlCampoDuracao(idBase, rotulo, dica, aoMudar) {
  const handler = aoMudar ? ` oninput="${aoMudar}" onchange="${aoMudar}"` : '';
  return `<div>
    <label for="${idBase}" style="display:block;font-size:0.78em;font-weight:700;color:#444;text-transform:uppercase;letter-spacing:0.4px;margin-bottom:5px;">${esc(rotulo)}</label>
    <div style="display:flex;gap:6px;">
      <input type="number" id="${idBase}" min="0" step="any" placeholder="—"${handler} style="flex:1;min-width:0;padding:9px 12px;border:1.5px solid #e0e0e0;border-radius:7px;font-size:0.93em;box-sizing:border-box;">
      <select id="${idBase}Unidade" aria-label="Unidade do ${esc(rotulo)}"${handler} style="width:92px;padding:9px 8px;border:1.5px solid #e0e0e0;border-radius:7px;font-size:0.93em;box-sizing:border-box;">
        <option value="min">min</option><option value="h">horas</option><option value="d">dias</option>
      </select>
    </div>
    ${dica ? `<div style="font-size:0.72em;color:#999;margin-top:3px;">${esc(dica)}</div>` : ''}
    <div id="${idBase}Legado" style="display:none;font-size:0.72em;color:#e65100;margin-top:3px;"></div>
  </div>`;
}

/** Preenche o campo de duração com minutos (null = vazio). textoLegado: texto antigo não convertido, mostrado como aviso. */
function _preencherCampoDuracao(idBase, min, textoLegado) {
  const u = ServicoComposicao.paraUnidade(min);
  document.getElementById(idBase).value = u.valor;
  document.getElementById(idBase + 'Unidade').value = u.unidade;
  const aviso = document.getElementById(idBase + 'Legado');
  if (!aviso) return;
  const mostrar = (min === null || min === undefined) && textoLegado;
  aviso.style.display = mostrar ? '' : 'none';
  aviso.textContent = mostrar ? `Valor anterior "${textoLegado}" não pôde ser convertido. Informe o número.` : '';
}

/** Minutos do campo de duração, ou null quando vazio/inválido. */
function _lerCampoDuracao(idBase) {
  return ServicoComposicao.deUnidade(document.getElementById(idBase).value, document.getElementById(idBase + 'Unidade').value);
}

/**
 * Texto de compatibilidade ("4 horas", "30 minutos") gravado em rto/rpo junto
 * com o número: DRP, PCN e o SLA dos contratos ainda leem o texto.
 */
function _textoCampoDuracao(idBase) {
  const valor = String(document.getElementById(idBase).value || '').trim();
  if (valor === '' || ServicoComposicao.deUnidade(valor, 'min') === null) return '';
  const rot = _ROTULO_UNIDADE_DURACAO[document.getElementById(idBase + 'Unidade').value] || _ROTULO_UNIDADE_DURACAO.h;
  return `${valor.replace('.', ',')} ${Number(valor) === 1 ? rot[0] : rot[1]}`;
}

// ---- Instalações (21/10/2026): bloco próprio no drawer de Dependência ----
function _htmlDadosInstalacao() {
  const lbl = 'display:block;font-size:0.78em;font-weight:700;color:#444;text-transform:uppercase;letter-spacing:0.4px;margin-bottom:5px;';
  const inp = 'width:100%;padding:9px 12px;border:1.5px solid #e0e0e0;border-radius:7px;font-size:0.93em;box-sizing:border-box;';
  return `
    <div id="depInstalacaoBloco" style="display:none;border-top:1px solid #eee;margin-top:18px;padding-top:14px;">
      <label style="${lbl}margin-bottom:8px;">Dados da instalação</label>
      <div style="display:grid;grid-template-columns:200px 1fr;gap:16px;margin-bottom:12px;">
        <div>
          <label for="depTipoInstalacao" style="${lbl}">Tipo</label>
          <select id="depTipoInstalacao" style="${inp}"><option value="">Selecione...</option>${TIPOS_INSTALACAO.map((t) => `<option value="${t}">${t}</option>`).join('')}</select>
        </div>
        <div>
          <label for="depEndereco" style="${lbl}">Endereço</label>
          <input type="text" id="depEndereco" placeholder="Rua, número, cidade/UF" style="${inp}">
        </div>
      </div>
      <div>
        <label for="depInstalacaoAlternativa" style="${lbl}">Instalação alternativa (contingência)</label>
        <select id="depInstalacaoAlternativa" style="${inp}"></select>
        <div style="font-size:0.72em;color:#888;margin-top:3px;">Para onde a operação vai se esta instalação ficar indisponível. Entra no PCN e no Mapa de Continuidade.</div>
      </div>
    </div>`;
}

/** Mostra o bloco só para Instalações e preenche as alternativas (as outras instalações). */
function _atualizarBlocoInstalacao(alternativaId) {
  const bloco = document.getElementById('depInstalacaoBloco');
  if (!bloco) return;
  const ehInst = _ehInstalacao(document.getElementById('depCategoria').value);
  bloco.style.display = ehInst ? 'block' : 'none';
  // Trocar a categoria muda o que vale como componente (Instalação em Instalação, não).
  renderDepComponentesTags();
  const sel = document.getElementById('depInstalacaoAlternativa');
  const atual = alternativaId !== undefined ? (alternativaId || '') : sel.value;
  const selfId = (document.getElementById('depId') || {}).value || '';
  const outras = (dependenciasData || []).filter((d) => _ehInstalacao(d.categoria) && d.id && String(d.id) !== String(selfId) && !String(d.id).startsWith('_tmp_'))
    .sort((a, b) => (a.nome || '').localeCompare(b.nome || '', 'pt-BR'));
  const temAtual = !atual || outras.some((d) => String(d.id) === String(atual));
  sel.innerHTML = '<option value="">Nenhuma</option>' + outras.map((d) => `<option value="${esc(d.id)}">${esc(d.nome)}${d.tipoInstalacao ? ' (' + esc(d.tipoInstalacao) + ')' : ''}</option>`).join('')
    + (temAtual ? '' : `<option value="${esc(atual)}">(instalação removida)</option>`);
  sel.value = atual;
}
window._atualizarBlocoInstalacao = _atualizarBlocoInstalacao;

/** Campos da instalação para o formulário (só quando a categoria é Instalações). */
function _coletarDadosInstalacao(categoria) {
  if (!_ehInstalacao(categoria)) return {};
  const altId = document.getElementById('depInstalacaoAlternativa').value;
  const alt = altId ? (dependenciasData || []).find((d) => String(d.id) === String(altId)) : null;
  return {
    tipoInstalacao: document.getElementById('depTipoInstalacao').value,
    endereco: document.getElementById('depEndereco').value.trim(),
    instalacaoAlternativa: altId ? { id: altId, nome: alt ? alt.nome : '' } : null,
  };
}

/** Seção "Componentes abaixo" (aba Dados Gerais da Dependência). */
function _htmlDepComponentes() {
  return `
    <div style="border-top:1px solid #eee;margin-top:18px;padding-top:14px;">
      <label style="display:block;font-size:0.78em;font-weight:700;color:#444;text-transform:uppercase;letter-spacing:0.4px;margin-bottom:8px;">Componentes abaixo</label>
      <p style="font-size:0.75em;color:#888;margin:0 0 8px;">Dependências que sustentam esta (ex.: Infraestrutura → Servidor → Banco de Dados). Formam a hierarquia usada no alerta de RTO/RPO/MTTR do Serviço e no mapa de conexões.</p>
      <div id="depComp-tags" style="display:flex;flex-wrap:wrap;gap:6px;margin-bottom:8px;"></div>
      <div style="position:relative;">
        <input type="text" id="depComp-input" placeholder="Digite para buscar..." autocomplete="off" style="width:100%;padding:9px 12px;border:1.5px solid #e0e0e0;border-radius:7px;font-size:0.9em;box-sizing:border-box;" oninput="depCompMostrarDropdown()" onfocus="depCompMostrarDropdown()" onblur="setTimeout(depCompFecharDropdown,300)">
        <div id="depComp-dropdown" style="display:none;position:absolute;top:100%;left:0;right:0;background:white;border:1.5px solid #e0e0e0;border-radius:0 0 7px 7px;max-height:220px;overflow-y:auto;z-index:50;box-shadow:0 4px 16px rgba(0,0,0,0.12);"></div>
      </div>
    </div>`;
}

window._depComponentesSel = [];

/**
 * Dependências técnicas que podem virar componente da que está aberta: fora
 * ela mesma, quem já está acima dela (fecharia um ciclo) e as já escolhidas.
 * Instalação como componente ("instalada em") só para dependência técnica:
 * Instalação dentro de Instalação não é um local físico, é contingência --
 * para isso existe "Instalação alternativa" (21/10/2026).
 */
const _depAbertaEhInstalacao = () => _ehInstalacao((document.getElementById('depCategoria') || {}).value);

function _depCompDisponiveis(filtro) {
  const selfId = (document.getElementById('depId') || {}).value || '';
  const bloqueados = new Set(ServicoComposicao.bloqueadosComoComponente(selfId, dependenciasData).map(String));
  const termo = (filtro || '').toLowerCase();
  const semInstalacoes = _depAbertaEhInstalacao();
  return (dependenciasData || []).filter((d) =>
    DEPENDENCIA_CATEGORIAS_CATALOGO.includes(d.categoria) &&
    !(semInstalacoes && _ehInstalacao(d.categoria)) &&
    d.id && !String(d.id).startsWith('_tmp_') &&
    !bloqueados.has(String(d.id)) &&
    !window._depComponentesSel.some((s) => String(s.id) === String(d.id)) &&
    (termo === '' || (d.nome || '').toLowerCase().includes(termo))
  ).sort((a, b) => (a.nome || '').localeCompare(b.nome || '', 'pt-BR'));
}

function renderDepComponentesTags() {
  const cont = document.getElementById('depComp-tags');
  if (!cont) return;
  const sel = window._depComponentesSel || [];
  // Instalação já gravada como componente de outra Instalação (antes da
  // restrição): continua visível, em laranja, para ser removida -- nada some sozinho.
  const instEmInst = _depAbertaEhInstalacao();
  cont.innerHTML = sel.length ? sel.map((item, i) => {
    const naoSeAplica = instEmInst && _ehInstalacao(item.categoria);
    const cor = naoSeAplica ? '#e65100' : '#d60014';
    return `<span class="${naoSeAplica ? 'dep-comp--nao-se-aplica' : ''}" style="display:inline-flex;align-items:center;gap:4px;background:${naoSeAplica ? '#fff3e0' : cor};color:${naoSeAplica ? cor : 'white'};border:1.5px solid ${cor};padding:4px 8px 4px 12px;border-radius:14px;font-size:0.85em;font-weight:500;white-space:nowrap;" title="${esc(naoSeAplica ? 'Instalação não fica dentro de outra Instalação — para contingência use "Instalação alternativa". Remova este componente.' : (item.categoria || ''))}">${esc(_iconeCategoriaDep(item.categoria))} ${esc(item.nome)}${naoSeAplica ? ' ⚠' : ''}<button onclick="removerDepComponente(${i})" style="background:none;border:none;cursor:pointer;font-size:1.1em;color:${naoSeAplica ? 'rgba(0,0,0,0.4)' : 'rgba(255,255,255,0.75)'};line-height:1;padding:0 3px;" title="Remover">&times;</button></span>`;
  }).join(' ') + (sel.some((item) => instEmInst && _ehInstalacao(item.categoria))
    ? '<div style="width:100%;font-size:0.74em;color:#e65100;margin-top:2px;">⚠ Instalação não fica dentro de outra Instalação. Para contingência, use "Instalação alternativa" acima.</div>' : '')
    : '<span style="font-size:0.82em;color:#bbb;font-style:italic;">Nenhum componente abaixo desta dependência.</span>';
}

window.depCompMostrarDropdown = () => {
  const input = document.getElementById('depComp-input');
  const dd = document.getElementById('depComp-dropdown');
  if (!input || !dd) return;
  const disp = _depCompDisponiveis(input.value.trim());
  if (!disp.length) {
    dd.innerHTML = '<div style="padding:8px 12px;font-size:0.84em;color:#999;">Nenhuma dependência disponível.</div>';
    dd.style.display = 'block';
    return;
  }
  dd.innerHTML = disp.slice(0, 30).map((d) =>
    `<div onmousedown="event.preventDefault();selecionarDepComponente('${escJs(d.id)}');" style="padding:8px 12px;cursor:pointer;font-size:0.86em;border-bottom:1px solid #f0f0f0;" onmouseenter="this.style.background='#f5f6fa'" onmouseleave="this.style.background='white'">${esc(_iconeCategoriaDep(d.categoria))} ${esc(d.nome)} <span style="color:#999;font-size:0.85em;">(${esc(d.categoria)})</span></div>`
  ).join('');
  dd.style.display = 'block';
};

window.depCompFecharDropdown = () => {
  const dd = document.getElementById('depComp-dropdown');
  if (dd) dd.style.display = 'none';
};

window.selecionarDepComponente = (id) => {
  const d = (dependenciasData || []).find((x) => String(x.id) === String(id));
  if (!d) return;
  if (_depAbertaEhInstalacao() && _ehInstalacao(d.categoria)) return;
  window._depComponentesSel.push({ id: d.id, nome: d.nome, categoria: d.categoria });
  document.getElementById('depComp-input').value = '';
  depCompFecharDropdown();
  renderDepComponentesTags();
};

window.removerDepComponente = (i) => {
  window._depComponentesSel.splice(i, 1);
  renderDepComponentesTags();
};

/**
 * Bloco somente leitura "Está abaixo de": dependências que têm esta como
 * componente e Serviços que a usam diretamente. A posse do vínculo é do lado
 * de cima, então aqui só se mostra (e o clique leva até lá).
 */
async function _renderAcimaDaDependencia(d) {
  const cont = document.getElementById('depAcimaDe');
  if (!cont) return;
  if (!d || !d.id) { cont.innerHTML = ''; return; }
  let servicos = [];
  try { servicos = await API.getServicos(); } catch (e) { servicos = []; }
  if ((document.getElementById('depId') || {}).value !== String(d.id)) return; // drawer já trocou de registro
  const acima = ServicoComposicao.acimaDe(d.id, dependenciasData, servicos);
  const alternativaDe = (dependenciasData || []).filter((x) => _ehInstalacao(x.categoria) && x.instalacaoAlternativa && String(x.instalacaoAlternativa.id) === String(d.id));
  const itens = [
    ...alternativaDe.map((x) => `<span onclick="editarDep('${escJs(x.id)}')" style="cursor:pointer;display:inline-block;padding:3px 10px;border-radius:12px;font-size:0.8em;background:white;border:1px solid #e0e0e0;color:#333;" title="Abrir ${esc(x.nome)}">📍 ${esc(x.nome)} <span style="color:#999;">(contingência dela)</span></span>`),
    ...acima.servicos.map((s) => `<span style="display:inline-block;padding:3px 10px;border-radius:12px;font-size:0.8em;background:white;border:1px solid #e0e0e0;color:#333;">🧩 ${esc(s.nome)} <span style="color:#999;">(Serviço)</span></span>`),
    ...acima.dependencias.map((x) => `<span onclick="editarDep('${escJs(x.id)}')" style="cursor:pointer;display:inline-block;padding:3px 10px;border-radius:12px;font-size:0.8em;background:white;border:1px solid #e0e0e0;color:#333;" title="Abrir ${esc(x.nome)}">${esc(_iconeCategoriaDep(x.categoria))} ${esc(x.nome)} <span style="color:#999;">(${esc(x.categoria)})</span></span>`),
  ];
  cont.innerHTML = `<div style="border-left:3px solid #d60014;background:#fffafa;padding:10px 14px;border-radius:0 6px 6px 0;">
    <div style="font-size:0.78em;font-weight:700;color:#444;text-transform:uppercase;letter-spacing:0.4px;margin-bottom:6px;">Está abaixo de</div>
    ${itens.length ? `<div style="display:flex;flex-wrap:wrap;gap:6px;">${itens.join('')}</div>` : '<div style="font-size:0.82em;color:#999;">Nenhum Serviço ou dependência usa esta como componente.</div>'}
    <div style="font-size:0.72em;color:#999;margin-top:6px;">O vínculo é feito no item de cima (Serviço ou dependência).</div>
  </div>`;
}

function _htmlDrawerDependencia() {
  return `
    <div class="drawer-overlay" id="drawerOverlayDependencia" onclick="fecharDrawerDependencia()"></div>
    <div class="drawer" id="drawerDependencia">
      <div class="drawer-header">
        <h3 id="depDrawerTitulo">Nova Dependência</h3>
        <button onclick="fecharDrawerDependencia()" style="background:none;border:none;font-size:1.4em;cursor:pointer;color:#999;line-height:1;">&times;</button>
      </div>
      <div class="drawer-body" style="padding:0;display:flex;flex-direction:column;">
        <div style="display:flex;border-bottom:2px solid #fce8ea;background:white;flex-shrink:0;">
          <button id="tab-dep-geral" onclick="trocarAbaDependencia('geral')" style="flex:1;padding:10px 20px;border:none;background:none;font-size:0.88em;font-weight:700;color:#d60014;border-bottom:3px solid #d60014;cursor:pointer;">Dados Gerais</button>
          <button id="tab-dep-drp" onclick="trocarAbaDependencia('drp')" style="flex:1;padding:10px 20px;border:none;background:none;font-size:0.88em;font-weight:700;color:#999;border-bottom:3px solid transparent;cursor:pointer;">Parâmetros DRP</button>
          <button id="tab-dep-plano" onclick="trocarAbaDependencia('plano')" style="flex:1;padding:10px 20px;border:none;background:none;font-size:0.88em;font-weight:700;color:#999;border-bottom:3px solid transparent;cursor:pointer;">Plano de Recuperação</button>
          <button id="tab-dep-registros" onclick="trocarAbaDependencia('registros')" style="flex:1;padding:10px 20px;border:none;background:none;font-size:0.88em;font-weight:700;color:#999;border-bottom:3px solid transparent;cursor:pointer;">Gestão de Testes</button>
          <button id="tab-dep-processos" onclick="trocarAbaDependencia('processos')" style="flex:1;padding:10px 20px;border:none;background:none;font-size:0.88em;font-weight:700;color:#999;border-bottom:3px solid transparent;cursor:pointer;">Processos</button>
        </div>
        <div style="flex:1;overflow-y:auto;padding:20px 24px;">
          <input type="hidden" id="depId">

          <div id="painel-dep-geral">
            <div style="display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-bottom:14px;">
              <div>
                <label style="display:block;font-size:0.78em;font-weight:700;color:#444;text-transform:uppercase;letter-spacing:0.4px;margin-bottom:5px;">Categoria <span class="req" aria-hidden="true">*</span></label>
                <select id="depCategoria" onchange="_atualizarBlocoInstalacao()" style="width:100%;padding:9px 12px;border:1.5px solid #e0e0e0;border-radius:7px;font-size:0.93em;box-sizing:border-box;">
                  <option value="">Selecione...</option>
                  ${DEPENDENCIA_CATEGORIAS_CATALOGO.map(c => `<option value="${c}">${c}</option>`).join('')}
                </select>
              </div>
              <div>
                <label style="display:block;font-size:0.78em;font-weight:700;color:#444;text-transform:uppercase;letter-spacing:0.4px;margin-bottom:5px;">Nome <span class="req" aria-hidden="true">*</span></label>
                <input type="text" id="depNome" placeholder="Ex: Switches e roteadores" style="width:100%;padding:9px 12px;border:1.5px solid #e0e0e0;border-radius:7px;font-size:0.93em;box-sizing:border-box;">
              </div>
            </div>
            <div style="margin-bottom:14px;">
              <label style="display:block;font-size:0.78em;font-weight:700;color:#444;text-transform:uppercase;letter-spacing:0.4px;margin-bottom:5px;">Papel</label>
              <textarea id="depDetalhes" rows="3" placeholder="Papel ou função desta dependência" style="width:100%;padding:9px 12px;border:1.5px solid #e0e0e0;border-radius:7px;font-size:0.93em;box-sizing:border-box;resize:vertical;font-family:inherit;"></textarea>
            </div>
            ${_htmlDadosInstalacao()}
            ${_htmlDepComponentes()}
            <div id="depAcimaDe" style="margin-top:18px;"></div>
          </div>

          <div id="painel-dep-drp" style="display:none;">
            <div id="depSlasContratados"></div>
            <div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:16px;margin-bottom:6px;">
              ${_htmlCampoDuracao('depRto', 'RTO', 'Tempo para voltar a funcionar')}
              ${_htmlCampoDuracao('depRpo', 'RPO', 'Perda de dados tolerada')}
              ${_htmlCampoDuracao('depMttr', 'MTTR', 'Tempo médio de reparo')}
            </div>
            <p style="font-size:0.75em;color:#888;margin:0 0 14px;">Entram na soma do caminho crítico dos Serviços acima desta dependência.</p>
            <div style="margin-bottom:14px;">
              <label style="display:block;font-size:0.78em;font-weight:700;color:#444;text-transform:uppercase;letter-spacing:0.4px;margin-bottom:8px;">Estratégia de contingência</label>
              <input type="hidden" id="depEstrategia" value="">
              <div id="chips-depEstrategia" style="display:flex;flex-wrap:wrap;gap:8px;"></div>
            </div>
            <div style="margin-bottom:14px;">
              <label style="display:block;font-size:0.78em;font-weight:700;color:#444;text-transform:uppercase;letter-spacing:0.4px;margin-bottom:5px;">Área Responsável</label>
              <select id="depResponsavel" style="width:100%;padding:9px 12px;border:1.5px solid #e0e0e0;border-radius:7px;font-size:0.93em;box-sizing:border-box;">
                <option value="">Selecione...</option>
              </select>
            </div>
            ${_htmlDrpLista('drpCriteriosAcionamento', 'Critérios de Acionamento do DRP', 'Ex: Indisponibilidade do serviço por mais de 30 minutos confirmada pelo monitoramento')}
            ${_htmlDrpLista('drpPreRequisitos', 'Pré-requisitos', 'Ex: Backup íntegro das últimas 24h disponível e validado')}
            ${_htmlDrpDependencias()}
            ${_htmlDrpLista('drpHealthCheck', 'Checklist de Verificação e Diagnóstico (Health Check)', 'Ex: Infraestrutura/Cloud: o ambiente está acessível?')}
            ${_htmlDrpLista('drpRunbook', 'Fase Executiva de Recuperação (Runbook de Restore)', 'Ex: Restaurar o banco de dados a partir do último backup íntegro')}
            ${_htmlDrpLista('drpCriteriosRetorno', 'Critérios de Retorno à Normalidade', 'Ex: Auditoria e conciliação manual (duplicidade ou erros)')}
            ${_htmlDrpLista('drpLimitacoes', 'Limitações Conhecidas da Estratégia', 'Ex: Dependência direta de provedores de internet e nuvem de terceiros')}
            ${_htmlDrpTestes()}
          </div>

          <div id="painel-dep-plano" style="display:none;">
            ${_htmlDrpPlano()}
          </div>

          <div id="painel-dep-registros" style="display:none;">
            ${_htmlDrpRoteiros()}
            <div style="border-top:1px solid #eee;margin-top:18px;padding-top:14px;">
              ${_htmlDrpRegistros()}
            </div>
          </div>

          <div id="painel-dep-processos" style="display:none;">
            <div id="depProcessosTabela"></div>
          </div>
        </div>
      </div>
      <div class="drawer-footer">
        <button class="btn btn-ghost" onclick="fecharDrawerDependencia()">Fechar</button>
        ${_seVeTela('mapa', '<button class="btn btn-ghost" onclick="verNoMapa(\'dependencia\')">🗺️ Ver no mapa</button>')}
        <button class="btn btn-primary" id="btnSalvarDep" onclick="salvarDep()">Salvar</button>
      </div>
    </div>
    ${_htmlModalEscolherTipoTeste()}`;
}

/** Título do drawer de Dependência com o nome como subtítulo -- espelha _atualizarTituloDrawerRisco. */
function _atualizarTituloDrawerDependencia(d) {
  const titulo = (d && d.id) ? 'Editar Dependência' : 'Nova Dependência';
  const nome = d && d.nome ? String(d.nome).trim() : '';
  const subtitulo = nome ? `<div style="font-size:0.75em;color:#555;font-weight:400;margin-top:4px;">${esc(nome)}</div>` : '';
  document.getElementById('depDrawerTitulo').innerHTML = titulo + subtitulo;
}

window.abrirDrawerDependencia = (d) => {
  document.getElementById('depId').value = d ? d.id : '';
  document.getElementById('depCategoria').value = d ? d.categoria : '';
  document.getElementById('depTipoInstalacao').value = d ? (d.tipoInstalacao || '') : '';
  document.getElementById('depEndereco').value = d ? (d.endereco || '') : '';
  _atualizarBlocoInstalacao(d && d.instalacaoAlternativa ? d.instalacaoAlternativa.id : '');
  document.getElementById('depNome').value = d ? d.nome : '';
  document.getElementById('depDetalhes').value = d ? (d.detalhes || '') : '';
  // Sem rtoMin/rpoMin ainda (antes da migracao), o texto legado e convertido
  // para a tela; o que nao converter aparece como aviso abaixo do campo.
  _preencherCampoDuracao('depRto', d ? ServicoComposicao.valorMin(d, 'rto') : null, d ? d.rto : '');
  _preencherCampoDuracao('depRpo', d ? ServicoComposicao.valorMin(d, 'rpo') : null, d ? d.rpo : '');
  _preencherCampoDuracao('depMttr', d ? ServicoComposicao.valorMin(d, 'mttr') : null, '');
  window._depComponentesSel = d && Array.isArray(d.componentes)
    ? d.componentes.filter((x) => x && x.id).map((x) => ({ id: x.id, nome: x.nome || '', categoria: x.categoria || '' }))
    : [];
  document.getElementById('depComp-input').value = '';
  depCompFecharDropdown();
  renderDepComponentesTags();
  _renderAcimaDaDependencia(d);
  document.getElementById('depEstrategia').value = d ? (d.estrategia || '') : '';
  renderEstrategiaChips();
  _popularSelectAreaResponsavelDep(d ? (d.responsavel || '') : '');
  window._depDrpListas = {
    drpCriteriosAcionamento: d && Array.isArray(d.drpCriteriosAcionamento) ? [...d.drpCriteriosAcionamento] : [],
    drpPreRequisitos: d && Array.isArray(d.drpPreRequisitos) ? [...d.drpPreRequisitos] : [],
    drpHealthCheck: d && Array.isArray(d.drpHealthCheck) ? [...d.drpHealthCheck] : [],
    drpRunbook: d && Array.isArray(d.drpRunbook) ? [...d.drpRunbook] : [],
    drpCriteriosRetorno: d && Array.isArray(d.drpCriteriosRetorno) ? [...d.drpCriteriosRetorno] : [],
    drpLimitacoes: d && Array.isArray(d.drpLimitacoes) ? [...d.drpLimitacoes] : [],
  };
  window._depDrpEditando = { drpCriteriosAcionamento: null, drpPreRequisitos: null, drpHealthCheck: null, drpRunbook: null, drpCriteriosRetorno: null, drpLimitacoes: null };
  ['drpCriteriosAcionamento', 'drpPreRequisitos', 'drpHealthCheck', 'drpRunbook', 'drpCriteriosRetorno', 'drpLimitacoes'].forEach((c) => {
    document.getElementById('novoItem-' + c).value = '';
    document.getElementById('btnAdicionar-' + c).textContent = '+ Adicionar';
    renderDrpLista(c);
  });
  // Seção "Dependências" (seletor do catálogo).
  window._depDrpDependenciasSel = d && Array.isArray(d.drpDependencias)
    ? d.drpDependencias.map((x) => ({ id: x.id != null ? x.id : null, nome: x.nome || '', categoria: x.categoria || 'Outros' }))
    : [];
  document.getElementById('drpDep-input').value = '';
  drpDepFecharDropdown();
  renderDrpDependenciasTags();
  // Seção "Testes do procedimento" (registro único).
  // Testes do Procedimento: Estratégias (Parâmetros DRP) + Registros (aba).
  window._depDrpEstrategias = d && Array.isArray(d.drpEstrategiasTeste)
    ? d.drpEstrategiasTeste.map((e) => ({ cenario: e.cenario || '', frequencia: e.frequencia || '' }))
    : [];
  window._depDrpRegistros = d && Array.isArray(d.drpRegistrosTeste)
    ? d.drpRegistrosTeste.map((r) => ({ data: r.data || '', resultado: r.resultado || '', evidencia: r.evidencia || '', pendencias: r.pendencias || '' }))
    : [];
  window._depDrpRoteiros = d && Array.isArray(d.drpRoteirosTeste)
    ? d.drpRoteirosTeste.map((r) => ({ categoria: r.categoria || '', versao: r.versao || 0, data: r.data || '', autor: r.autor || '' }))
    : [];
  // Migração não-destrutiva: se ainda não há listas mas existe o drpTestes
  // antigo (registro único) com conteúdo, semeia 1 estratégia + 1 registro.
  const t = (d && d.drpTestes && typeof d.drpTestes === 'object') ? d.drpTestes : {};
  if (!window._depDrpEstrategias.length && (t.cenarioTestado || t.frequenciaEsperada)) {
    window._depDrpEstrategias.push({ cenario: t.cenarioTestado || '', frequencia: t.frequenciaEsperada || '' });
  }
  if (!window._depDrpRegistros.length && (t.dataUltimoTeste || t.resultado || t.evidencia || t.pendencias)) {
    window._depDrpRegistros.push({ data: t.dataUltimoTeste || '', resultado: t.resultado || '', evidencia: t.evidencia || '', pendencias: t.pendencias || '' });
  }
  renderDrpEstrategiasTeste();
  renderDrpRoteirosTeste();
  renderDrpRegistrosTeste();
  // Aba "Plano de Recuperação": template importado + preview do DRP salvo.
  window._depDrpTemplate = d && d.drpTemplate ? String(d.drpTemplate) : '';
  window._depDrpTemplateNome = d && d.drpTemplateNome ? String(d.drpTemplateNome) : '';
  renderDrpResumo();
  _atualizarTituloDrawerDependencia(d);
  _renderProcessosDaDependencia(d);
  trocarAbaDependencia('geral');
  document.getElementById('drawerDependencia').classList.add('open');
  document.getElementById('drawerOverlayDependencia').classList.add('open');
  // Rascunho (categoria/nome sugeridos, sem id) não existe no banco: o Fechar
  // tem que gravar, nunca tratar como "sem mudança".
  if (d && !d.id) _edDep.esquecer(); else _edDep.marcar();
};

/**
 * Processos de Negócio que dependem de uma dependência do catálogo: casa por
 * dependenciaItens[].id -- ou, pra vínculo legado sem id, por nome (mesmo
 * critério de _adivinharDependenciaLegada), com categoria como desempate
 * quando o item legado já tiver uma gravada. Reaproveitado pela aba
 * "Processos" do drawer de Dependência e pelo relatório "Processos por
 * Dependência" -- mesma regra de vínculo, um único lugar.
 */
/**
 * Rede para a cadeia Processo -> Serviço -> componentes: os serviços e o
 * catálogo que a tela já tem carregados, ou null (aí só o vínculo direto).
 */
function _redeCadeiaCarregada(dependencias) {
  const servicos = (window.servicosCatalogoProcesso && window.servicosCatalogoProcesso.length) ? window.servicosCatalogoProcesso
    : (typeof servicosData !== 'undefined' && servicosData && servicosData.length ? servicosData : null);
  const deps = dependencias || ((window.dependenciasCatalogo && window.dependenciasCatalogo.length) ? window.dependenciasCatalogo : null);
  return servicos && deps ? { servicos, dependencias: deps } : null;
}

/**
 * Processos que dependem da dependência. Com a rede (serviços + catálogo),
 * pela cadeia inteira -- direto, por um item acima dela nos componentes ou por
 * um Serviço que a usa (CadeiaDependencias.processosQueDependemDe). `rede`:
 * objeto explícito, `false` para só o vínculo direto (Pessoa, 4 P), ou
 * omitido para usar o que a tela já carregou.
 */
function _processosVinculadosADependencia(dependencia, processos, rede) {
  const r = rede === false ? null : (rede || _redeCadeiaCarregada());
  if (r && dependencia && dependencia.id && (r.dependencias || []).some((d) => String(d.id) === String(dependencia.id))) {
    return CadeiaDependencias.processosQueDependemDe(dependencia.id, { processos, servicos: r.servicos, dependencias: r.dependencias }).map((x) => x.processo);
  }
  return _processosVinculadosDiretos(dependencia, processos);
}

function _processosVinculadosDiretos(dependencia, processos) {
  return (processos || []).filter((p) => Array.isArray(p.dependenciaItens) && p.dependenciaItens.some((item) =>
    item.id ? item.id === dependencia.id : (item.nome === dependencia.nome && (!item.categoria || item.categoria === dependencia.categoria))
  ));
}

/**
 * Aba "Processos": lista os Processos de Negócio que dependem desta
 * dependência. Só faz sentido pra dependência já salva (sem id, nenhum
 * processo pode apontar pra ela ainda).
 */
async function _renderProcessosDaDependencia(d) {
  const cont = document.getElementById('depProcessosTabela');
  if (!cont) return;
  if (!d || !d.id) {
    cont.innerHTML = '<p style="font-size:0.85em;color:#999;padding:8px 0;">Salve a dependência para ver os processos vinculados.</p>';
    return;
  }
  cont.innerHTML = '<p style="font-size:0.85em;color:#999;padding:8px 0;">⏳ Carregando...</p>';
  let processos, servicos;
  try {
    [processos, servicos] = await Promise.all([API.getProcessos(), API.getServicos().catch(() => [])]);
  } catch (e) {
    cont.innerHTML = '<p style="font-size:0.85em;color:#c62828;padding:8px 0;">Não foi possível carregar os processos.</p>';
    return;
  }
  // Pela cadeia (21/10/2026): direto, via Serviço ou via um item acima nos componentes.
  const catalogo = (dependenciasData && dependenciasData.length) ? dependenciasData : (window.dependenciasCatalogo || []);
  const comOrigem = catalogo.some((x) => String(x.id) === String(d.id))
    ? CadeiaDependencias.processosQueDependemDe(d.id, { processos, servicos, dependencias: catalogo })
    : _processosVinculadosDiretos(d, processos).map((p) => ({ processo: p, origens: ['Direta'] }));
  const vinculados = comOrigem.map((x) => x.processo);
  const origemDe = new Map(comOrigem.map((x) => [String(x.processo.id), x.origens.join('; ')]));
  if (!vinculados.length) {
    cont.innerHTML = '<p class="vazio-inline">Nenhum processo vinculado a esta dependência.</p>';
    return;
  }
  cont.innerHTML = `<table style="width:100%;border-collapse:collapse;font-size:0.9em;">
    <thead>
      <tr>
        <th style="padding:10px 0;text-align:left;font-weight:600;color:#555;font-size:0.82em;border-bottom:1.5px solid #e0e0e0;">Área</th>
        <th style="padding:10px 0;text-align:left;font-weight:600;color:#555;font-size:0.82em;border-bottom:1.5px solid #e0e0e0;">Processo</th>
        <th style="padding:10px 0;text-align:left;font-weight:600;color:#555;font-size:0.82em;border-bottom:1.5px solid #e0e0e0;width:30%;">Tier</th>
      </tr>
    </thead>
    <tbody>
      ${vinculados.map((p) => {
        const tier = Criticidade.tierDoProcesso(p);
        return `<tr style="cursor:pointer;" onclick="window.location.hash='processos'" title="Ir para a tela Processos">
          <td style="padding:10px 0;border-bottom:1px solid #f0f0f0;color:#222;">${esc(p.area)}</td>
          <td style="padding:10px 0;border-bottom:1px solid #f0f0f0;color:#222;font-weight:500;">${esc(p.processo)}<div class="origem-vinculo" style="font-size:0.78em;color:#888;font-weight:400;">${esc(origemDe.get(String(p.id)) || '')}</div></td>
          <td style="padding:10px 0;border-bottom:1px solid #f0f0f0;">${_htmlBadge(_nivelTierProcesso(tier), tier)}</td>
        </tr>`;
      }).join('')}
    </tbody>
  </table>`;
}

function _fecharDrawerDependenciaSemSalvar() {
  document.getElementById('drawerDependencia').classList.remove('open');
  document.getElementById('drawerOverlayDependencia').classList.remove('open');
  window._backupNovoServidor = null;
  window._servicoNovaDependenciaCategoria = null;
  _reabrirDrawerPaiSeEscondido();
}
// Fechar/×/clique fora/Esc: sem mudança fecha; com mudança pergunta Salvar/Descartar/Continuar (DECISÃO 16/10/2026, _fecharComRastreador).
window.fecharDrawerDependencia = () => _fecharComRastreador({
  idDrawer: 'drawerDependencia',
  sujo: () => _edDep.sujo(),
  salvar: () => salvarDep(),
  fecharSemSalvar: _fecharDrawerDependenciaSemSalvar,
});

const _edDep = criarRastreadorEdicao(() => _coletarFormularioDependencia());

// Só o que a pessoa edita nesta tela. Os campos que o salvar apenas preserva
// do registro (setor, empresa, drpSalvo, drpRoteirosTeste...) ficam de fora de
// propósito: gerar um DRP muda drpSalvo em memória sem a pessoa ter editado
// nada, e isso não pode contar como "mudou o formulário".
function _coletarFormularioDependencia() {
  return {
    id: document.getElementById('depId').value || null,
    categoria: document.getElementById('depCategoria').value.trim(),
    nome: document.getElementById('depNome').value.trim(),
    detalhes: document.getElementById('depDetalhes').value.trim(),
    rtoMin: _lerCampoDuracao('depRto'),
    rpoMin: _lerCampoDuracao('depRpo'),
    mttrMin: _lerCampoDuracao('depMttr'),
    componentes: (window._depComponentesSel || []).map((x) => ({ id: x.id, nome: x.nome, categoria: x.categoria })),
    ..._coletarDadosInstalacao(document.getElementById('depCategoria').value.trim()),
    estrategia: document.getElementById('depEstrategia').value,
    responsavel: document.getElementById('depResponsavel').value,
    drpCriteriosAcionamento: window._depDrpListas.drpCriteriosAcionamento || [],
    drpPreRequisitos: window._depDrpListas.drpPreRequisitos || [],
    drpHealthCheck: window._depDrpListas.drpHealthCheck || [],
    drpRunbook: window._depDrpListas.drpRunbook || [],
    drpCriteriosRetorno: window._depDrpListas.drpCriteriosRetorno || [],
    drpLimitacoes: window._depDrpListas.drpLimitacoes || [],
    drpDependencias: (window._depDrpDependenciasSel || []).map((x) => ({ id: x.id != null ? x.id : null, nome: x.nome, categoria: x.categoria || 'Outros' })),
    // Estratégias de Teste (Parâmetros DRP) e histórico de Registros (aba).
    drpEstrategiasTeste: (window._depDrpEstrategias || []).map((e) => ({ cenario: e.cenario || '', frequencia: e.frequencia || '' })),
    drpRegistrosTeste: (window._depDrpRegistros || []).map((r) => ({ data: r.data || '', resultado: r.resultado || '', evidencia: r.evidencia || '', pendencias: r.pendencias || '' })),
    // Aba Plano de Recuperação: template importado.
    drpTemplate: window._depDrpTemplate || '',
    drpTemplateNome: window._depDrpTemplateNome || '',
  };
}

window.editarDep = (id) => {
  const d = dependenciasData.find(x => x.id === id);
  if (d) abrirDrawerDependencia(d);
};

window.excluirDep = async (id) => {
  if (!await confirmarAcao('Excluir esta dependência?')) return;
  try {
    await API.excluirDependencia(id);
    dependenciasData = dependenciasData.filter(x => x.id !== id);
    renderizarDependencias();
    showToast('✅ Excluída!', '#2e7d32');
    API.invalidate('getDependencias');
  } catch(e) { showToast('❌ ' + _mensagemErro(e), '#c62828'); }
};

window.salvarDep = async () => {
  const idAtual = document.getElementById('depId').value || null;
  // Setor/Empresa/Telefone/Email/Endereco sairam do formulario (so fazem
  // sentido pra Fornecedor, que tem tela propria pra eles) -- preserva o que
  // ja estava gravado no registro em vez de reenviar vazio, que apagaria em
  // silencio um dado antigo no proximo merge:true (_salvarDependencia grava
  // esses campos sempre, e e a mesma funcao compartilhada com Fornecedor).
  const existente = idAtual ? dependenciasData.find((x) => x.id === idAtual) : null;
  // Foto do formulário no clique -- é ela que vira "limpo" depois de gravar.
  const estadoDoFormulario = _coletarFormularioDependencia();
  const d = {
    ...estadoDoFormulario,
    setor: existente ? (existente.setor || '') : '',
    empresa: existente ? (existente.empresa || '') : '',
    telefone: existente ? (existente.telefone || '') : '',
    email: existente ? (existente.email || '') : '',
    // Endereço: da instalação vem do formulário (bloco "Dados da instalação");
    // nas outras categorias segue preservado do registro.
    endereco: _ehInstalacao(estadoDoFormulario.categoria) ? (estadoDoFormulario.endereco || '') : (existente ? (existente.endereco || '') : ''),
    // Roteiros de Teste: gerado/apagado só pelo fluxo próprio (gerarRoteiroTeste/
    // excluirRoteiroTeste) -- aqui só preserva o que já existe, mesmo tratamento
    // de drpSalvo logo abaixo.
    drpRoteirosTeste: existente ? (existente.drpRoteirosTeste || []) : [],
    // drpTestes (registro único antigo) não é mais editado pela UI -- preserva
    // o que já estava gravado (fonte da migração e fallback do gerarDRP).
    drpTestes: existente && existente.drpTestes ? existente.drpTestes : undefined,
    // drpSalvo (versões do artefato) é gravado pelo fluxo próprio (salvarDRP)
    // -- aqui só preserva o que já existe pra não sumir do objeto em memória
    // no merge otimista.
    drpSalvo: existente ? (existente.drpSalvo || '') : '',
    // Texto de compatibilidade (DRP/PCN/SLA de contrato leem rto/rpo em texto).
    // Campo vazio preserva o texto antigo que nao pode ser convertido.
    rto: _textoCampoDuracao('depRto') || (estadoDoFormulario.rtoMin === null && existente ? (existente.rto || '') : ''),
    rpo: _textoCampoDuracao('depRpo') || (estadoDoFormulario.rpoMin === null && existente ? (existente.rpo || '') : ''),
  };
  if (!d.categoria) return _avisarCampo('depCategoria', 'Informe a categoria.');
  if (!d.nome) return _avisarCampo('depNome', 'Informe o nome.');
  // Sem esta guarda, digitar "Fornecedores" no campo de categoria criaria um
  // fornecedor que esta tela nao mostra mais: sumiria da vista de quem acabou
  // de cadastrar.
  if (Perfis.categoriaDeFornecedor(d.categoria)) {
    return showToast('Fornecedor é cadastrado em Fornecedores → Cadastro.', '#e65100');
  }

  // Capturados ANTES de fechar o drawer: fecharDrawerDependencia() reabre o
  // drawer de origem (se for o caso) e limpa essas flags como efeito colateral.
  const veioDoBackup = !!window._backupNovoServidor;
  const veioDoServico = !!window._servicoNovaDependenciaCategoria;
  const aninhado = veioDoBackup || veioDoServico;
  // Cadastro rápido genérico (_abrirCadastroRapido): o drawer espera a gravação
  // real e só então devolve a dependência, com o id definitivo, para a origem.
  const cadastroRapido = !aninhado && _temDrawerPaiEmpilhado();

  // Optimistic: atualizar a UI imediatamente; só FECHA o drawer quando foi
  // aberto por cima de outro (cadastro rápido de Servidor/Serviço a partir do
  // Backup/Serviço) -- aí sim o sentido é "crie rapidinho e volte". Direto do
  // catálogo, fica aberto (padrão "Fechar + Salvar", igual o resto do sistema).
  if (aninhado) _fecharDrawerDependenciaSemSalvar();
  // Sem fechar, o usuário pode clicar "Salvar" de novo antes da gravação real
  // terminar -- desabilita o botão até lá pra não criar duas dependências.
  const btnSalvarDep = document.getElementById('btnSalvarDep');
  if (!aninhado && btnSalvarDep) btnSalvarDep.disabled = true;
  const isNew = !d.id;
  let tempId = null;
  if (d.id) {
    const idx = dependenciasData.findIndex(x => x.id === d.id);
    if (idx !== -1) dependenciasData[idx] = { ...d };
  } else {
    tempId = '_tmp_' + Date.now(); // ID temporário (apenas para UI)
    d.id = tempId;
    dependenciasData.push(d);
  }
  _refreshAposSalvarDependencia();
  window.dependenciasCatalogo = dependenciasData;
  showToast('⏳ Salvando...', '#d60014');

  try {
    // Enviar ao backend SEM o ID temporário para novos registros
    const payload = { ...d };
    if (isNew) payload.id = null;
    const result = await API.salvarDependencia(payload);
    _edDep.marcar({ ...estadoDoFormulario, id: isNew ? result.id : estadoDoFormulario.id });
    // Atualizar ID real se era novo
    if (isNew && result.id) {
      const tempIdx = dependenciasData.findIndex(x => x.id === tempId);
      if (tempIdx !== -1) dependenciasData[tempIdx].id = result.id;
      if (!aninhado) {
        // Sem fechar o drawer, o próximo "Salvar" precisa gravar no MESMO
        // registro em vez de criar uma segunda dependência idêntica.
        document.getElementById('depId').value = result.id;
        _atualizarTituloDrawerDependencia({ ...d, id: result.id });
      }
    }
    if (!aninhado && btnSalvarDep) btnSalvarDep.disabled = false;
    API.invalidate('getDependencias');
    if (cadastroRapido && result.id) _entregarCadastroRapido({ ...d, id: result.id }, _fecharDrawerDependenciaSemSalvar);
    // Cadastro rápido de Servidor a partir do Backup: seleciona com o id REAL
    // (nunca o id temporário otimista acima) -- é exatamente o cuidado que
    // evita recriar a "referência fantasma" já corrigida uma vez neste
    // projeto (ver a decisão de 24/09/2026 sobre Componentes do Serviço).
    if (veioDoBackup && document.getElementById('backupServidor')) {
      _popularSelectBackupServidor(result.id);
    }
    // Mesmo cadastro rápido, agora a partir do drawer de Serviço (Dependências
    // do Serviço) -- mesmo cuidado de só vincular com o id real.
    if (veioDoServico && document.getElementById('servicoDependenciasPorCategoria')) {
      window._servicoDependencias = window._servicoDependencias || [];
      window._servicoDependencias.push({ categoria: d.categoria, nome: d.nome, id: result.id });
      window._servicoDependenciasCatalogoPorCategoria = window._servicoDependenciasCatalogoPorCategoria || {};
      if (!window._servicoDependenciasCatalogoPorCategoria[d.categoria]) window._servicoDependenciasCatalogoPorCategoria[d.categoria] = [];
      window._servicoDependenciasCatalogoPorCategoria[d.categoria].push({ nome: d.nome, id: result.id });
      _renderServicoDependenciasPorCategoria();
      _renderServicoProcessosImpactados();
      _renderComposicaoServico();
    }
    showToast('✅ Salvo!', '#2e7d32');
    return true;
  } catch(e) {
    showToast('❌ ' + _mensagemErro(e), '#c62828');
    if (!aninhado && btnSalvarDep) btnSalvarDep.disabled = false;
    // Reverter (remove o registro temporário criado nesta operação)
    if (isNew && tempId) {
      dependenciasData = dependenciasData.filter(x => x.id !== tempId);
      _refreshAposSalvarDependencia();
    }
    return false;
  }
};

/**
 * Re-renderiza a lista da tela ativa depois de salvar/reverter uma dependência.
 * O drawer de dependência agora é usado tanto no Catálogo (#dependencias)
 * quanto na tela DRP (#drp) -- cada uma tem sua própria lista.
 */
function _refreshAposSalvarDependencia() {
  const page = (window.location.hash.slice(1).split('?')[0]) || '';
  if (page === 'drp') {
    if (typeof renderDRPListaComFiltro === 'function') renderDRPListaComFiltro();
  } else if (document.getElementById('depRows')) {
    renderizarDependencias();
  }
}

