/**
 * Popula o <select> de Servidor do Backup com as Dependências técnicas (as 7
 * categorias, igual ao catálogo usado pelo "+ Novo") a partir de
 * window.dependenciasCatalogo; usado na abertura e depois de cadastrar uma
 * dependência nova por cima.
 */
function _popularSelectBackupServidor(valorSelecionado) {
  const sel = document.getElementById('backupServidor');
  if (!sel) return;
  // Só a categoria técnica "Servidor" (uma das 7 de DEPENDENCIA_CATEGORIAS_TECNICAS)
  // -- não o catálogo técnico inteiro.
  const disponiveis = (window.dependenciasCatalogo || [])
    .filter((d) => d.categoria === 'Servidor')
    .sort((a, c) => (a.nome || '').localeCompare(c.nome || '', 'pt-BR'));
  sel.innerHTML = '<option value="">Selecione...</option>' +
    disponiveis.map((d) => `<option value="${esc(d.id)}">${esc(d.nome)}</option>`).join('');
  sel.value = valorSelecionado || '';
}

// ---- Jobs (mini-CRUD "item com várias colunas", mesmo padrão de Pessoas
// Associadas/Gestor do Contrato do Fornecedor e Plano de Ação/KRIs de Risco) ----

window._ajustarCamposJobAgenda = () => {
  const freq = document.getElementById('jobFrequencia').value;
  const box = document.getElementById('jobDiasSemanaBox');
  if (box) box.style.display = freq === 'Semanal' ? 'block' : 'none';
};

window.toggleJobDiaSemana = (dia) => {
  const set = new Set(window._jobDiasSemanaSelecionados || []);
  if (set.has(dia)) set.delete(dia); else set.add(dia);
  window._jobDiasSemanaSelecionados = [...set];
  document.querySelectorAll('.job-dia-chip').forEach((el) => {
    const d = Number(el.dataset.dia);
    const ativo = set.has(d);
    el.style.background = ativo ? '#d60014' : 'white';
    el.style.color = ativo ? 'white' : '#555';
    el.style.borderColor = ativo ? '#d60014' : '#e0e0e0';
  });
};

function _limparFormularioJob() {
  document.getElementById('jobFrequencia').value = 'Diário';
  document.getElementById('jobIntervalo').value = '1';
  document.getElementById('jobHorario').value = '';
  document.getElementById('jobTipo').value = 'Full';
  _avisarTipoJobBackup();
  document.getElementById('jobDuracaoValor').value = '';
  document.getElementById('jobDuracaoUnidade').value = 'horas';
  document.getElementById('jobRetencaoValor').value = '';
  document.getElementById('jobRetencaoUnidade').value = 'dias';
  document.getElementById('jobDestino').value = '';
  window._jobDiasSemanaSelecionados = [];
  document.querySelectorAll('.job-dia-chip').forEach((el) => { el.style.background = 'white'; el.style.color = '#555'; el.style.borderColor = '#e0e0e0'; });
  _ajustarCamposJobAgenda();
  window._backupJobEditando = null;
  const aviso = document.getElementById('jobEdicaoAviso');
  if (aviso) aviso.style.display = 'none';
  const btn = document.getElementById('btnAdicionarJob');
  if (btn) btn.textContent = '+ Adicionar';
}

window.cancelarEdicaoJob = () => { _limparFormularioJob(); };

function _lerFormularioJob() {
  return {
    agenda: {
      frequencia: document.getElementById('jobFrequencia').value,
      intervalo: Number(document.getElementById('jobIntervalo').value) || 1,
      diasSemana: [...(window._jobDiasSemanaSelecionados || [])],
    },
    horarioInicio: document.getElementById('jobHorario').value,
    tipo: document.getElementById('jobTipo').value,
    duracaoValor: document.getElementById('jobDuracaoValor').value ? Number(document.getElementById('jobDuracaoValor').value) : null,
    duracaoUnidade: document.getElementById('jobDuracaoUnidade').value,
    destino: document.getElementById('jobDestino').value.trim(),
    retencaoValor: document.getElementById('jobRetencaoValor').value ? Number(document.getElementById('jobRetencaoValor').value) : null,
    retencaoUnidade: document.getElementById('jobRetencaoUnidade').value,
  };
}

window.adicionarJob = async () => {
  const dados = _lerFormularioJob();
  if (!dados.horarioInicio) return showToast('Informe o horário de início.', '#e65100');
  // Nome do job e' sempre derivado dos metadados (nunca digitado à mão), pra
  // ficar estável e reconhecível quando outras telas forem referenciá-lo.
  dados.nome = _nomearJob(dados);
  window._backupJobs = window._backupJobs || [];
  if (window._backupJobEditando !== null && window._backupJobEditando !== undefined) {
    window._backupJobs[window._backupJobEditando] = { ...window._backupJobs[window._backupJobEditando], ...dados };
  } else {
    window._backupJobs.push({ id: _novoIdJob(), ...dados });
  }
  _limparFormularioJob();
  _renderBackupJobsTabela();
  // Cada job adicionado já grava o Backup inteiro (não só fica em memória até
  // clicar "Salvar") -- se os campos obrigatórios do Backup ainda não estiverem
  // preenchidos, _gravarBackupAtual avisa e o job fica só local até o próximo save.
  await comBotaoCarregando('btnAdicionarJob', async () => {
    const id = await _gravarBackupAtual();
    if (id) showToast('✅ Job salvo!', '#2e7d32');
  });
};

function _novoIdJob() { return 'job-' + Date.now() + '-' + Math.random().toString(36).slice(2, 7); }

/** Nome do job a partir dos próprios metadados: Tipo · Agenda · Horário. */
function _nomearJob(dados) {
  const nomeBackup = (document.getElementById('backupNome') || {}).value || '';
  const prefixo = nomeBackup.trim() ? nomeBackup.trim() + ' · ' : '';
  return `${prefixo}${dados.tipo} · ${_descreverAgendaJob(dados.agenda)} · ${dados.horarioInicio}`;
}

/** Joga um job no formulário da aba Jobs (usado por Editar e por Duplicar). */
function _preencherFormularioJob(job) {
  document.getElementById('jobFrequencia').value = job.agenda.frequencia;
  document.getElementById('jobIntervalo').value = job.agenda.intervalo;
  window._jobDiasSemanaSelecionados = [...(job.agenda.diasSemana || [])];
  document.querySelectorAll('.job-dia-chip').forEach((el) => {
    const d = Number(el.dataset.dia);
    const ativo = window._jobDiasSemanaSelecionados.includes(d);
    el.style.background = ativo ? '#d60014' : 'white';
    el.style.color = ativo ? 'white' : '#555';
    el.style.borderColor = ativo ? '#d60014' : '#e0e0e0';
  });
  _ajustarCamposJobAgenda();
  document.getElementById('jobHorario').value = job.horarioInicio || '';
  document.getElementById('jobTipo').value = job.tipo;
  _avisarTipoJobBackup();
  document.getElementById('jobDuracaoValor').value = job.duracaoValor != null ? job.duracaoValor : '';
  document.getElementById('jobDuracaoUnidade').value = job.duracaoUnidade || 'horas';
  document.getElementById('jobRetencaoValor').value = job.retencaoValor != null ? job.retencaoValor : '';
  document.getElementById('jobRetencaoUnidade').value = job.retencaoUnidade || 'dias';
  document.getElementById('jobDestino').value = job.destino || '';
}

window.editarJob = (idx) => {
  const job = (window._backupJobs || [])[idx];
  if (!job) return;
  _preencherFormularioJob(job);
  window._backupJobEditando = idx;
  document.getElementById('jobEdicaoAvisoTexto').textContent = '✎ Editando job';
  document.getElementById('jobEdicaoAviso').style.display = 'block';
  document.getElementById('btnAdicionarJob').textContent = 'Salvar alteração';
};

/** Duplicar: o formulário vem preenchido com a cópia; "+ Adicionar" cria um job novo (id e nome próprios). */
window.duplicarJob = (idx) => {
  const job = (window._backupJobs || [])[idx];
  if (!job) return;
  _limparFormularioJob();
  _preencherFormularioJob(job);
  document.getElementById('jobEdicaoAvisoTexto').textContent = '⧉ Copiando job — ajuste e clique em + Adicionar';
  document.getElementById('jobEdicaoAviso').style.display = 'block';
};

window.removerJob = (idx) => {
  window._backupJobs.splice(idx, 1);
  if (window._backupJobEditando === idx) _limparFormularioJob();
  _renderBackupJobsTabela();
};

/** Descrição curta da agenda pra exibir na tabela (ex.: "A cada 2 semana(s) (Seg, Qua)"). */
function _descreverAgendaJob(agenda) {
  const dias = ['Dom', 'Seg', 'Ter', 'Qua', 'Qui', 'Sex', 'Sáb'];
  const unidade = { 'Diário': 'dia(s)', 'Semanal': 'semana(s)', 'Mensal': 'mês(es)', 'Anual': 'ano(s)' }[agenda.frequencia] || '';
  let texto = agenda.intervalo > 1 ? `A cada ${agenda.intervalo} ${unidade}` : agenda.frequencia;
  if (agenda.frequencia === 'Semanal' && (agenda.diasSemana || []).length) {
    texto += ` (${[...agenda.diasSemana].sort().map((d) => dias[d]).join(', ')})`;
  }
  return texto;
}

function _renderBackupJobsTabela() {
  const cont = document.getElementById('backupJobsTabela');
  if (!cont) return;
  const jobs = window._backupJobs || [];
  _avisosModoBackup();
  if (!jobs.length) {
    cont.innerHTML = '<p class="vazio-inline">Nenhum job cadastrado ainda.</p>';
    return;
  }
  cont.innerHTML = `<table style="width:100%;border-collapse:collapse;font-size:0.88em;">
    <thead><tr>
      <th style="padding:8px 0;text-align:left;font-weight:600;color:#555;font-size:0.8em;border-bottom:1.5px solid #e0e0e0;">Nome</th>
      <th style="padding:8px 0;text-align:left;font-weight:600;color:#555;font-size:0.8em;border-bottom:1.5px solid #e0e0e0;">Horário</th>
      <th style="padding:8px 0;text-align:left;font-weight:600;color:#555;font-size:0.8em;border-bottom:1.5px solid #e0e0e0;">Tipo</th>
      <th style="padding:8px 0;text-align:left;font-weight:600;color:#555;font-size:0.8em;border-bottom:1.5px solid #e0e0e0;">Duração</th>
      <th style="padding:8px 0;text-align:left;font-weight:600;color:#555;font-size:0.8em;border-bottom:1.5px solid #e0e0e0;">Destino</th>
      <th style="padding:8px 0;text-align:left;font-weight:600;color:#555;font-size:0.8em;border-bottom:1.5px solid #e0e0e0;">Retenção</th>
      <th style="width:100px;border-bottom:1.5px solid #e0e0e0;"></th>
    </tr></thead>
    <tbody>
      ${jobs.map((j, i) => `<tr>
        <td style="padding:7px 0;border-bottom:1px solid #f5f5f5;">${esc(j.nome || _descreverAgendaJob(j.agenda))}</td>
        <td style="padding:7px 0;border-bottom:1px solid #f5f5f5;">${esc(j.horarioInicio || '-')}</td>
        <td style="padding:7px 0;border-bottom:1px solid #f5f5f5;">${esc(j.tipo || '-')}</td>
        <td style="padding:7px 0;border-bottom:1px solid #f5f5f5;">${j.duracaoValor != null ? esc(j.duracaoValor + ' ' + j.duracaoUnidade) : '-'}</td>
        <td style="padding:7px 0;border-bottom:1px solid #f5f5f5;">${esc(j.destino || '-')}</td>
        <td style="padding:7px 0;border-bottom:1px solid #f5f5f5;">${j.retencaoValor != null ? esc(j.retencaoValor + ' ' + j.retencaoUnidade) : '-'}</td>
        <td style="padding:7px 0;border-bottom:1px solid #f5f5f5;text-align:center;white-space:nowrap;">
          <button class="btn-icon" onclick="editarJob(${i})" title="Editar">
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#ff6b35" stroke-width="2"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"/></svg>
          </button>
          <button class="btn-icon" onclick="duplicarJob(${i})" title="Duplicar">
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#ff6b35" stroke-width="2"><rect x="9" y="9" width="13" height="13" rx="2" ry="2"/><path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"/></svg>
          </button>
          <button class="btn-icon" onclick="removerJob(${i})" title="Remover">
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#999" stroke-width="2"><polyline points="3 6 5 6 21 6"/><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/></svg>
          </button>
        </td>
      </tr>`).join('')}
    </tbody>
  </table>`;
}

/**
 * Monta o payload a partir do formulário e grava via API, sem fechar o drawer
 * nem mexer na aba ativa -- usado pelo botão "Salvar" (que fecha depois) e por
 * adicionarJob() (que fica na aba Jobs, salvando a cada job adicionado).
 * Devolve o id salvo, ou null se a validação falhar (toast já mostrado).
 */
async function _gravarBackupAtual() {
  const payload = _coletarFormularioBackup();
  if (!payload.nome) { _avisarCampo('backupNome', 'Informe o nome do backup.'); return null; }
  if (!payload.servicoIds.length) { _avisarCampo('backupServicoAdd', 'Vincule pelo menos um serviço.'); return null; }
  const id = payload.id;

  try {
    const r = await API.salvarBackup(payload);
    _edBackup.marcar({ ...payload, id: r.id });
    const item = { ...payload, id: r.id };
    const idx = backupsData.findIndex((x) => String(x.id) === String(r.id));
    if (idx >= 0) backupsData[idx] = item; else backupsData.push(item);
    // Backup novo passa a ter id real -- os próximos jobs adicionados (ou um
    // "Salvar" seguinte) atualizam o mesmo documento, em vez de criar outro.
    if (!id) {
      document.getElementById('backupId').value = r.id;
      document.getElementById('backupDrawerTitulo').textContent = 'Editar Backup';
    }
    if (document.getElementById('backupRows')) renderizarCatalogoBackup();
    return r.id;
  } catch (e) {
    showToast('❌ ' + _mensagemErro(e, 'Não foi possível salvar.'), '#c62828');
    return null;
  }
}

window.salvarBackup = async () => {
  return await comBotaoCarregando('btnSalvarBackup', async () => {
    const id = await _gravarBackupAtual();
    if (id) {
      if (_temDrawerPaiEmpilhado()) _fecharDrawerBackupSemSalvar();
      showToast('✅ Salvo!', '#2e7d32');
    }
    return !!id;
  });
};

/**
 * Clonar: abre um backup NOVO já preenchido com os dados e jobs de outro (ids
 * novos, nomes de job recalculados). Nada grava sozinho -- o rastreador marcou o
 * formulário em branco, então Salvar cria o documento e Fechar pergunta.
 * Stakeholder legado e datas de criação não vêm junto.
 */
window.clonarBackup = (id) => {
  const b = (backupsData || []).find((x) => String(x.id) === String(id));
  if (!b) return;
  abrirDrawerBackup();
  document.getElementById('backupNome').value = (b.nome || '') + ' (cópia)';
  document.getElementById('backupDescricao').value = b.descricao || '';
  window._backupServicoIds = [...(b.servicoIds || [])];
  _renderServicosBackup();
  _popularSelectBackupServidor(b.servidorId || '');
  _popularSelectFerramentaBackup(b.ferramentaId || '');
  document.getElementById('backupFerramentaOutra').value = b.ferramentaOutra || '';
  _ajustarFerramentaOutraBackup();
  document.getElementById('backupModo').value = b.modo || '';
  document.getElementById('backupEscopo').value = b.escopo || '';
  window._backupJobs = (b.jobs || []).map((j) => ({ ...JSON.parse(JSON.stringify(j)), id: _novoIdJob(), nome: j.agenda ? _nomearJob(j) : (j.nome || '') }));
  _renderBackupJobsTabela();
  _renderModoBackupChips();
  document.getElementById('backupDrawerTitulo').textContent = `Novo Backup (cópia de ${b.nome || 'backup'})`;
};

window.excluirBackup = async (id) => {
  const b = backupsData.find((x) => String(x.id) === String(id));
  if (!b) return;
  const nJobs = (b.jobs || []).length;
  if (!await confirmarAcao(`Excluir o backup "${b.nome}"?${nJobs ? ` Os ${nJobs} job(s) cadastrados nele também somem.` : ''} Esta ação não pode ser desfeita.`)) return;
  try {
    await API.excluirBackup(id);
    backupsData = backupsData.filter((x) => String(x.id) !== String(id));
    if (document.getElementById('backupRows')) renderizarCatalogoBackup();
    showToast('🗑️ Excluído.', '#555');
  } catch (e) {
    showToast('❌ ' + _mensagemErro(e, 'Não foi possível excluir.'), '#c62828');
  }
};

// ============================================================
// PÁGINA: VULNERABILIDADES
//
// Catálogo de vulnerabilidades reportadas (CVSS/CWE/CVE, status de correção).
// Severidade vem de vulnerabilidade-severidade.js (CVSS manda; severidade
// manual só é fallback quando CVSS não se aplica). A abertura/encerramento
// automático de Risco NÃO acontece aqui -- roda no servidor (Cloud Function
// riscoDeVulnerabilidade, igual ao risco automático de Fornecedor) sempre que
// o documento é salvo; esta tela só mostra, quando existir, um link pro risco
// já aberto.
// ============================================================
let vulnerabilidadesData = [];
let vulnerabilidadesOrdenacao = criarOrdenacao('codigo', 'desc');
const VULNERABILIDADES_POR_PAGINA = 20;
const vulnerabilidadesPaginacao = criarPaginacao(VULNERABILIDADES_POR_PAGINA);
// Selecao para edicao em lote / clonar (mesmo padrao de processosSelecionados).
// Sobrevive a filtro, ordenacao e troca de pagina.
let vulnerabilidadesSelecionadas = new Set();

const VULNERABILIDADE_STATUS_CORRECAO = ['Pendente', 'Em Correção', 'Corrigida', 'Aceita'];

/**
 * Tipo de Vulnerabilidade (DECISAO 15/10/2026): taxonomia FIXA em dois niveis
 * (Tipo -> Subtipo), alinhada a NIST/CIS/OWASP. O Tipo e obrigatorio no salvar;
 * o Subtipo e opcional. `tratativa` e so a dica mostrada no drawer (nao troca o
 * Responsavel). Mudar esta lista e decisao de produto: valor ja gravado que sair
 * dela continua visivel, marcado "(fora da lista)". O servidor so olha um valor
 * daqui: 'Não Conformidade' abre risco como "Regulatório/Legal"
 * (functions/vulnerabilidadeRisco.js).
 */
const VULNERABILIDADE_TIPOS = [
  { tipo: 'Não Conformidade', descricao: 'Violação de leis, regulações de mercado ou políticas internas de segurança e TI.',
    tratativa: 'Costuma exigir tratativa orçamentária ou jurídica, não só técnica.',
    subtipos: ['Licenciamento', 'LGPD/Privacidade', 'Política Interna', 'PCI-DSS', 'Outro'] },
  { tipo: 'Falha de Software (CVE / Bug)', descricao: 'Falhas técnicas e bugs no código de sistemas operacionais, binários ou bibliotecas de terceiros.',
    tratativa: 'Resolvida por Engenharia/Infra com patch ou atualização.',
    subtipos: ['CVE Conhecido', 'Zero-Day', 'Bug Interno', 'Biblioteca de Terceiros'] },
  { tipo: 'Má Configuração', descricao: 'Parâmetros de segurança configurados incorretamente ou mantidos no padrão inseguro.',
    tratativa: 'Resolvida por Engenharia/Infra com ajuste de configuração ou script.',
    subtipos: ['Exposição Pública (porta, bucket)', 'Senha/Credencial Padrão', 'Hardening Ausente', 'Outro'] },
  { tipo: 'Software Obsoleto / EOL', descricao: 'Sistemas ou componentes descontinuados pelo fabricante, sem suporte a correções.',
    tratativa: 'Costuma exigir orçamento ou projeto de migração — não há patch.',
    subtipos: ['Sistema Operacional', 'Linguagem/Runtime', 'Aplicação/Banco de Dados', 'Biblioteca/Componente'] },
  { tipo: 'Falha de Aplicação Web / API', descricao: 'Falhas na lógica ou implementação de sistemas desenvolvidos internamente (OWASP Top 10).',
    tratativa: 'Corrigida pelo time do produto (OWASP Top 10).',
    subtipos: ['Injeção (SQLi etc.)', 'XSS', 'Controle de Acesso Quebrado (BOLA/IDOR)', 'Exposição de Dados Sensíveis', 'Autenticação/Sessão', 'Lógica de Negócio', 'Outro'] },
  { tipo: 'Controle de Acesso / IAM', descricao: 'Fraquezas na gestão de identidade, privilégios excessivos ou governança de credenciais.',
    tratativa: 'Gestão de identidades: revisão de acessos e credenciais.',
    subtipos: ['Privilégio Excessivo', 'Conta Órfã/Ex-colaborador', 'Credencial sem Expiração/Rotação', 'Ausência de MFA', 'Outro'] },
  { tipo: 'Fraqueza de Arquitetura / Rede', descricao: 'Falhas estruturais no desenho do ambiente ou ausência de controles defensivos.',
    tratativa: 'Mudança estrutural no ambiente; costuma virar projeto.',
    subtipos: ['Segmentação Ausente', 'Criptografia Ausente (trânsito/repouso)', 'Controle Defensivo Ausente', 'Outro'] },
];

/**
 * Avaliacao de severidade alinhada ao Tipo (DECISAO 15/10/2026).
 *
 * `metodo` = o que aparece primeiro na aba Severidade; `cvss` = 'principal',
 * 'alternativa' (recolhido) ou 'nao-se-aplica' (nem aparece). `matriz` troca SO
 * o texto da matriz Impacto x Facilidade: perguntas, rotulos e explicacoes dos 4
 * niveis. Os CODIGOS gravados continuam os de Cvss31.IMPACTOS/FACILIDADES (por
 * posicao), entao severidadeCriterios ja gravado continua valido, a regua 4x4
 * (Cvss31.sugerirSeveridade) nao muda e trocar de tipo mantem o que foi marcado.
 * Tipo sem `matriz` usa o texto padrao de cvss31.js. A regra de calculo
 * (VulnerabilidadeSeveridade.faixa: CVSS manda) e o servidor nao mudam.
 *
 * `cwe`/`cve` (DECISAO 15/10/2026): se o campo aparece na Identificacao. CWE e
 * catalogo de FRAQUEZAS -- cobre quase toda falha tecnica, so nao Nao
 * Conformidade. CVE identifica falha PUBLICA de produto de TERCEIRO -- faz
 * sentido em Falha de Software, EOL e Ma Configuracao; codigo interno (Web/API),
 * IAM e Arquitetura nao recebem CVE. Campo que o tipo nao usa mas ja tem valor
 * continua visivel, com aviso e "Limpar" (_aplicarCamposPorTipoVuln).
 */
const VULNERABILIDADE_CONFIG_POR_TIPO = {
  'Falha de Software (CVE / Bug)': { metodo: 'cvss', cvss: 'principal', cwe: true, cve: true },
  'Falha de Aplicação Web / API': { metodo: 'cvss', cvss: 'principal', cwe: true, cve: false },
  'Má Configuração': { metodo: 'cvss', cvss: 'principal', cwe: true, cve: true },
  'Software Obsoleto / EOL': {
    metodo: 'matriz', cvss: 'alternativa', cwe: true, cve: true,
    porque: 'Sem patch do fabricante, o que pesa é quão crítico e quão exposto é o ativo. Se houver CVE conhecida, o CVSS dela pode ser informado.',
    matriz: {
      impacto: { pergunta: 'Quão crítico é o ativo obsoleto?', niveis: [
        { rotulo: 'Baixo', explicacao: 'Ativo de apoio ou isolado, sem dado sensível.' },
        { rotulo: 'Moderado', explicacao: 'Usado por parte dos processos, com alternativa.' },
        { rotulo: 'Alto', explicacao: 'Sustenta processo ou produto importante, ou guarda dado sensível.' },
        { rotulo: 'Grave', explicacao: 'Núcleo do produto/negócio ou dado sensível em larga escala.' },
      ] },
      facilidade: { pergunta: 'Quão exposto ele está?', niveis: [
        { rotulo: 'Isolado', explicacao: 'Rede restrita, sem CVE pública conhecida.' },
        { rotulo: 'Rede interna', explicacao: 'Alcançável a partir da rede corporativa.' },
        { rotulo: 'Internet ou CVE pública', explicacao: 'Exposto à internet ou com falha pública conhecida.' },
        { rotulo: 'Exploit ativo', explicacao: 'Há exploit público em uso ou já foi explorado.' },
      ] },
    },
  },
  'Controle de Acesso / IAM': {
    metodo: 'matriz', cvss: 'alternativa', cwe: true, cve: false,
    porque: 'Falha de gestão de acesso: o que pesa é o que o acesso indevido permite e quão fácil é usá-lo.',
    matriz: {
      impacto: { pergunta: 'O que o acesso indevido permite?', niveis: [
        { rotulo: 'Baixo', explicacao: 'Ler dado não sensível.' },
        { rotulo: 'Moderado', explicacao: 'Alterar dado interno ou de parte dos usuários.' },
        { rotulo: 'Alto', explicacao: 'Dado sensível ou funções administrativas de um sistema.' },
        { rotulo: 'Grave', explicacao: 'Administração de produção/domínio, vários sistemas ou dados de clientes.' },
      ] },
      facilidade: { pergunta: 'Quão fácil é usar esse acesso indevidamente?', niveis: [
        { rotulo: 'Difícil', explicacao: 'Exige credencial de outra pessoa e várias condições juntas.' },
        { rotulo: 'Possível', explicacao: 'Exige estar logado na rede interna ou em outro sistema.' },
        { rotulo: 'Fácil', explicacao: 'Credencial ativa sem MFA, ou conta de ex-colaborador ainda ativa.' },
        { rotulo: 'Muito fácil', explicacao: 'Credencial exposta/compartilhada ou acesso já sendo usado.' },
      ] },
    },
  },
  'Fraqueza de Arquitetura / Rede': {
    metodo: 'matriz', cvss: 'alternativa', cwe: true, cve: false,
    porque: 'Falha estrutural do ambiente: o que pesa é o alcance que ela dá a um atacante e quão exposto está o ponto fraco.',
    matriz: {
      impacto: { pergunta: 'O que um atacante alcança por causa dessa fraqueza?', niveis: [
        { rotulo: 'Baixo', explicacao: 'Ambiente de teste ou isolado.' },
        { rotulo: 'Moderado', explicacao: 'Parte da rede interna.' },
        { rotulo: 'Alto', explicacao: 'Ambiente de produção ou dados sensíveis.' },
        { rotulo: 'Grave', explicacao: 'Todo o ambiente, ou produção de clientes.' },
      ] },
      facilidade: { pergunta: 'Quão exposto está o ponto fraco?', niveis: [
        { rotulo: 'Só com acesso adm.', explicacao: 'Exige acesso administrativo ou físico.' },
        { rotulo: 'Rede interna', explicacao: 'Alcançável a partir da rede interna.' },
        { rotulo: 'Internet com esforço', explicacao: 'Alcançável pela internet, com algum esforço.' },
        { rotulo: 'Internet sem barreira', explicacao: 'Exposto à internet sem nenhum controle.' },
      ] },
    },
  },
  'Não Conformidade': {
    metodo: 'matriz', cvss: 'nao-se-aplica', cwe: false, cve: false,
    porque: 'Não é falha técnica explorável — o CVSS não se aplica. O que pesa é a exposição legal/regulatória e a chance de ser apontada.',
    matriz: {
      impacto: { pergunta: 'Qual a exposição legal, regulatória ou contratual?', niveis: [
        { rotulo: 'Baixo', explicacao: 'Desvio de política interna, sem efeito externo.' },
        { rotulo: 'Moderado', explicacao: 'Descumprimento de política ou contrato com efeito limitado e corrigível.' },
        { rotulo: 'Alto', explicacao: 'Pode gerar multa, sanção contratual ou expor dado pessoal (LGPD).' },
        { rotulo: 'Grave', explicacao: 'Sanção relevante (ANPD, órgão fiscalizador), multa alta ou processo judicial.' },
      ] },
      facilidade: { pergunta: 'Qual a chance de ser apontada (auditoria, fiscalização, cliente)?', niveis: [
        { rotulo: 'Improvável', explicacao: 'Só uma verificação muito específica encontraria.' },
        { rotulo: 'Possível', explicacao: 'Uma auditoria de rotina pode encontrar.' },
        { rotulo: 'Provável', explicacao: 'Visível para cliente, fornecedor ou fiscalização comum.' },
        { rotulo: 'Já apontada', explicacao: 'Já foi identificada por auditoria, cliente ou órgão externo.' },
      ] },
    },
  },
};

/** Quais identificadores tecnicos o tipo usa. Sem tipo (ou tipo fora da lista) = os dois, como antes. */
function _camposDoTipoVuln(tipo) {
  const cfg = VULNERABILIDADE_CONFIG_POR_TIPO[tipo];
  return cfg ? { cwe: cfg.cwe !== false, cve: cfg.cve !== false } : { cwe: true, cve: true };
}

/** Config de severidade do tipo, com o texto padrao da matriz quando o tipo nao define um. Sem tipo = null. */
function _configSeveridadeVuln(tipo) {
  const cfg = VULNERABILIDADE_CONFIG_POR_TIPO[tipo];
  if (!cfg) return null;
  const padrao = (lista) => lista.map((o) => ({ rotulo: o.codigo, explicacao: o.explicacao }));
  return {
    metodo: cfg.metodo,
    cvss: cfg.cvss,
    porque: cfg.porque || 'Falha técnica explorável: o CVSS 3.1 é a régua de mercado. Se ele não se aplicar a este caso, use a matriz.',
    matriz: cfg.matriz || {
      impacto: { pergunta: 'Qual o impacto se acontecer?', niveis: padrao(Cvss31.IMPACTOS) },
      facilidade: { pergunta: 'Quão fácil é acontecer?', niveis: padrao(Cvss31.FACILIDADES) },
    },
  };
}

/** Como a vulnerabilidade foi descoberta (o "quem reportou" continua em origemDeteccao, rotulo "Reportado por"). */
const VULNERABILIDADE_METODOS_DETECCAO = ['Scan Automatizado', 'Pentest', 'Threat Intelligence', 'Auditoria Interna', 'Auditoria Externa', 'Report Interno', 'Report de Cliente', 'Outro'];

function _tipoVulnerabilidade(tipo) {
  return VULNERABILIDADE_TIPOS.find((t) => t.tipo === tipo) || null;
}

/** Options de um select de lista fixa; valor gravado fora da lista fica visivel e marcado. */
function _optionsListaFixaVuln(lista, valorAtual, rotuloVazio) {
  const atual = valorAtual || '';
  return `<option value="">${esc(rotuloVazio)}</option>` +
    lista.map((x) => `<option value="${esc(x)}">${esc(x)}</option>`).join('') +
    (atual && !lista.includes(atual) ? `<option value="${esc(atual)}">${esc(atual)} (fora da lista)</option>` : '');
}

/** Celula "Tipo" da grade: tipo + subtipo em cinza; sem tipo = pill neutra "Não classificada". */
function _htmlCelulaTipoVuln(v) {
  if (!v.tipo) return '<span class="badge badge-gray">Não classificada</span>';
  return `<span title="${esc([v.tipo, v.subtipo].filter(Boolean).join(' · '))}">${esc(v.tipo)}${v.subtipo ? ` <span class="muted">· ${esc(v.subtipo)}</span>` : ''}</span>`;
}

/**
 * Próximo código "AAAA-NNN" (ano atual + sequencial de 3 dígitos), pra nunca
 * depender de alguém digitar/repetir um código à mão. Olha só os códigos do
 * ANO ATUAL já carregados em vulnerabilidadesData -- a sequência reinicia a
 * cada ano, igual o próprio histórico importado já fazia (2025-000x,
 * 2026-0xx). Só roda no SALVAR de um registro novo, nunca na edição.
 */
function _proximoCodigoVulnerabilidade() {
  const prefixo = new Date().getFullYear() + '-';
  const maior = (vulnerabilidadesData || [])
    .map((v) => v.codigo || '')
    .filter((c) => c.startsWith(prefixo))
    .map((c) => parseInt(c.slice(prefixo.length), 10))
    .filter((n) => Number.isFinite(n))
    .reduce((m, n) => Math.max(m, n), 0);
  return prefixo + String(maior + 1).padStart(3, '0');
}

/** Pill de workflow (status da correção), não é Badge de severidade -- mesma distinção já aplicada a _badgeStatusRisco. */
function _pillStatusCorrecaoVulnerabilidade(status) {
  const cores = {
    'Pendente': { cor: '#e65100', fundo: '#fff3e0' },
    'Em Correção': { cor: '#1565c0', fundo: '#e3f2fd' },
    'Corrigida': { cor: '#2e7d32', fundo: '#e8f5e9' },
    'Aceita': { cor: '#555', fundo: '#f0f0f0' },
  };
  const c = cores[status] || { cor: '#999', fundo: '#f5f5f5' };
  return `<span style="display:inline-block;padding:3px 10px;border-radius:10px;font-size:0.78em;font-weight:600;color:${c.cor};background:${c.fundo};">${esc(status || 'Não informado')}</span>`;
}

/** Dias corridos entre detecção e correção, só exibido -- nunca gravado (mesmo espírito do score do Risco não confiar em valor do cliente). */
function _tempoCorrecaoDias(dataDeteccao, dataCorrecao) {
  if (!dataDeteccao || !dataCorrecao) return null;
  const d1 = new Date(dataDeteccao + 'T00:00:00');
  const d2 = new Date(dataCorrecao + 'T00:00:00');
  if (isNaN(d1) || isNaN(d2)) return null;
  return Math.round((d2 - d1) / 86400000);
}

async function vulnerabilidades() {
  app.innerHTML = `
    ${_htmlCabecalhoLista({ titulo: 'Vulnerabilidades', sub: 'Catálogo de vulnerabilidades reportadas, com severidade e abertura automática de risco.',
      primario: { rotulo: '+ Nova vulnerabilidade', onclick: 'abrirDrawerVulnerabilidade()' },
      extra: `<button class="btn btn-ghost" onclick="abrirDrawerVulnerabilidadeLote()" id="btnEditarVulnLote" style="display:none;">Editar selecionadas</button>
        <button class="btn btn-ghost" onclick="clonarVulnerabilidadesSelecionadas()" id="btnClonarVulnSelecionadas" style="display:none;">Clonar selecionadas</button>
        <button class="btn btn-ghost" onclick="exportarVulnerabilidadesParaRiscos()" id="btnExportarVulnRiscos" style="display:none;">Exportar para Riscos</button>`,
      maisAcoes: [
        _seVeTela('vulnerabilidades-painel', 'x') ? { rotulo: 'Painel de Vulnerabilidades', onclick: "location.hash='#vulnerabilidades-painel'" } : null,
        { rotulo: 'Risco automático (limiar de CVSS)', onclick: 'abrirConfigLista()' },
      ] })}
    ${_htmlBarraLista({ busca: { id: 'buscaVulnerabilidade', placeholder: 'Buscar vulnerabilidade…' }, aoMudar: 'filtrarVulnerabilidadesBarra', contadorId: 'contadorVulnerabilidades',
      filtros: [
        { id: 'filtroVulnProduto', rotulo: 'Produto', todos: 'Todos', opcoes: [] },
        { id: 'filtroVulnSeveridade', rotulo: 'Severidade', opcoes: ['Crítica', 'Alta', 'Média', 'Baixa'].map((s) => [s, s]) },
        { id: 'filtroVulnStatus', rotulo: 'Correção', todos: 'Todas', opcoes: [...VULNERABILIDADE_STATUS_CORRECAO.map((s) => [s, s]), ['__atrasadas__', 'Atrasadas']] },
        { id: 'filtroVulnTipo', rotulo: 'Tipo', todos: 'Todos', opcoes: [...VULNERABILIDADE_TIPOS.map((x) => [x.tipo, x.tipo]), ['__sem_tipo__', 'Não classificada']] },
      ] })}
    <div id="vulnPainelExposicao"></div>
    ${_htmlDrawerConfigLista('Risco automático a partir de CVSS', 'vulnLimiarBox')}
    <div class="loading">⏳ Carregando...</div>
    <div class="data-table data-table--lista" id="listaVulnerabilidades" style="display:none;">
      <!-- 8 colunas que cabem em ~960px (23/10/2026): Tipo segue o nome na mesma
           célula; a data de detecção vai no title da Severidade. -->
      <table style="min-width:960px;">
        <colgroup>
          <col style="width:40px"><col style="width:96px"><col style="width:115px"><col style="width:200px"><col style="width:112px">
          <col style="width:135px"><col style="width:120px"><col style="width:110px">
        </colgroup>
        <thead>
          <tr>
            <th style="text-align:center;padding-left:6px;padding-right:6px;"><input type="checkbox" id="chkTodasVulnerabilidades" onchange="toggleTodasVulnerabilidades(this.checked)" title="Selecionar todas desta página"></th>
            <th onclick="ordenarVulnerabilidades('codigo')" style="cursor:pointer;">Código <span id="sort-vuln-codigo"></span></th>
            <th onclick="ordenarVulnerabilidades('produto')" style="cursor:pointer;">Produto <span id="sort-vuln-produto"></span></th>
            <th onclick="ordenarVulnerabilidades('nome')" style="cursor:pointer;" title="Nome e tipo">Vulnerabilidade <span id="sort-vuln-nome"></span></th>
            <th onclick="ordenarVulnerabilidades('severidade')" style="cursor:pointer;">Severidade <span id="sort-vuln-severidade"></span></th>
            <th onclick="ordenarVulnerabilidades('statusCorrecao')" style="cursor:pointer;">Correção <span id="sort-vuln-statusCorrecao"></span></th>
            <th>Responsável</th>
            <th class="col-acoes">Ações</th>
          </tr>
        </thead>
        <tbody id="vulnerabilidadeRows"></tbody>
      </table>
      <div id="vulnPaginacao"></div>
    </div>
    ${_htmlDrawerVulnerabilidade()}
    ${_htmlDrawerVulnerabilidadeLote()}`;

  try {
    const [vulnsList, riscosList, depsList, areasList, produtosList, cfgVuln] = await Promise.all([
      API.getVulnerabilidades(),
      API.getRiscos().catch((e) => { console.error('Vulnerabilidades: riscos não carregaram; link de "risco aberto" ficará indisponível', e); return riscosData || []; }),
      // Responsável (Pessoas) e Equipe (Áreas) da aba Correção. Se falharem, a
      // tela abre igual e os seletores mostram só o valor já gravado.
      API.getDependencias().catch((e) => { console.error('Vulnerabilidades: pessoas não carregaram', e); return null; }),
      API.getAreas().catch((e) => { console.error('Vulnerabilidades: áreas não carregaram', e); return null; }),
      // Catálogo de Produtos de Software (nome do produto vinculado). Se falhar,
      // a tela abre igual e mostra o texto do ativo afetado.
      API.getProdutosSoftware().catch((e) => { console.error('Vulnerabilidades: produtos não carregaram', e); return null; }),
      API.getConfigVulnerabilidade().catch(() => ({ limiarCvss: 7 })),
    ]);
    vulnerabilidadesData = vulnsList;
    vulnLimiarCvss = cfgVuln && Number.isFinite(Number(cfgVuln.limiarCvss)) ? Number(cfgVuln.limiarCvss) : 7;
    riscosData = riscosList;
    if (depsList) {
      pessoasData = depsList.filter((d) => d.categoria === 'Pessoas');
      _vulnDepsCatalogo = depsList.filter((d) => VULN_CATEGORIAS_DEPENDENCIA.includes(d.categoria));
    }
    if (areasList) window.areasData = areasList;
    if (produtosList) produtosSoftwareData = produtosList;
  } catch (e) {
    console.error('vulnerabilidades: falha ao carregar', e);
    document.querySelector('.loading').outerHTML = _htmlErroCarga('Não foi possível carregar as vulnerabilidades.', 'vulnerabilidades');
    return;
  }

  const produtosVuln = [...new Set(vulnerabilidadesData.map(_nomeProdutoVuln).filter(Boolean))].sort((a, b) => a.localeCompare(b, 'pt-BR'));
  _preencherFiltroLista('filtroVulnProduto', 'Produto', produtosVuln.map((p) => [p, p]), 'Todos');

  document.querySelector('.loading').style.display = 'none';
  document.getElementById('listaVulnerabilidades').style.display = 'block';
  vulnerabilidadesPaginacao.reiniciar();
  vulnerabilidadesSelecionadas = new Set();
  renderizarVulnerabilidades();
}

/**
 * Nome do produto para a grade/filtro/busca: o Produto de Software vinculado
 * (nome do catálogo, que acompanha renomeações) ou, sem vínculo, o texto antigo.
 */
function _nomeProdutoVuln(v) {
  const p = v && v.produtoSoftwareId ? _produtoSoftwarePorId(v.produtoSoftwareId) : null;
  if (p) return p.nome;
  if (v && v.produtoSoftwareId) return (v.produto || '').trim() || '(produto removido)';
  return ((v && v.produto) || '').trim();
}

/** Célula "Produto" da grade: nome do produto vinculado + "Ativo: …" em cinza (quando há os dois). */
/**
 * Dependencias afetadas (DECISAO 15/10/2026): substitui o texto livre "Ativo
 * afetado". Escolha em duas etapas (categoria -> item do catalogo de
 * Dependencias), varias por vulnerabilidade, vinculo por id ({id, categoria,
 * nome}, mesmo formato de dependenciaItens). So categorias tecnicas + Processos
 * Internos: Fornecedor e Pessoa ja tem cadastro e risco proprios. O texto antigo
 * (`produto`) fica como legado: visivel so leitura ate alguem limpar.
 */
const VULN_CATEGORIAS_DEPENDENCIA = ['Infraestrutura', 'Sistemas', 'Portais Web', 'Servidor', 'Banco de Dados', 'API', 'Segurança', 'Processos Internos'];
let _vulnDepsCatalogo = [];
window._vulnDependencias = [];

/** Nomes das dependencias afetadas (para grade, busca e risco). */
function _nomesDependenciasVuln(v) {
  return (Array.isArray(v && v.dependenciasAfetadas) ? v.dependenciasAfetadas : []).map((d) => d.nome).filter(Boolean);
}

/** Celula "Produto" da grade: produto vinculado + "Dependências: ..." (ou o texto legado) em cinza. */
function _htmlCelulaProdutoVuln(v) {
  const nome = _nomeProdutoVuln(v);
  const deps = _nomesDependenciasVuln(v);
  const ativo = ((v && v.produto) || '').trim();
  let linha = '';
  if (deps.length) linha = `Dependências: ${deps.join(', ')}`;
  else if (ativo && v.produtoSoftwareId && ativo.toLowerCase() !== nome.toLowerCase()) linha = `Ativo: ${ativo}`;
  if (!nome && !linha) return '-';
  // Uma linha só: o complemento (dependências ou ativo) segue depois de " · ".
  if (!linha) return esc(nome);
  return `${nome ? esc(nome) : '<span class="muted">—</span>'} <span class="muted" title="${esc(linha)}">· ${esc(linha)}</span>`;
}

function renderizarVulnerabilidades() {
  _renderPainelExposicaoVuln();
  const RANK_SEVERIDADE = { 'Crítica': 4, 'Alta': 3, 'Média': 2, 'Baixa': 1, 'Não informado': 0 };
  let data = [...vulnerabilidadesData];

  const busca = (document.getElementById('buscaVulnerabilidade') || {}).value || '';
  if (busca.trim()) {
    const termo = busca.toLowerCase();
    data = data.filter((v) =>
      (v.codigo || '').toLowerCase().includes(termo) ||
      _nomeProdutoVuln(v).toLowerCase().includes(termo) ||
      (v.produto || '').toLowerCase().includes(termo) ||
      _nomesDependenciasVuln(v).some((n) => n.toLowerCase().includes(termo)) ||
      (v.nome || '').toLowerCase().includes(termo) ||
      (v.cve || '').toLowerCase().includes(termo) ||
      (v.cwe || '').toLowerCase().includes(termo) ||
      (v.tipo || '').toLowerCase().includes(termo) ||
      (v.subtipo || '').toLowerCase().includes(termo));
  }
  const filtroTipo = (document.getElementById('filtroVulnTipo') || {}).value || '';
  if (filtroTipo) data = data.filter((v) => (filtroTipo === '__sem_tipo__' ? !v.tipo : v.tipo === filtroTipo));
  const filtroProduto = (document.getElementById('filtroVulnProduto') || {}).value || '';
  if (filtroProduto) data = data.filter((v) => _nomeProdutoVuln(v) === filtroProduto);
  const filtroSeveridade = (document.getElementById('filtroVulnSeveridade') || {}).value || '';
  if (filtroSeveridade) data = data.filter((v) => VulnerabilidadeSeveridade.faixa(v).rotulo === filtroSeveridade);
  const filtroStatus = (document.getElementById('filtroVulnStatus') || {}).value || '';
  if (filtroStatus === '__atrasadas__') data = data.filter(_vulnAtrasada);
  else if (filtroStatus) data = data.filter((v) => v.statusCorrecao === filtroStatus);

  data = vulnerabilidadesOrdenacao.aplicar(data, {
    produto: (a, b, dir) => dir * _nomeProdutoVuln(a).toLowerCase().localeCompare(_nomeProdutoVuln(b).toLowerCase(), 'pt-BR'),
    severidade: (a, b, dir) => dir * ((RANK_SEVERIDADE[VulnerabilidadeSeveridade.faixa(a).rotulo] || 0) - (RANK_SEVERIDADE[VulnerabilidadeSeveridade.faixa(b).rotulo] || 0)),
  });
  vulnerabilidadesOrdenacao.atualizarSetas('sort-vuln-', ['codigo', 'produto', 'nome', 'tipo', 'severidade', 'statusCorrecao', 'dataDeteccao']);

  _atualizarBarraLista('contadorVulnerabilidades', data.length, ['vulnerabilidade', 'vulnerabilidades']);

  const totalFiltrado = data.length;
  const pagInfo = vulnerabilidadesPaginacao.aplicar(data);
  const { totalPaginas, inicio } = pagInfo;
  const pagina = pagInfo.itens;

  document.getElementById('vulnerabilidadeRows').innerHTML = pagina.length
    ? pagina.map((v) => {
        const faixa = VulnerabilidadeSeveridade.faixa(v);
        const riscoAberto = (riscosData || []).find((r) => r.origem === 'Vulnerabilidade' && String(r.vulnerabilidadeId) === String(v.id) && r.status !== 'Encerrado');
        return `<tr style="cursor:pointer;" onclick="abrirDrawerVulnerabilidade('${esc(v.id)}')">
        <td class="col-c" onclick="event.stopPropagation();"><input type="checkbox" class="chk-vulnerabilidade" data-id="${esc(v.id)}" ${vulnerabilidadesSelecionadas.has(String(v.id)) ? 'checked' : ''} onchange="toggleVulnerabilidadeSelecionada('${escJs(v.id)}', this.checked)" aria-label="Selecionar"></td>
        ${_tdLista(v.codigo || '–', 'forte')}
        <td>${_htmlCelulaProdutoVuln(v)}</td>
        <td title="${esc([v.nome, v.tipo ? [v.tipo, v.subtipo].filter(Boolean).join(' · ') : 'Não classificada'].filter(Boolean).join(' — '))}">${esc(v.nome || '–')}${riscoAberto ? ` <a href="#riscos?risco=${esc(riscoAberto.id)}" onclick="event.stopPropagation();" class="badge badge-red" style="text-decoration:none;">${riscoAberto.status === 'Aceito' ? 'Risco aceito' : 'Risco aberto'}</a>` : ''} <span class="muted">· ${v.tipo ? esc([v.tipo, v.subtipo].filter(Boolean).join(' · ')) : 'Não classificada'}</span></td>
        <td title="${esc(v.dataDeteccao ? 'Detectada em ' + new Date(v.dataDeteccao + 'T00:00:00').toLocaleDateString('pt-BR') : '')}">${_htmlBadge(_nivelSeveridadeVulnerabilidade(faixa.rotulo), faixa.rotulo)}</td>
        <td>${_pillStatusCorrecaoVulnerabilidade(v.statusCorrecao)}${_vulnAtrasada(v) ? ' <span class="vuln-atrasada badge badge-red" title="Data prevista de correção já passou">Atrasada</span>' : ''}</td>
        ${_tdLista(v.responsavel || '–')}
        ${_htmlAcoesLinha([_acaoEditar(`abrirDrawerVulnerabilidade('${escJs(v.id)}')`), _acaoClonar(`clonarVulnerabilidade('${escJs(v.id)}')`), _acaoExcluir(`excluirVulnerabilidade('${escJs(v.id)}')`)])}
      </tr>`;
      }).join('')
    : `<tr><td colspan="8" class="vazio">${vulnerabilidadesData.length ? 'Nenhuma vulnerabilidade encontrada com esses filtros.' : 'Nenhuma vulnerabilidade cadastrada.'}</td></tr>`;
  _sincronizarSelecaoVulnerabilidades();

  const paginacao = document.getElementById('vulnPaginacao');
  if (paginacao) {
    paginacao.innerHTML = _htmlPaginacao(pagInfo, 'irParaPaginaVulnerabilidades');
  }
}

// ------------------------------------------------------------
// Exposicao e vinculo com o Registro de Riscos (DECISAO 15/10/2026, NIST):
// atraso de correcao, inconsistencias "acima do limiar sem risco" e o limiar
// configuravel (config_regua/vulnerabilidade, lido tambem pelo servidor).
// ------------------------------------------------------------
let vulnLimiarCvss = 7;
const _NOTA_POR_SEVERIDADE_VULN = { 'Crítica': 9.5, 'Alta': 7.5, 'Média': 5, 'Baixa': 2 };

/** Mesma "nota" do servidor (vulnerabilidadeRisco._nota): CVSS, ou valor representativo da severidade manual. */
function _notaVuln(v) {
  if (v && v.cvss !== null && v.cvss !== undefined && v.cvss !== '' && Number.isFinite(Number(v.cvss))) return Number(v.cvss);
  return _NOTA_POR_SEVERIDADE_VULN[v && v.severidadeManual] || null;
}

function _vulnEmAberto(v) {
  return !['Corrigida', 'Aceita'].includes(v && v.statusCorrecao);
}

/** Data prevista de correcao ja passou e a vulnerabilidade segue em aberto. */
function _vulnAtrasada(v) {
  const hoje = new Date().toISOString().slice(0, 10);
  return !!(v && v.dataPrevistaCorrecao && v.dataPrevistaCorrecao < hoje && _vulnEmAberto(v));
}

/** Acima do limiar, em aberto e sem risco ativo: o que o gatilho deveria ter coberto. */
function _vulnSemRiscoAcimaDoLimiar(v) {
  const nota = _notaVuln(v);
  return _vulnEmAberto(v) && nota !== null && nota >= vulnLimiarCvss && !_riscoAbertoDaVuln(v.id);
}

/**
 * Lista de Vulnerabilidades (23/10/2026): a exposição (em aberto por severidade,
 * atrasadas) está no Painel de Vulnerabilidades. Aqui fica só o aviso que pede
 * ação -- vulnerabilidade acima do limiar sem risco aberto, com o atalho para
 * selecioná-las -- e o limiar de CVSS, no drawer "Configurar".
 */
function _renderPainelExposicaoVuln() {
  const cont = document.getElementById('vulnPainelExposicao');
  const semRisco = (vulnerabilidadesData || []).filter(_vulnSemRiscoAcimaDoLimiar);
  if (cont) {
    cont.innerHTML = semRisco.length ? `<div class="lista-alerta">⚠️ Acima do limiar sem risco: ${semRisco.length}
      — vulnerabilidade com CVSS de ${vulnLimiarCvss} ou mais sem risco aberto no Registro.
      <button type="button" class="link-acao" onclick="selecionarVulnSemRisco()">Selecionar para exportar</button></div>` : '';
  }
  const box = document.getElementById('vulnLimiarBox');
  if (!box) return;
  const podeRegua = Perfis.podeEditarRegua(window.USER_PERFIS);
  box.innerHTML = `<div style="display:flex;flex-direction:column;gap:10px;font-size:0.9em;color:#555;">
      <span>Vulnerabilidade com CVSS a partir deste valor abre risco automaticamente no Registro de Riscos.</span>
      <span style="display:inline-flex;align-items:center;gap:8px;">Risco automático a partir de CVSS
        ${podeRegua
          ? `<input type="number" id="vulnLimiarCvss" min="0" max="10" step="0.1" value="${vulnLimiarCvss}" style="width:72px;padding:6px 8px;border:1px solid #ddd;border-radius:6px;">
             <button class="btn btn-ghost" onclick="salvarLimiarVulnerabilidade()">Salvar</button>`
          : `<strong>${vulnLimiarCvss}</strong>`}
      </span>
    </div>`;
}

window.filtrarVulnerabilidadesBarra = () => { vulnerabilidadesPaginacao.reiniciar(); renderizarVulnerabilidades(); };

window.selecionarVulnSemRisco = () => {
  (vulnerabilidadesData || []).filter(_vulnSemRiscoAcimaDoLimiar).forEach((v) => vulnerabilidadesSelecionadas.add(String(v.id)));
  renderizarVulnerabilidades();
};

window.salvarLimiarVulnerabilidade = async () => {
  const valor = Number(document.getElementById('vulnLimiarCvss').value);
  try {
    await API.salvarConfigVulnerabilidade({ limiarCvss: valor });
    vulnLimiarCvss = valor;
    renderizarVulnerabilidades();
    showToast('✅ Limiar salvo. Vale para as próximas edições e para a varredura diária.', '#2e7d32');
  } catch (e) {
    showToast('❌ ' + _mensagemErro(e, 'Não foi possível salvar.'), '#c62828');
  }
};

// ============================================================
// PÁGINA: PAINEL DE VULNERABILIDADES (visão executiva, 19/10/2026)
//
// Uma seção por pergunta da diretoria, na ordem: exposição, tendência, ação
// imediata, prazos, serviços e dados críticos. Toda a conta está em
// vulnerabilidade-painel.js (testada à parte); aqui só se desenha.
// Admin, Segurança e Gestor. O Gestor não vê a lista de Vulnerabilidades nem o
// Registro de Riscos inteiro: as linhas não levam ao drawer e o critério
// "acima do limiar sem risco" fica de fora para ele.
// ============================================================
let _painelVuln = null;
const _painelVulnFiltro = { produto: '', tipo: '', meses: 12 };
const _JANELA_PAINEL_VULN = 90;
const _COR_PAINEL_VULN = { total: CATEGORIA_CORES[0], criticasAltas: CATEGORIA_CORES[2], novas: CATEGORIA_CORES[3], corrigidas: CATEGORIA_CORES[9] };

async function vulnerabilidadesPainel() {
  app.innerHTML = `
    <div class="page-header">
      <div><h2>Painel de Vulnerabilidades</h2><p class="page-sub">Visão executiva da gestão de vulnerabilidades: exposição, tendência, ação imediata, prazos e processos críticos</p></div>
      <div style="display:flex;gap:8px;">
        ${_seVeTela('vulnerabilidades-relatorio', '<button class="btn btn-ghost" onclick="location.hash=\'#vulnerabilidades-relatorio\'">📄 Relatório</button>')}
        ${_seVeTela('vulnerabilidades', '<button class="btn btn-ghost" onclick="location.hash=\'#vulnerabilidades\'">Ver lista de vulnerabilidades</button>')}
      </div>
    </div>
    <div class="filters">
      <div class="field">
        <label class="field-label" for="painelVulnProduto">Produto</label>
        <select id="painelVulnProduto" class="field-control" onchange="filtrarPainelVulnerabilidades()"><option value="">Todos</option></select>
      </div>
      <div class="field">
        <label class="field-label" for="painelVulnTipo">Tipo</label>
        <select id="painelVulnTipo" class="field-control" onchange="filtrarPainelVulnerabilidades()">
          <option value="">Todos</option>
          ${VULNERABILIDADE_TIPOS.map((t) => `<option value="${esc(t.tipo)}">${esc(t.tipo)}</option>`).join('')}
          <option value="__sem_tipo__">Não classificada</option>
        </select>
      </div>
      <div class="field">
        <label class="field-label" for="painelVulnMeses">Período da tendência</label>
        <select id="painelVulnMeses" class="field-control" onchange="filtrarPainelVulnerabilidades()">
          <option value="12">Últimos 12 meses</option>
          <option value="6">Últimos 6 meses</option>
        </select>
      </div>
    </div>
    <div class="loading">⏳ Carregando...</div>
    <div id="painelVulnConteudo" class="painel-exec"></div>`;

  const podeVerLista = Perfis.podeVerTela(window.USER_PERFIS, 'vulnerabilidades');
  try {
    const [vulns, processos, produtos, cfg, fotos, riscos, rede0] = await Promise.all([
      API.getVulnerabilidades(),
      API.getProcessos().catch((e) => { console.error('Painel de Vulnerabilidades: processos não carregaram', e); return null; }),
      API.getProdutosSoftware().catch(() => null),
      API.getConfigVulnerabilidade().catch(() => ({ limiarCvss: 7 })),
      API.getFotosPainelVulnerabilidades().catch((e) => { console.error('Painel de Vulnerabilidades: fotos mensais não carregaram; a tendência fica só reconstruída', e); return []; }),
      // O Gestor só lê os riscos da própria área (regra do banco): sem a lista
      // inteira, o critério "acima do limiar sem risco" mentiria para ele.
      podeVerLista ? API.getRiscos().catch(() => null) : Promise.resolve(null),
      _carregarRedeDeDependencias(),
    ]);
    if (produtos) produtosSoftwareData = produtos;
    _painelVuln = {
      vulns: vulns || [],
      processos,
      rede: rede0,
      fotos: fotos || [],
      riscos,
      limiar: cfg && Number.isFinite(Number(cfg.limiarCvss)) ? Number(cfg.limiarCvss) : 7,
      podeVerLista,
    };
  } catch (e) {
    console.error('Painel de Vulnerabilidades: falha ao carregar', e);
    document.querySelector('.loading').outerHTML = _htmlErroCarga('Não foi possível carregar as vulnerabilidades.', 'vulnerabilidadesPainel');
    return;
  }
  document.querySelector('.loading').style.display = 'none';

  const selProduto = document.getElementById('painelVulnProduto');
  const nomes = [...new Set(_painelVuln.vulns.map(_nomeProdutoVuln).filter(Boolean))].sort((a, b) => a.localeCompare(b, 'pt-BR'));
  selProduto.innerHTML = '<option value="">Todos</option>' + nomes.map((n) => `<option value="${esc(n)}">${esc(n)}</option>`).join('');
  selProduto.value = nomes.includes(_painelVulnFiltro.produto) ? _painelVulnFiltro.produto : '';
  document.getElementById('painelVulnTipo').value = _painelVulnFiltro.tipo;
  document.getElementById('painelVulnMeses').value = String(_painelVulnFiltro.meses);
  renderizarPainelVulnerabilidades();
}

window.filtrarPainelVulnerabilidades = () => {
  _painelVulnFiltro.produto = document.getElementById('painelVulnProduto').value;
  _painelVulnFiltro.tipo = document.getElementById('painelVulnTipo').value;
  _painelVulnFiltro.meses = Number(document.getElementById('painelVulnMeses').value) || 12;
  renderizarPainelVulnerabilidades();
};

function _vulnsDoPainelFiltradas() {
  const f = _painelVulnFiltro;
  return _painelVuln.vulns.filter((v) => {
    if (f.produto && _nomeProdutoVuln(v) !== f.produto) return false;
    if (f.tipo === '__sem_tipo__') return !v.tipo;
    if (f.tipo && v.tipo !== f.tipo) return false;
    return true;
  });
}

function renderizarPainelVulnerabilidades() {
  const cont = document.getElementById('painelVulnConteudo');
  if (!cont || !_painelVuln) return;
  if (!_painelVuln.vulns.length) {
    cont.innerHTML = _htmlVazio('Nenhuma vulnerabilidade cadastrada ainda.', 'O painel se preenche conforme as vulnerabilidades forem registradas.');
    return;
  }
  const vulns = _vulnsDoPainelFiltradas();
  if (!vulns.length) {
    cont.innerHTML = _htmlVazio('Nenhuma vulnerabilidade com estes filtros.', 'Troque o produto ou o tipo para ver o painel.');
    return;
  }
  const VP = VulnerabilidadePainel;
  const comFiltro = !!(_painelVulnFiltro.produto || _painelVulnFiltro.tipo);
  // A foto mensal é da empresa inteira: com filtro, a série é só reconstruída.
  const serie = VP.serieMensal(vulns, { meses: _painelVulnFiltro.meses, fotos: comFiltro ? [] : _painelVuln.fotos });
  const janelas = VP.janelas(null, _JANELA_PAINEL_VULN);
  cont.innerHTML = [
    _htmlPainelVulnExposicao(vulns, serie),
    _htmlPainelVulnTendencia(vulns, serie, janelas, comFiltro),
    _htmlPainelVulnAcao(vulns),
    _htmlPainelVulnPrazos(vulns, janelas),
    _htmlPainelVulnCriticos(vulns),
  ].join('');
}

function _secaoPainelVuln(numero, pergunta, referencia) {
  return `<div class="painel-pergunta"><span class="painel-pergunta__num">${numero}</span>${esc(pergunta)}<span class="painel-pergunta__ref">${esc(referencia)}</span></div>`;
}

/** "+3 vs. set/26" -- variação do valor de hoje contra o fechamento do mês anterior. */
function _tendenciaPainelVuln(atual, anterior, campo) {
  if (!anterior) return '';
  const d = atual - anterior[campo];
  const mes = VulnerabilidadePainel.rotuloMes(anterior.mes);
  if (d === 0) return `Igual a ${mes}`;
  return `${d > 0 ? '▲ +' : '▼ '}${d} vs. ${mes}`;
}

function _barraPainelVuln(pct, cor) {
  return `<div class="barra"><div class="barra__valor" style="width:${Math.max(0, Math.min(100, pct))}%;background:${cor};"></div></div>`;
}

function _corSeveridadeVuln(s) {
  return s === VulnerabilidadePainel.SEM_SEVERIDADE ? 'var(--border-strong)' : VulnerabilidadeSeveridade.faixa({ severidadeManual: s }).cor;
}

// ---- 1. Exposição atual ----
function _htmlPainelVulnExposicao(vulns, serie) {
  const VP = VulnerabilidadePainel;
  const e = VP.exposicao(vulns);
  const anterior = serie.length > 1 ? serie[serie.length - 2] : null;
  const nivelCA = e.porSeveridade['Crítica'] ? 'critical' : (e.porSeveridade['Alta'] ? 'high' : null);
  const aceitasCA = e.aceitasPorSeveridade['Crítica'] + e.aceitasPorSeveridade['Alta'];
  const linhas = VP.SEVERIDADES.concat(e.semSeveridade ? [VP.SEM_SEVERIDADE] : []).map((s) => {
    const n = e.porSeveridade[s];
    const cor = _corSeveridadeVuln(s);
    return `<div class="painel-linha">
        <span class="painel-linha__rotulo">${esc(s)}</span>${_barraPainelVuln(e.abertas ? (n / e.abertas) * 100 : 0, cor)}
        <span class="painel-linha__valor num">${n}</span>
      </div>`;
  }).join('');
  const produtos = VP.porProduto(vulns, _nomeProdutoVuln).slice(0, 8);
  const maiorIndice = produtos.length ? produtos[0].indice || 1 : 1;
  const linhasProduto = produtos.map((p) => `<div class="painel-linha">
        <span class="painel-linha__rotulo painel-linha__rotulo--longo" title="${esc(p.nome)}">${esc(p.nome)}</span>${_barraPainelVuln((p.indice / maiorIndice) * 100, 'var(--red)')}
        <span class="painel-linha__valor num" title="Índice ${p.indice}">${p.total}</span>
      </div>`).join('');
  return `
    ${_secaoPainelVuln(1, 'Qual é a exposição atual?', 'NIST CSF 2.0 · ID.RA-01')}
    <div class="painel-metricas">
      ${_htmlMetricCard({ label: 'Em aberto', value: e.abertas, trend: _tendenciaPainelVuln(e.abertas, anterior, 'abertas') })}
      ${_htmlMetricCard({ label: 'Críticas + Altas em aberto', value: e.criticasAltas, level: nivelCA, trend: _tendenciaPainelVuln(e.criticasAltas, anterior, 'criticasAltas') })}
      ${_htmlMetricCard({ label: 'Índice de exposição', value: e.indice, trend: _tendenciaPainelVuln(e.indice, anterior, 'indice') || 'Crítica 10 · Alta 5 · Média 2 · Baixa 1' })}
      ${_htmlMetricCard({ label: 'Aceitas (risco assumido)', value: e.aceitas, trend: aceitasCA ? `${aceitasCA} Crítica${aceitasCA === 1 ? '' : 's'} ou Alta${aceitasCA === 1 ? '' : 's'}` : '' })}
    </div>
    <div class="painel-colunas">
      <div class="painel-card">
        <div class="painel-card__titulo">Em aberto por severidade</div>
        <div class="painel-card__sub">Pendentes e em correção. Severidade pelo CVSS (faixas NVD) ou, sem CVSS, a escolhida na avaliação</div>
        ${e.abertas ? linhas : '<div class="vazio-inline">Nenhuma vulnerabilidade em aberto.</div>'}
      </div>
      <div class="painel-card">
        <div class="painel-card__titulo">Produtos mais expostos</div>
        <div class="painel-card__sub">Barra pelo índice de exposição; número = vulnerabilidades em aberto</div>
        ${linhasProduto || '<div class="vazio-inline">Nenhuma vulnerabilidade em aberto.</div>'}
      </div>
    </div>`;
}

// ---- 2. Tendência ----
function _htmlPainelVulnTendencia(vulns, serie, janelas, comFiltro) {
  const VP = VulnerabilidadePainel;
  window._painelVulnSerie = serie;
  const atual = VP.mttr(vulns, janelas.atual.de, janelas.atual.ate);
  const antes = VP.mttr(vulns, janelas.anterior.de, janelas.anterior.ate);
  const mov = VP.movimento(vulns, janelas.atual.de, janelas.atual.ate);
  const reconstruidos = serie.filter((p) => p.fonte === 'reconstruida').length;
  // Tempo de correção: subir é piorar (▲ vermelho), cair é melhorar (▼ verde).
  let variacaoMttr = '';
  if (atual.media !== null && antes.media !== null && atual.media !== antes.media) {
    const piorou = atual.media > antes.media;
    variacaoMttr = `<div class="painel-card__sub" style="margin:4px 0 0;color:${piorou ? '#c62828' : '#2e7d32'};">${piorou ? '▲' : '▼'} ${Math.abs(atual.media - antes.media)} dia${Math.abs(atual.media - antes.media) === 1 ? '' : 's'} vs. os ${_JANELA_PAINEL_VULN} dias anteriores (${antes.media})</div>`;
  }
  const mttrSev = VP.SEVERIDADES.filter((s) => atual.porSeveridade[s])
    .map((s) => `${_htmlBadge(_nivelSeveridadeVulnerabilidade(s), s)} <span class="num">${atual.porSeveridade[s].media} dia${atual.porSeveridade[s].media === 1 ? '' : 's'}</span> <span class="muted">(${atual.porSeveridade[s].n})</span>`)
    .join('&nbsp;&nbsp; ');
  const legenda = (itens) => itens.map(([nome, cor]) => `<span class="painel-legenda"><span class="painel-legenda__cor" style="background:${cor};"></span>${esc(nome)}</span>`).join('');
  return `
    ${_secaoPainelVuln(2, 'Estamos melhorando ou piorando?', 'NIST SP 800-40 · SP 800-55')}
    <div class="painel-colunas">
      <div class="painel-card">
        <div class="painel-card__titulo">Backlog em aberto no fim de cada mês</div>
        <div class="painel-card__sub">Linha caindo = exposição diminuindo</div>
        ${_svgPainelVulnBacklog(serie)}
        <div style="margin-top:8px;">${legenda([['Total em aberto', _COR_PAINEL_VULN.total], ['Críticas + Altas', _COR_PAINEL_VULN.criticasAltas]])}</div>
      </div>
      <div class="painel-card">
        <div class="painel-card__titulo">Entradas × saídas por mês</div>
        <div class="painel-card__sub">Corrigidas acima das novas = o time está vencendo o backlog</div>
        ${_svgPainelVulnMovimento(serie)}
        <div style="margin-top:8px;">${legenda([['Novas (detectadas)', _COR_PAINEL_VULN.novas], ['Corrigidas', _COR_PAINEL_VULN.corrigidas]])}</div>
      </div>
    </div>
    ${reconstruidos ? `<div class="painel-nota">${reconstruidos === serie.length - 1 && !comFiltro ? 'Os meses anteriores' : `${reconstruidos} ${reconstruidos === 1 ? 'mês foi reconstruído' : 'meses foram reconstruídos'}`} pelas datas de detecção e correção, com a severidade de hoje${comFiltro ? ' (com filtro, a série é sempre reconstruída: a foto mensal é da empresa inteira)' : '. A partir de agora, a varredura diária grava o fechamento de cada mês'}.</div>` : ''}
    <div class="painel-card">
      <div class="painel-card__titulo">Velocidade de correção — últimos ${_JANELA_PAINEL_VULN} dias</div>
      <div class="painel-card__sub">Tempo médio de correção (MTTR) = da detecção até a correção</div>
      <div class="painel-kpis">
        <div class="painel-kpi">
          <div class="painel-kpi__rotulo">Tempo médio de correção</div>
          <div class="painel-kpi__valor num">${atual.media !== null ? `${atual.media} dia${atual.media === 1 ? '' : 's'}` : '–'}</div>
          ${atual.n ? `<div class="painel-card__sub" style="margin:4px 0 0;">${atual.n} corrigida${atual.n === 1 ? '' : 's'} no período</div>` : '<div class="painel-card__sub" style="margin:4px 0 0;">Nenhuma corrigida no período</div>'}
          ${variacaoMttr}
        </div>
        <div class="painel-kpi">
          <div class="painel-kpi__rotulo">Taxa de fechamento</div>
          <div class="painel-kpi__valor num" style="color:${mov.taxaFechamento === null ? 'inherit' : (mov.taxaFechamento >= 100 ? '#2e7d32' : '#c62828')};">${mov.taxaFechamento !== null ? mov.taxaFechamento + '%' : '–'}</div>
          <div class="painel-card__sub" style="margin:4px 0 0;">${mov.corrigidas} corrigida${mov.corrigidas === 1 ? '' : 's'} para ${mov.novas} nova${mov.novas === 1 ? '' : 's'}</div>
        </div>
        <div class="painel-kpi">
          <div class="painel-kpi__rotulo">Saldo do backlog</div>
          <div class="painel-kpi__valor num" style="color:${mov.saldo > 0 ? '#c62828' : (mov.saldo < 0 ? '#2e7d32' : 'inherit')};">${mov.saldo > 0 ? '+' : ''}${mov.saldo}</div>
          <div class="painel-card__sub" style="margin:4px 0 0;">${mov.saldo > 0 ? 'Entrou mais do que saiu' : (mov.saldo < 0 ? 'Saiu mais do que entrou' : 'Entradas e saídas empatadas')}</div>
        </div>
      </div>
      ${mttrSev ? `<div style="margin-top:14px;font-size:13px;">Por severidade: ${mttrSev}</div>` : ''}
    </div>`;
}

/** Geometria comum dos dois gráficos mensais (mesmo tamanho, mesmos rótulos de mês). */
function _eixosPainelVuln(serie, maxValor, estatico) {
  const L = 600, A = 220, M = { topo: 14, baixo: 30, esq: 36, dir: 10 };
  const areaW = L - M.esq - M.dir, areaH = A - M.topo - M.baixo;
  const max = Math.max(1, maxValor) * 1.15;
  const n = serie.length;
  const passoX = areaW / n;
  const xCentro = (i) => M.esq + passoX * i + passoX / 2;
  const y = (v) => M.topo + areaH - (areaH * v) / max;
  let grade = '';
  for (let f = 0; f <= 4; f++) {
    const v = Math.round((max / 4) * f);
    grade += `<line x1="${M.esq}" y1="${y(v)}" x2="${L - M.dir}" y2="${y(v)}" stroke="#eee" stroke-width="1"/>`
      + `<text x="${M.esq - 6}" y="${y(v) + 4}" text-anchor="end" font-size="10" fill="#999">${v}</text>`;
  }
  const rotulos = serie.map((p, i) => `<text x="${xCentro(i)}" y="${A - M.baixo + 16}" text-anchor="middle" font-size="10" fill="#999">${esc(VulnerabilidadePainel.rotuloMes(p.mes))}</text>`).join('');
  // Alvo de hover por mês: a coluna inteira, transparente (mesma classe do
  // Monitor, para o toque fora fechar a dica). No relatório impresso
  // (`estatico`) não há dica: a aba nova não tem estas funções.
  const alvos = estatico ? '' : serie.map((p, i) => `<rect class="ponto-monitor-hit" x="${M.esq + passoX * i}" y="${M.topo}" width="${passoX}" height="${areaH}" fill="transparent" style="cursor:pointer;" onmouseenter="_mostrarDicaPainelVuln(event,${i})" onmouseleave="_esconderDicaMonitor()" onclick="_mostrarDicaPainelVuln(event,${i})"/>`).join('');
  const moldura = `<line x1="${M.esq}" y1="${M.topo}" x2="${M.esq}" y2="${A - M.baixo}" stroke="#ccc"/><line x1="${M.esq}" y1="${A - M.baixo}" x2="${L - M.dir}" y2="${A - M.baixo}" stroke="#ccc"/>`;
  return { L, A, passoX, xCentro, y, base: A - M.baixo, fundo: grade + rotulos + moldura, alvos };
}

function _svgPainelVulnBacklog(serie, estatico) {
  const g = _eixosPainelVuln(serie, Math.max(...serie.map((p) => p.abertas)), estatico);
  const linha = (campo, cor) => {
    const pontos = serie.map((p, i) => `${g.xCentro(i)},${g.y(p[campo])}`).join(' ');
    return (serie.length > 1 ? `<polyline points="${pontos}" fill="none" stroke="${cor}" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"/>` : '')
      + serie.map((p, i) => `<circle cx="${g.xCentro(i)}" cy="${g.y(p[campo])}" r="3" fill="${p.fonte === 'reconstruida' ? '#fff' : cor}" stroke="${cor}" stroke-width="1.5"/>`).join('');
  };
  return `<svg viewBox="0 0 ${g.L} ${g.A}" style="width:100%;height:auto;display:block;" role="img" aria-label="Backlog de vulnerabilidades em aberto por mês">
    ${g.fundo}${linha('abertas', _COR_PAINEL_VULN.total)}${linha('criticasAltas', _COR_PAINEL_VULN.criticasAltas)}${g.alvos}
  </svg>`;
}

function _svgPainelVulnMovimento(serie, estatico) {
  const g = _eixosPainelVuln(serie, Math.max(...serie.map((p) => Math.max(p.novas, p.corrigidas))), estatico);
  const larg = Math.min(16, g.passoX * 0.32);
  const barra = (x, v, cor) => (v > 0 ? `<rect x="${x}" y="${g.y(v)}" width="${larg}" height="${g.base - g.y(v)}" fill="${cor}" rx="2"/>` : '');
  const barras = serie.map((p, i) => barra(g.xCentro(i) - larg - 1, p.novas, _COR_PAINEL_VULN.novas) + barra(g.xCentro(i) + 1, p.corrigidas, _COR_PAINEL_VULN.corrigidas)).join('');
  return `<svg viewBox="0 0 ${g.L} ${g.A}" style="width:100%;height:auto;display:block;" role="img" aria-label="Vulnerabilidades novas e corrigidas por mês">
    ${g.fundo}${barras}${g.alvos}
  </svg>`;
}

/** HTML da dica de um mês (texto de VulnerabilidadePainel.linhasDicaMes, escapado). */
function _conteudoDicaPainelVuln(ponto) {
  const [titulo, ...linhas] = VulnerabilidadePainel.linhasDicaMes(ponto);
  return `<div style="font-weight:700;color:var(--ink);">${esc(titulo)}</div>`
    + linhas.map((l) => `<div style="margin-top:3px;">${esc(l)}</div>`).join('');
}

window._mostrarDicaPainelVuln = (ev, i) => {
  const ponto = (window._painelVulnSerie || [])[i];
  if (!ponto) return;
  const el = _dicaMonitorEl();
  el.innerHTML = _conteudoDicaPainelVuln(ponto);
  _posicionarDicaGrafico(el, ev);
};

// ---- 3. Ação imediata ----
const _NIVEL_MOTIVO_PAINEL_VULN = {
  'Crítica': 'critical', 'Processo Tier 1': 'critical', 'Alta com exploit': 'high', 'Atrasada': 'high', 'Acima do limiar sem risco': 'medium',
};
const _LIMITE_ACAO_PAINEL_VULN = 10;

function _htmlPainelVulnAcao(vulns) {
  const VP = VulnerabilidadePainel;
  const d = _painelVuln;
  const riscoAberto = d.riscos
    ? (id) => d.riscos.some((r) => r.origem === 'Vulnerabilidade' && String(r.vulnerabilidadeId) === String(id) && r.status !== 'Encerrado')
    : null;
  const itens = VP.acaoImediata(vulns, { processos: d.processos || [], rede: d.rede, limiar: d.limiar, riscoAberto });
  const criterios = 'Em aberto e: Crítica, Alta com exploit disponível, prazo vencido, atinge processo Tier 1'
    + (riscoAberto ? `, ou severidade no limiar de risco (${d.limiar}) sem risco aberto` : '');
  const linhas = itens.slice(0, _LIMITE_ACAO_PAINEL_VULN).map((it) => {
    const v = it.v;
    const sev = VP.severidade(v);
    const clicavel = d.podeVerLista;
    const motivos = it.motivos.map((m) => {
      const rot = m === VP.MOTIVO.ATRASADA ? `Atrasada ${it.diasAtraso}d` : m;
      return _htmlBadge(_NIVEL_MOTIVO_PAINEL_VULN[m] || null, rot);
    }).join(' ');
    return `<tr${clicavel ? ` style="cursor:pointer;" onclick="location.hash='#vulnerabilidades?vuln=${escJs(String(v.id))}'" title="Abrir a vulnerabilidade"` : ''}>
        <td class="num">${esc(v.codigo || '–')}</td>
        <td class="title">${esc(v.nome || '–')}<div class="muted" style="font-size:12px;">${esc(_nomeProdutoVuln(v) || 'Sem produto')}</div></td>
        <td>${_htmlBadge(_nivelSeveridadeVulnerabilidade(sev), sev)}</td>
        <td>${motivos}</td>
        <td>${_pillStatusCorrecaoVulnerabilidade(v.statusCorrecao)}</td>
        <td>${esc(v.responsavel || v.equipeResponsavel || '–')}${v.responsavel && v.equipeResponsavel ? `<div class="muted" style="font-size:12px;">${esc(v.equipeResponsavel)}</div>` : ''}</td>
      </tr>`;
  }).join('');
  const resto = itens.length - _LIMITE_ACAO_PAINEL_VULN;
  return `
    ${_secaoPainelVuln(3, 'Quais vulnerabilidades exigem ação imediata?', 'NIST SP 800-40 · priorização')}
    <div class="painel-card">
      <div class="painel-card__titulo">Ação imediata ${itens.length ? `<span class="muted" style="font-weight:400;">· ${itens.length}</span>` : ''}</div>
      <div class="painel-card__sub">${esc(criterios)}. Ordem: gravidade, processo crítico e dias de atraso</div>
      ${itens.length ? `<div class="data-table data-table--compact">
        <table>
          <colgroup><col style="width:90px"><col><col style="width:110px"><col style="width:300px"><col style="width:130px"><col style="width:170px"></colgroup>
          <thead><tr><th>Código</th><th>Vulnerabilidade</th><th>Severidade</th><th>Por quê</th><th>Status</th><th>Responsável</th></tr></thead>
          <tbody>${linhas}</tbody>
        </table>
      </div>
      ${resto > 0 ? `<div class="painel-nota" style="margin:10px 0 0;">E mais ${resto} vulnerabilidade${resto === 1 ? '' : 's'} nestes critérios.</div>` : ''}`
    : _htmlVazio('Nada exige ação imediata.', 'Nenhuma vulnerabilidade em aberto atende aos critérios acima.')}
    </div>`;
}

// ---- 4. Prazos ----
function _htmlPainelVulnPrazos(vulns, janelas) {
  const VP = VulnerabilidadePainel;
  const cp = VP.cumprimentoPrazo(vulns, janelas.atual.de, janelas.atual.ate);
  const at = VP.atraso(vulns);
  const equipes = VP.porEquipe(vulns, janelas.atual.de, janelas.atual.ate);
  const pctCor = (p) => (p === null ? 'inherit' : p >= 80 ? '#2e7d32' : p >= 50 ? '#f57c00' : '#c62828');
  const linhas = equipes.map((e) => `<tr>
      <td class="title">${esc(e.equipe)}</td>
      <td class="col-c num">${e.abertas}</td>
      <td class="col-c num"${e.atrasadas ? ' style="color:#c62828;font-weight:700;"' : ''}>${e.atrasadas || '–'}</td>
      <td class="col-c num"${e.semPrazo ? ' style="color:#e65100;"' : ''}>${e.semPrazo || '–'}</td>
      <td class="col-c num">${e.corrigidas || '–'}</td>
      <td class="col-c num" style="color:${pctCor(e.pctNoPrazo)};font-weight:600;">${e.pctNoPrazo !== null ? e.pctNoPrazo + '%' : '–'}</td>
      <td class="col-c num">${e.mttr !== null ? e.mttr + ' d' : '–'}</td>
    </tr>`).join('');
  return `
    ${_secaoPainelVuln(4, 'As equipes estão corrigindo dentro dos prazos?', 'NIST SP 800-40 · SP 800-55')}
    <div class="painel-metricas">
      ${_htmlMetricCard({ label: `Corrigidas no prazo (${_JANELA_PAINEL_VULN} dias)`, value: cp.pct !== null ? cp.pct + '%' : '–', trend: cp.comPrazo ? `${cp.noPrazo} de ${cp.comPrazo} com data prevista` : 'Nenhuma corrigida com data prevista' })}
      ${_htmlMetricCard({ label: 'Atrasadas hoje', value: at.atrasadas, level: at.atrasadas ? 'high' : null, trend: at.atrasadas ? `Atraso médio ${at.diasMedio} dia${at.diasMedio === 1 ? '' : 's'} · maior ${at.diasMaximo}` : '' })}
      ${_htmlMetricCard({ label: 'Em aberto sem prazo definido', value: at.semPrazo, trend: at.pctSemPrazo !== null ? `${at.pctSemPrazo}% das em aberto` : '' })}
      ${_htmlMetricCard({ label: `Corrigidas sem data prevista (${_JANELA_PAINEL_VULN} dias)`, value: cp.semPrazoDefinido, trend: 'Fora do percentual de prazo' })}
    </div>
    ${at.semPrazo ? `<div class="painel-nota">O prazo é a Data Prevista de Correção de cada vulnerabilidade. Sem ela, não há como medir atraso: ${at.semPrazo} em aberto ainda não têm prazo.</div>` : ''}
    <div class="painel-card">
      <div class="painel-card__titulo">Por equipe responsável</div>
      <div class="painel-card__sub">Backlog e atraso de hoje; corrigidas, % no prazo e tempo médio de correção nos últimos ${_JANELA_PAINEL_VULN} dias</div>
      ${equipes.length ? `<div class="data-table data-table--compact">
        <table>
          <thead><tr><th>Equipe</th><th class="col-c">Em aberto</th><th class="col-c">Atrasadas</th><th class="col-c">Sem prazo</th><th class="col-c">Corrigidas</th><th class="col-c">% no prazo</th><th class="col-c">Tempo médio</th></tr></thead>
          <tbody>${linhas}</tbody>
        </table>
      </div>` : '<div class="vazio-inline">Nenhuma equipe com vulnerabilidades em aberto ou corrigidas no período.</div>'}
    </div>`;
}

// ---- 5. Serviços e dados críticos ----
function _htmlPainelVulnCriticos(vulns) {
  const VP = VulnerabilidadePainel;
  const d = _painelVuln;
  const T = Criticidade.TIER;
  const dados = VP.exposicaoDados(vulns);
  const sv = VP.semVinculo(vulns);
  let blocoProcessos;
  if (!d.processos) {
    blocoProcessos = `<div class="painel-card">${_htmlErroCarga('Não foi possível carregar os processos de negócio.', 'vulnerabilidadesPainel')}</div>`;
  } else {
    const exp = VP.processosExpostos(vulns, d.processos, d.rede);
    const totalProc = exp.processos.length;
    const linhasTier = [T.T1, T.T2, T.T3, T.PENDENTE].map((t) => {
      const n = exp.porTier[t] || 0;
      const cor = t === T.PENDENTE ? 'var(--border-strong)' : Criticidade.corDoTier(t);
      return `<div class="painel-linha">
          <span class="painel-linha__rotulo">${esc(t === T.PENDENTE ? 'Pendente (sem BIA)' : t)}</span>${_barraPainelVuln(totalProc ? (n / totalProc) * 100 : 0, cor)}
          <span class="painel-linha__valor num">${n}</span>
        </div>`;
    }).join('');
    const criticos = exp.processos.filter((p) => p.tier === T.T1 || p.tier === T.T2);
    const linhasCriticos = criticos.map((p) => `<tr>
        <td class="title">${esc(p.processo)}</td>
        <td class="muted">${esc(p.area || '–')}</td>
        <td>${_htmlBadge(_nivelTierProcesso(p.tier), Criticidade.tierCurto(p.tier))}</td>
        <td class="col-c num">${p.total}</td>
        <td>${_htmlBadge(_nivelSeveridadeVulnerabilidade(p.piorSeveridade), p.piorSeveridade)}</td>
      </tr>`).join('');
    blocoProcessos = `
      <div class="painel-colunas">
        <div class="painel-card">
          <div class="painel-card__titulo">Processos de negócio expostos</div>
          <div class="painel-card__sub">Processos que dependem de algum ativo afetado por vulnerabilidade em aberto, por Tier do BIA</div>
          ${totalProc ? linhasTier : '<div class="vazio-inline">Nenhum processo atingido pelas vulnerabilidades em aberto.</div>'}
          ${sv.total ? `<div class="painel-nota" style="margin:12px 0 0;">⚠ ${sv.total} em aberto (${sv.pct}%) sem dependência vinculada — o impacto delas nos processos não aparece aqui.</div>` : ''}
        </div>
        <div class="painel-card">
          <div class="painel-card__titulo">Exposição legal e de dados pessoais</div>
          <div class="painel-card__sub">Em aberto com subtipo LGPD/Privacidade, ou Não Conformidade com exposição legal Alta ou Grave</div>
          <div class="painel-kpis" style="grid-template-columns:1fr 1fr;">
            <div class="painel-kpi"><div class="painel-kpi__rotulo">Total</div><div class="painel-kpi__valor num"${dados.total ? ' style="color:#c62828;"' : ''}>${dados.total}</div></div>
            <div class="painel-kpi"><div class="painel-kpi__rotulo">LGPD / Privacidade</div><div class="painel-kpi__valor num">${dados.lgpd}</div></div>
          </div>
          ${dados.vulnerabilidades.slice(0, 5).map((v) => `<div class="painel-linha" style="margin-top:10px;"><span class="num" style="width:70px;flex-shrink:0;">${esc(v.codigo || '–')}</span><span style="flex:1;font-size:13px;">${esc(v.nome || '–')}</span>${_htmlBadge(_nivelSeveridadeVulnerabilidade(VP.severidade(v)), VP.severidade(v))}</div>`).join('')}
        </div>
      </div>
      <div class="painel-card">
        <div class="painel-card__titulo">Processos críticos atingidos (Tier 1 e Tier 2)</div>
        <div class="painel-card__sub">Pela cadeia vulnerabilidade → dependência afetada → processo do BIA, mais crítico primeiro</div>
        ${criticos.length ? `<div class="data-table data-table--compact">
          <table>
            <colgroup><col><col style="width:200px"><col style="width:100px"><col style="width:120px"><col style="width:170px"></colgroup>
            <thead><tr><th>Processo</th><th>Área</th><th>Tier</th><th class="col-c">Em aberto</th><th>Pior severidade</th></tr></thead>
            <tbody>${linhasCriticos}</tbody>
          </table>
        </div>` : '<div class="vazio-inline">Nenhum processo Tier 1 ou Tier 2 atingido por vulnerabilidade em aberto.</div>'}
      </div>`;
  }
  return `
    ${_secaoPainelVuln(5, 'Existe risco relevante para os serviços e dados críticos?', 'NIST CSF 2.0 · ID.RA-04 / GV.RM')}
    ${blocoProcessos}`;
}

window.ordenarVulnerabilidades = (coluna) => { vulnerabilidadesOrdenacao.ordenar(coluna); vulnerabilidadesPaginacao.reiniciar(); renderizarVulnerabilidades(); };
window.irParaPaginaVulnerabilidades = (delta) => { vulnerabilidadesPaginacao.mover(delta); renderizarVulnerabilidades(); };

// ------------------------------------------------------------
// Selecao, edicao em lote e clonar (DECISAO 15/10/2026) -- mesmo padrao de
// Processos de Negocio. "Marcar todas" cobre as linhas da PAGINA visivel.
// ------------------------------------------------------------
function _sincronizarSelecaoVulnerabilidades() {
  const chks = [...document.querySelectorAll('#vulnerabilidadeRows .chk-vulnerabilidade')];
  const chkTodas = document.getElementById('chkTodasVulnerabilidades');
  if (chkTodas) {
    const todas = chks.length > 0 && chks.every((el) => vulnerabilidadesSelecionadas.has(el.dataset.id));
    chkTodas.checked = todas;
    chkTodas.indeterminate = !todas && chks.some((el) => vulnerabilidadesSelecionadas.has(el.dataset.id));
  }
  const n = vulnerabilidadesSelecionadas.size;
  [['btnEditarVulnLote', 'Editar selecionadas'], ['btnClonarVulnSelecionadas', 'Clonar selecionadas'], ['btnExportarVulnRiscos', 'Exportar para Riscos']].forEach(([id, rotulo]) => {
    const btn = document.getElementById(id);
    if (!btn) return;
    btn.style.display = n > 0 ? 'inline-block' : 'none';
    btn.textContent = n > 0 ? `${rotulo} (${n})` : rotulo;
  });
}

window.toggleVulnerabilidadeSelecionada = (id, checked) => {
  if (checked) vulnerabilidadesSelecionadas.add(String(id)); else vulnerabilidadesSelecionadas.delete(String(id));
  _sincronizarSelecaoVulnerabilidades();
};

window.toggleTodasVulnerabilidades = (checked) => {
  document.querySelectorAll('#vulnerabilidadeRows .chk-vulnerabilidade').forEach((el) => {
    const id = el.dataset.id;
    if (!id) return;
    if (checked) vulnerabilidadesSelecionadas.add(id); else vulnerabilidadesSelecionadas.delete(id);
    el.checked = checked;
  });
  _sincronizarSelecaoVulnerabilidades();
};

/**
 * Copia de uma vulnerabilidade para virar um registro novo. Copia o que descreve
 * a falha (produto, nome, CVSS/CWE/CVE, severidade, origem, responsavel...) e
 * ZERA o que e do ciclo de vida do registro original: codigo (novo), data de
 * deteccao (hoje), status (Aberto) e tudo da correcao.
 */
function _copiaDeVulnerabilidade(v, codigo, hoje) {
  return {
    id: null,
    codigo,
    ticketReport: v.ticketReport || '',
    produto: v.produto || '',
    produtoSoftwareId: v.produtoSoftwareId || '',
    dependenciasAfetadas: (Array.isArray(v.dependenciasAfetadas) ? v.dependenciasAfetadas : []).map((d) => ({ id: d.id || null, categoria: d.categoria || '', nome: d.nome || '' })),
    versao: v.versao || '',
    nome: `${v.nome || ''} (cópia)`,
    cwe: v.cwe || '',
    cve: v.cve || '',
    cvss: v.cvss != null && v.cvss !== '' ? Number(v.cvss) : null,
    severidadeManual: v.severidadeManual || '',
    cvssVetor: v.cvssVetor || '',
    severidadeCriterios: {
      impacto: (v.severidadeCriterios && v.severidadeCriterios.impacto) || '',
      facilidade: (v.severidadeCriterios && v.severidadeCriterios.facilidade) || '',
    },
    descricao: v.descricao || '',
    dataDeteccao: hoje,
    origemDeteccao: v.origemDeteccao || '',
    tipo: v.tipo || '',
    subtipo: v.subtipo || '',
    metodoDeteccao: v.metodoDeteccao || '',
    exploitDisponivel: v.exploitDisponivel || '',
    equipeResponsavel: v.equipeResponsavel || '',
    responsavel: v.responsavel || '',
    ticketCorrecao: '',
    statusCorrecao: 'Pendente',
    dataPrevistaCorrecao: '',
    dataCorrecao: '',
    evidenciaCorrecao: '',
    observacoes: v.observacoes || '',
  };
}

/** Icone da linha: abre o drawer ja preenchido, sem id, para revisar antes de salvar. */
window.clonarVulnerabilidade = (id) => {
  const original = vulnerabilidadesData.find((x) => String(x.id) === String(id));
  if (!original) return;
  abrirDrawerVulnerabilidade(_copiaDeVulnerabilidade(original, _proximoCodigoVulnerabilidade(), new Date().toISOString().slice(0, 10)));
};

/** Botao do cabecalho: cria as copias direto, uma a uma (o codigo sequencial depende da anterior). */
window.clonarVulnerabilidadesSelecionadas = async () => {
  const ids = [...vulnerabilidadesSelecionadas];
  if (!ids.length) return;
  // Tipo e obrigatorio: copiar uma nao classificada criaria outra nao classificada.
  const semTipo = ids.map((id) => vulnerabilidadesData.find((x) => String(x.id) === id)).filter((v) => v && !v.tipo);
  if (semTipo.length) {
    return showToast(`Classifique o Tipo antes de clonar: ${semTipo.map((v) => v.codigo || v.id).join(', ')}.`, '#e65100');
  }
  if (!await confirmarAcao(`Criar ${ids.length} cópia(s)? Cada uma recebe código novo e status Pendente; se a severidade cruzar o limiar, um risco é aberto automaticamente, como em qualquer vulnerabilidade nova.`)) return;

  await comBotaoCarregando('btnClonarVulnSelecionadas', async () => {
    const hoje = new Date().toISOString().slice(0, 10);
    const codigos = [];
    const erros = [];
    for (const id of ids) {
      const original = vulnerabilidadesData.find((x) => String(x.id) === String(id));
      if (!original) continue;
      const copia = _copiaDeVulnerabilidade(original, _proximoCodigoVulnerabilidade(), hoje);
      try {
        const r = await API.salvarVulnerabilidade(copia);
        vulnerabilidadesData.push({ ...copia, id: r.id });
        codigos.push(copia.codigo);
      } catch (e) {
        erros.push(`${original.codigo || id}: ${e.message || 'erro desconhecido'}`);
      }
    }
    vulnerabilidadesSelecionadas = new Set();
    vulnerabilidadesPaginacao.reiniciar();
    renderizarVulnerabilidades();
    if (!erros.length) {
      showToast(`✅ ${codigos.length} cópia(s) criada(s): ${codigos[0]}${codigos.length > 1 ? ' a ' + codigos[codigos.length - 1] : ''}.`, '#2e7d32');
    } else {
      showToast(`⚠️ ${codigos.length} de ${ids.length} cópia(s) criada(s). Erro em: ${erros.join('; ')}`, '#e65100');
    }
  });
};

/** Risco automatico/manual ainda aberto desta vulnerabilidade (mesma regra do link "Risco aberto" da grade). */
function _riscoAbertoDaVuln(id) {
  return (riscosData || []).find((r) => r.origem === 'Vulnerabilidade' && String(r.vulnerabilidadeId) === String(id) && r.status !== 'Encerrado');
}

/**
 * "Exportar para Riscos" das selecionadas (DECISAO 15/10/2026): a mesma acao de
 * servidor da exportacao individual do drawer (importarVulnerabilidadeParaRisco),
 * uma por vez. Pula antes de chamar o servidor quem ja tem risco aberto; o
 * servidor tambem nao duplica (jaExiste). Como na individual, ignora limiar e
 * status da correcao -- o confirm avisa quantas estao Corrigida/Aceita.
 */
window.exportarVulnerabilidadesParaRiscos = async () => {
  const selecionadas = [...vulnerabilidadesSelecionadas]
    .map((id) => vulnerabilidadesData.find((x) => String(x.id) === id)).filter(Boolean);
  if (!selecionadas.length) return;
  const comRisco = selecionadas.filter((v) => _riscoAbertoDaVuln(v.id));
  const aExportar = selecionadas.filter((v) => !_riscoAbertoDaVuln(v.id));
  if (!aExportar.length) {
    return showToast(`Todas as ${selecionadas.length} selecionada(s) já têm risco aberto no Registro de Riscos.`, '#e65100');
  }
  const fechadas = aExportar.filter((v) => ['Corrigida', 'Aceita'].includes(v.statusCorrecao)).length;
  const msg = `Criar risco no Registro de Riscos para ${aExportar.length} vulnerabilidade(s)?`
    + (comRisco.length ? `\n\n${comRisco.length} já têm risco aberto e serão puladas.` : '')
    + (fechadas ? `\n\n${fechadas} estão Corrigida/Aceita — o risco será criado mesmo assim (como na exportação individual).` : '');
  if (!await confirmarAcao(msg)) return;

  await comBotaoCarregando('btnExportarVulnRiscos', async () => {
    let criados = 0;
    let jaExistiam = comRisco.length;
    const erros = [];
    for (const v of aExportar) {
      try {
        const r = await API.post('importarVulnerabilidadeParaRisco', { id: v.id });
        if (r && r.jaExiste) jaExistiam++; else criados++;
      } catch (e) {
        erros.push(`${v.codigo || v.id}: ${e.message || 'erro desconhecido'}`);
      }
    }
    try {
      API.invalidate('getRiscos');
      riscosData = await API.getRiscos();
    } catch (e) { /* a grade so perde o link "Risco aberto" ate recarregar */ }
    vulnerabilidadesSelecionadas = new Set();
    renderizarVulnerabilidades();
    const resumo = `${criados} risco(s) criado(s)${jaExistiam ? `, ${jaExistiam} já existiam` : ''}`;
    if (!erros.length) showToast(`✅ ${resumo}.`, '#2e7d32');
    else showToast(`⚠️ ${resumo}. Erro em: ${erros.join('; ')}`, '#e65100');
  });
};

